/// 🎥️ The addressed window's retained pose, or `None` while it has never been orbited — a render
/// that reads `None` falls back to the model-derived camera plus `fit_json`'s one-shot framing.
pub fn current<'a, C>(view: &'a semio_framework_plugin::ConfigView<'_, C>) -> Option<&'a EnergyModelWindowConfig> {
    view.window::<EnergyModelWindowConfigOwner>()
}

/// 🪟️ Binds one config mutation to the EXACT window instance the gesture came from — a camera is
/// per instance, so a dispatch with no addressed window, or one addressed at another window kind, is
/// a refusal rather than a write to the wrong pane.
pub fn addressed(view: &semio_framework_plugin::ViewModel, mutation: EnergyModelWindowConfigMutation) -> Result<semio_framework_plugin::WindowConfigMutation, semio_framework_plugin::Fault> {
    let window_id = view
        .window_id
        .as_deref()
        .ok_or_else(|| semio_framework_plugin::Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("energy.model.3d.window-required"), "a camera change requires a concrete 3d model window"))?;
    let kind = view.window_instances.iter().find(|window| window.id == window_id).map(|window| window.window_kind_id.as_str());
    if kind != Some(super::WINDOW_KIND_ID) {
        return Err(semio_framework_plugin::Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("energy.model.3d.window-kind"), "a camera change requires a 3d model window"));
    }
    Ok(semio_framework_plugin::WindowConfigMutation::of::<EnergyModelWindowConfigOwner>(window_id, mutation))
}

