//#region 🔖️OpText
/// ✂️ Local DSL-only mirror of `DagMutation` — every real variant flattened into its own keyworded
/// record, converted at the `store::OpText` boundary only; `DagMutation` itself, and every consumer
/// matching on it, is completely untouched. `DagNodeSpec` (whole node, for `create-node`),
/// `DagNodeKind` (`replace-node-kind`) and `PropertyBag` (`replace-node-properties`,
/// `connect-nodes`'s edge properties) don't have a clean DSL scalar shape, so they round-trip as an
/// opaque `dsl::json`-encoded (`ToValue`/`FromValue`, not `serde_json`) string field here — a
/// documented deviation, not a silent one.
#[derive(Clone, Debug, PartialEq, dsl::DslEnum)]
enum DagMutationDsl {
    CreateNode { node_json: String, index: Option<usize> },
    DeleteNode { id: String },
    RenameNode { id: String, new_id: String },
    ChangeNodeName { id: String, new_name: String },
    MoveNode { id: String, x: f64, y: f64 },
    ResizeNode { id: String, width: f64, height: f64 },
    ChangeNodeIcon { id: String, new_icon: String },
    ChangeNodeAbbreviation { id: String, new_abbreviation: String },
    ChangeNodeOperatorKind { id: String, new_operator_kind: Option<String> },
    ReplaceNodeKind { id: String, new_kind_json: String },
    ReplaceNodeProperties { id: String, new_properties_json: String },
    ReorderNodes { order: Vec<String> },
    ConnectNodes { id: String, source: String, target: String, route_style: EdgeRouteStyle, properties_json: String, index: Option<usize> },
    DisconnectNodes { id: String },
    MoveNodes { ids: Vec<String>, dx: f64, dy: f64 },
    SetNodePositions { positions_json: String },
    SetSlider {
        id: String,
        #[dsl(key = "field")]
        slider_field: DagSliderField,
        value: f64,
    },
}

//#region 🔖️HandcraftedOpCodecs
/// ⚡️ P6 handcrafted OpText/OpBinary (derive no longer emits these traits).
impl OpText for DagMutationDsl {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        let variants = <Self as dsl::DslVariants>::variants();
        for (keyword, spec_fn) in &variants {
            let probe = format!("{} ", keyword);
            if line == keyword.as_str() || line.starts_with(&probe) {
                let record = dsl::parse(line, &(spec_fn.ordinary)(), &dsl::ParseOptions { limits: semio_framework_diagnostic::Limits::default(), mode: dsl::SourceMode::Inline })?;
                return <Self as dsl::DslVariants>::from_named_record(keyword, &record);
            }
        }
        Err(dsl::__rt::field_error(format!("unknown mutation line '{line}'")))
    }
    fn print_op(&self) -> String {
        let (keyword, record) = <Self as dsl::DslVariants>::to_named_record(self);
        let variants = <Self as dsl::DslVariants>::variants();
        let spec_fn = variants.iter().find(|(k, _)| k == &keyword).map(|(_, s)| *s).expect("variant spec must exist for its own keyword");
        dsl::print(&record, &(spec_fn.ordinary)(), dsl::JoinMode::Inline)
    }
}

