pub fn default_fem2d_snapshot() -> crate::Fem2dSnapshot {
    match <crate::Fem2dSnapshot as store::ArtifactDsl>::parse_dsl(crate::standards::v1::subsets::any::schema::snapshot::text::FEM2D_EXAMPLE_TEXT) {
