                snapshot.nodes.len(),
                snapshot.elements.len(),
                snapshot.regions.len(),
                snapshot.materials.len(),
                snapshot.sections.len(),
                snapshot.supports.len(),
                snapshot.load_cases.len(),
                snapshot.combinations.len()
