fn class(v: f64) -> &'static str {
    if v.is_nan() {
        "nan"
    } else if v == f64::INFINITY {
        "positiveInfinity"
    } else if v == f64::NEG_INFINITY {
        "negativeInfinity"
    } else {
        "finite"
    }
}
fn text(v: &Option<String>) -> Cell<'_> {
    v.as_deref().map(Cell::Text).unwrap_or(Cell::Null)
}
fn ordinal(n: usize) -> Result<Cell<'static>, String> {
    Ok(Cell::Integer(i64::try_from(n).map_err(|e| e.to_string())?))
}
struct Cells<'a> {
    values: [Cell<'a>; 32],
    len: usize,
}
impl<'a> Cells<'a> {
    fn new(values: &[Cell<'a>]) -> Self {
        let mut out = Self { values: [Cell::Null; 32], len: 0 };
        for value in values {
            out.push(*value);
        }
        out
    }
    fn push(&mut self, v: Cell<'a>) {
        self.values[self.len] = v;
        self.len += 1;
    }
    fn float(&mut self, v: f64) {
        self.push(if v.is_nan() { Cell::Null } else { Cell::Real(v) });
        self.push(Cell::Integer(v.to_bits() as i64));
        self.push(Cell::Text(class(v)));
    }
    fn optional(&mut self, v: Option<f64>) {
        if let Some(v) = v {
            self.float(v);
        } else {
            self.push(Cell::Null);
            self.push(Cell::Null);
            self.push(Cell::Null);
        }
    }
    fn insert(&self, out: &mut Projection<'_, '_>, table: usize) -> Result<i64, String> {
        out.insert(TABLES[table].0, &self.values[..self.len])
    }
}
fn add(total: &mut usize, count: usize, c: &SqliteSnapshotControl<'_>) -> Result<(), String> {
    *total = total.checked_add(count).ok_or("Block row count overflow")?;
    c.check_rows(*total)
}
fn admit_schema(c: &SqliteSnapshotControl<'_>) -> Result<(), String> {
    let size = TABLES.iter().try_fold(SQL.len(), |sum, (name, _)| sum.checked_add(name.len()).ok_or("Block schema count overflow"))?;
    if size > c.limits().max_schema_bytes {
        return Err("Block authored schema exceeds byte limit".into());
    }
    Ok(())
}
fn native_list(v: Option<&dsl::FieldValue>) -> Result<&[dsl::FieldValue], String> {
    match v {
        None | Some(dsl::FieldValue::Absent) => Ok(&[]),
        Some(dsl::FieldValue::List(v)) => Ok(v),
        _ => Err("Block owned list required".into()),
    }
}
fn native_add(total: &mut usize, n: usize, maximum: usize) -> Result<(), String> {
    *total = total.checked_add(n).ok_or("Block native rows overflow")?;
    if *total > maximum {
        return Err("Block native rows exceed limit".into());
    }
    Ok(())
}
struct Cursor<'a, 'c, 'p> {
    row: &'a SqliteRow,
    index: usize,
    c: &'c mut SqliteSnapshotControl<'p>,
}
impl<'a, 'c, 'p> Cursor<'a, 'c, 'p> {
    fn new(row: &'a SqliteRow, index: usize, c: &'c mut SqliteSnapshotControl<'p>) -> Self {
        Self { row, index, c }
    }
    fn next(&mut self) -> Result<&'a SqliteValue, String> {
        let v = self.row.values.get(self.index).ok_or("Block missing cell")?;
        self.index += 1;
        Ok(v)
    }
    fn borrowed(&mut self) -> Result<&'a str, String> {
        match self.next()? {
            SqliteValue::Text(v) => Ok(v),
            _ => Err("Block TEXT required".into()),
        }
    }
    fn text(&mut self) -> Result<String, String> {
        let v = self.borrowed()?;
        Reconstruction::new(self.c)?.text(v)
    }
    fn optional_text(&mut self) -> Result<Option<String>, String> {
        if self.row.values.get(self.index) == Some(&SqliteValue::Null) {
            self.next()?;
            Ok(None)
        } else {
            self.text().map(Some)
        }
    }
    fn integer(&mut self) -> Result<i64, String> {
        match self.next()? {
            SqliteValue::Integer(v) => Ok(*v),
            _ => Err("Block INTEGER required".into()),
        }
    }
    fn boolean(&mut self) -> Result<bool, String> {
        let v = match self.integer()? {
            0 => false,
            1 => true,
            _ => return Err("Block boolean differs".into()),
        };
        Reconstruction::new(self.c)?.scalar()?;
        Ok(v)
    }
    fn float(&mut self) -> Result<f64, String> {
        let query = self.next()?;
        let v = f64::from_bits(self.integer()? as u64);
        if self.borrowed()? != class(v) {
            return Err("Block numeric class differs".into());
        }
        let matches = if v.is_nan() {
            query == &SqliteValue::Null
        } else {
            match query {
                SqliteValue::Real(q) => *q == v,
                SqliteValue::Integer(q) => v.is_finite() && v.fract() == 0.0 && v >= i64::MIN as f64 && v < -(i64::MIN as f64) && v as i64 == *q,
                _ => false,
            }
        };
        if !matches {
            return Err("Block numeric query differs".into());
        }
        Reconstruction::new(self.c)?.scalar()?;
        Ok(v)
    }
    fn optional_float(&mut self) -> Result<Option<f64>, String> {
        if self.row.values.get(self.index + 1) == Some(&SqliteValue::Null) {
            for _ in 0..3 {
                if self.next()? != &SqliteValue::Null {
                    return Err("Block partial optional scalar".into());
                }
            }
            Ok(None)
        } else {
            self.float().map(Some)
        }
    }
    fn done(self) -> Result<(), String> {
        if self.index != self.row.values.len() {
            return Err("Block extra cell".into());
        }
        Ok(())
    }
}
struct Rows<'a> {
    groups: BTreeMap<(usize, i64), BTreeMap<i64, &'a SqliteRow>>,
}
impl<'a> Rows<'a> {
    fn new(d: &'a SqliteDatabase, c: &mut SqliteSnapshotControl<'_>) -> Result<Self, String> {
        store::sqlite_snapshot::validate_sqlite_database_schema(d, SQL, c.limits()).map_err(|e| e.to_string())?;
        c.check_database(d, SqliteSnapshotPhase::ReconstructSnapshot)?;
        let mut ids: BTreeMap<usize, BTreeSet<i64>> = BTreeMap::new();
        let mut groups = BTreeMap::<(usize, i64), BTreeMap<i64, &SqliteRow>>::new();
        for (t, (name, width)) in TABLES.iter().enumerate() {
            for (n, row) in d.table(name)?.rows.iter().enumerate() {
                if row.rowid <= 0 || row.integer(0)? != row.rowid || row.values.len() != *width || !ids.entry(t).or_default().insert(row.rowid) {
                    return Err("Block alias/width differs".into());
                }
                if n % 256 == 0 {
                    c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, n, d.table(name)?.rows.len())?;
                }
            }
        }
        for (t, (name, _)) in TABLES.iter().enumerate() {
            for (n, row) in d.table(name)?.rows.iter().enumerate() {
                let parent = if t == 0 { 0 } else { row.integer(1)? };
                if t != 0 && !ids.get(&PARENTS[t]).is_some_and(|ids| ids.contains(&parent)) {
                    return Err("Block orphan ownership".into());
                }
                let order = if SINGLETONS.contains(&t) {
                    row.rowid
                } else {
                    let order = row.integer(2)?;
                    if order < 0 {
                        return Err("Block negative ordinal".into());
                    }
                    order
                };
                if groups.entry((t, parent)).or_default().insert(order, row).is_some() {
                    return Err("Block duplicate ordinal".into());
                }
                if n % 256 == 0 {
                    c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, n, d.table(name)?.rows.len())?;
                }
            }
        }
        Ok(Self { groups })
    }
    fn one(&mut self, t: usize, parent: i64) -> Result<&'a SqliteRow, String> {
        let group = self.groups.remove(&(t, parent)).unwrap_or_default();
        if group.len() != 1 {
            return Err("Block singleton cardinality differs".into());
        }
        group.into_values().next().ok_or("Block singleton missing".into())
    }
    fn take(&mut self, t: usize, parent: i64, c: &mut SqliteSnapshotControl<'_>) -> Result<Vec<&'a SqliteRow>, String> {
        let group = self.groups.remove(&(t, parent)).unwrap_or_default();
        let total = group.len();
        c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, total)?;
        let mut out = Vec::new();
        out.try_reserve_exact(total).map_err(|_| "Block relationship allocation failed")?;
        for (n, (order, row)) in group.into_iter().enumerate() {
            if order != i64::try_from(n).map_err(|e| e.to_string())? {
                return Err("Block noncontiguous ordinal".into());
            }
            out.push(row);
            if (n + 1) % 256 == 0 {
                c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, n + 1, total)?;
            }
        }
        c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, total, total)?;
        Ok(out)
    }
    fn finish(self, c: &mut SqliteSnapshotControl<'_>) -> Result<(), String> {
        if !self.groups.is_empty() {
            return Err("Block unowned entity".into());
        }
        c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 1, 1)
    }
}
fn project_kind(out: &mut Projection<'_, '_>, owner: i64, k: &BlockKindIdentity) -> Result<(), String> {
    out.insert(TABLES[1].0, &[Cell::Integer(owner), Cell::Text(&k.id), Cell::Text(&k.name), Cell::Text(&k.label), text(&k.variant), Cell::Text(&k.description), text(&k.icon), text(&k.unit)])?;
    Ok(())
}
fn kind(row: &SqliteRow, c: &mut SqliteSnapshotControl<'_>) -> Result<BlockKindIdentity, String> {
    let mut v = Cursor::new(row, 2, c);
    let out = BlockKindIdentity { id: v.text()?, name: v.text()?, label: v.text()?, variant: v.optional_text()?, description: v.text()?, icon: v.optional_text()?, unit: v.optional_text()? };
    v.done()?;
    Ok(out)
}
