}
fn author(row: &SqliteRow, c: &mut SqliteSnapshotControl<'_>) -> Result<BlockAuthor, String> {
    let mut v = Cursor::new(row, 3, c);
    let out = BlockAuthor { id: v.text()?, name: v.text()?, email: v.optional_text()? };
