        En1997Mutation::InsertLayer(payload) => En1997MutationDsl::InsertLayer { index: payload.index, layer: payload.layer.clone() },
        En1997Mutation::RemoveLayer(payload) => En1997MutationDsl::RemoveLayer { index: payload.index },
