/// 📄️ The real registry preserves imported graph documents and retires its rebuilt roots.
#[test]
fn imported_graph_text_registry_round_trip_preserves_graph_and_retires_rebuilt_snapshot() {
    use semio_framework_plugin::{Dialect, ErasedComposeSource, IoPayload, StandardId, SubsetId};
    use semio_s_artifact_procedural_generation3d::standards::v1::subsets::any::io::{import, io_registry};
    let contract = fixture()["registryText"].clone();
    assert_eq!(contract["source"], "imported-unit-cube");
    assert_eq!(contract["preserveGraph"], true);
    let document = mesh_bridge::import_mesh_data(&crate::unit_cube_mesh_data()).expect("real imported graph");
    assert_eq!(document.host_snapshot.widgets.len(), 3);
    let expected = semio_framework_os_kernel::ToValue::to_value(&document);
    let bytes = document_io::export_document_bytes(&document).expect("real document text");
    let json = String::from_utf8(semio_s_artifact_procedural_generation3d::standards::v1::subsets::any::io::export::serializers::artifacts::json::v_rfc8259::any::serialize_bytes(&document).expect("real document json")).expect("json is utf8");
    let independent: serde_json::Value = serde_json::from_str(&json).expect("third-party json reader");
    assert_eq!(independent["hostSnapshot"]["widgets"].as_array().expect("imported graph widgets").len(), 3);
    retire_document(document);
    let entry = io_registry::entries().iter().find(|entry| entry.writes.artifact_kind == contract["target"].as_str().unwrap()).expect("true graph text registry entry");
    for kind in contract["sourceKinds"].as_array().unwrap() {
        let source = match kind.as_str().unwrap() {
            "native" => ErasedComposeSource { dialect: semio_s_artifact_procedural_generation3d::GENERATION3D_DIALECT, payload: IoPayload::Text(String::from_utf8(bytes.clone()).unwrap()) },
            "json-bridge" => ErasedComposeSource { dialect: Dialect { artifact_kind: "s.stdio.json", standard: StandardId("rfc8259"), subset: SubsetId::ANY }, payload: IoPayload::Text(json.clone()) },
            unknown => panic!("unsupported registry fixture source {unknown}"),
        };
        let sources = [source];
        let composed = ::semio_framework_async::poll::resolve_ready((entry.compose)(&sources)).expect("actual registry exports imported graph");
        assert_eq!(composed.dialect, entry.writes);
        let IoPayload::Text(text) = composed.payload else { panic!("text registry must return text") };
        let restored = import::deserializers::artifacts::txt::v_utf_8::any::deserialize_bytes(text.as_bytes()).expect("registry text imports");
        let actual = semio_framework_os_kernel::ToValue::to_value(&restored);
        retire_document(restored);
        assert_eq!(actual, expected, "registry preserves the full imported graph for {kind}");
    }
}

//! 🧊️ generation3d ← `s.stdio.gltf@2.0` — a real glTF/GLB file becomes a real, previewable document.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf discarded the bytes and returned an
//! empty document (see the stl sibling's doc comment for the shared defect and the fixture design).
//!
//! Both container forms are accepted — the `glTF` magic selects gltf's own `decode_glb`, anything
//! else goes through `parse_gltf_document` — because a user picking "import glTF" does not
//! distinguish them. The flow evaluator has no `brep.io.importGltf` operator, so geometry is
//! normalized through `SemioMeshFromGltf` → `SemioMeshToStl` → ASCII STL onto a `brep.io.importStl`
//! neuron, exactly as the ply sibling does.
//!
//! 🔖 Documented lossiness: only geometry crosses. glTF materials, textures, animations, skins,
//! cameras and the scene graph have no counterpart in a BRep flow graph and do not survive; a
//! non-triangle primitive is refused by `SemioMeshToStl` as a typed error rather than approximated.
use crate::standards::v1::subsets::any::io::mesh_bridge::{base64_encode, import_document, io_error, stl_ascii_bytes};
use crate::Generation3dSnapshot;
use semio_framework_plugin::ArtifactDeserializer;
use semio_s_artifact_stdio_gltf::GltfSnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::import::deserializers::artifacts::gltf::v2_0::any::SemioMeshFromGltf;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;

/// 🔧️ The neuron kind glTF geometry re-enters the flow graph through, after normalization.
pub const IMPORT_NEURON_KIND: &str = "brep.io.importStl";

/// 🪄️ GLB container magic (glTF 2.0 §4.4.1) — the one byte-level cue that picks the container.
const GLB_MAGIC: &[u8; 4] = b"glTF";

pub fn register() {}

pub fn mesh_from_bytes(bytes: &[u8]) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_snapshot(&decode(bytes)?)
}

pub fn mesh_from_snapshot(from: &GltfSnapshot) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    ::semio_framework_async::poll::resolve_ready(SemioMeshFromGltf::deserialize(from)).map_err(|error| io_error(format!("generation3d←gltf: {error}")))
}

fn decode(bytes: &[u8]) -> Result<GltfSnapshot, semio_framework_diagnostic::TextError> {
    let decoded = if bytes.starts_with(GLB_MAGIC) { semio_s_artifact_stdio_gltf::engine::decode_glb(bytes) } else { semio_s_artifact_stdio_gltf::engine::parse_gltf_document(bytes) };
    decoded.map_err(|error| io_error(format!("generation3d←gltf: {error}")))
}

pub fn deserialize(from: &GltfSnapshot) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(&stl_ascii_bytes(&mesh_from_snapshot(from)?)?)))
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(&stl_ascii_bytes(&mesh_from_bytes(bytes)?)?)))
}

//! ⚡️ `s.wfc.grid3d` — the mutation vocabulary's single-line TEXT opcodes + grammar. One keyword per
//! `Grid3dMutation` variant, in the `KINDS` order the oracle catalog declares.
//!
//! The dispatch enum derives `dsl::Mutations` (one unnamed field per variant), which emits no
//! keyworded record, so this leaf carries a flat `Grid3dOperationDsl` mirror converted at the
//! `OpText`/`OpBinary` boundary only — every field is a local type that already binds
//! `dsl::DslField`, so no twin RECORD is needed, only a twin ENUM.

//#region 📖️SemioGrammar
/// 📖️ Normative handcrafted text grammar for this facet (`dialect grammar`).
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️.grammar.semio");
//#endregion 📖️SemioGrammar

