//#region 🔖️OpTextMirror
#[derive(Clone, Debug, PartialEq, dsl::DslEnum)]
pub enum Grid3dOperationDsl {
    ChangeSeed {
        seed: u64,
    },
    ResizeGrid {
        width: u32,
        height: u32,
        depth: u32,
    },
    ChangeCellSizes {
        axis: Grid3dAxis,
        sizes: Vec<f64>,
    },
    ChangePeriodicity {
        periodic_x: bool,
        periodic_y: bool,
        periodic_z: bool,
    },
    CreateTile {
        #[dsl(block)]
        tile: Grid3dTile,
    },
    DeleteTile {
        id: String,
    },
    ChangeTileWeight {
        tile_id: String,
        weight: f64,
    },
    ChangeTileMedia {
        tile_id: String,
        #[dsl(statements, block)]
        media: Grid3dTileMedia,
    },
    CreateRule {
        #[dsl(block)]
        rule: Grid3dRule,
    },
    DeleteRule {
        id: String,
    },
    PinCell {
        #[dsl(block)]
        pinned: Grid3dPinnedCell,
    },
    UnpinCell {
        x: u32,
        y: u32,
        z: u32,
    },
    MaskCell {
        #[dsl(block)]
        cell: Grid3dCell,
    },
    UnmaskCell {
        x: u32,
        y: u32,
        z: u32,
    },
}

pub fn operation_to_dsl(operation: &Grid3dMutation) -> Grid3dOperationDsl {
    match operation {
        Grid3dMutation::ChangeSeed(ChangeSeed { seed }) => Grid3dOperationDsl::ChangeSeed { seed: *seed },
        Grid3dMutation::ResizeGrid(ResizeGrid { width, height, depth }) => Grid3dOperationDsl::ResizeGrid { width: *width, height: *height, depth: *depth },
        Grid3dMutation::ChangeCellSizes(ChangeCellSizes { axis, sizes }) => Grid3dOperationDsl::ChangeCellSizes { axis: *axis, sizes: sizes.clone() },
        Grid3dMutation::ChangePeriodicity(ChangePeriodicity { periodic_x, periodic_y, periodic_z }) => Grid3dOperationDsl::ChangePeriodicity { periodic_x: *periodic_x, periodic_y: *periodic_y, periodic_z: *periodic_z },
        Grid3dMutation::CreateTile(CreateTile { tile }) => Grid3dOperationDsl::CreateTile { tile: tile.clone() },
        Grid3dMutation::DeleteTile(DeleteTile { id }) => Grid3dOperationDsl::DeleteTile { id: id.clone() },
        Grid3dMutation::ChangeTileWeight(ChangeTileWeight { tile_id, weight }) => Grid3dOperationDsl::ChangeTileWeight { tile_id: tile_id.clone(), weight: *weight },
        Grid3dMutation::ChangeTileMedia(ChangeTileMedia { tile_id, media }) => Grid3dOperationDsl::ChangeTileMedia { tile_id: tile_id.clone(), media: media.clone() },
        Grid3dMutation::CreateRule(CreateRule { rule }) => Grid3dOperationDsl::CreateRule { rule: rule.clone() },
        Grid3dMutation::DeleteRule(DeleteRule { id }) => Grid3dOperationDsl::DeleteRule { id: id.clone() },
        Grid3dMutation::PinCell(PinCell { pinned }) => Grid3dOperationDsl::PinCell { pinned: pinned.clone() },
        Grid3dMutation::UnpinCell(UnpinCell { x, y, z }) => Grid3dOperationDsl::UnpinCell { x: *x, y: *y, z: *z },
        Grid3dMutation::MaskCell(MaskCell { cell }) => Grid3dOperationDsl::MaskCell { cell: *cell },
        Grid3dMutation::UnmaskCell(UnmaskCell { x, y, z }) => Grid3dOperationDsl::UnmaskCell { x: *x, y: *y, z: *z },
    }
}

pub fn operation_from_dsl(operation: Grid3dOperationDsl) -> Grid3dMutation {
    match operation {
        Grid3dOperationDsl::ChangeSeed { seed } => Grid3dMutation::ChangeSeed(ChangeSeed { seed }),
        Grid3dOperationDsl::ResizeGrid { width, height, depth } => Grid3dMutation::ResizeGrid(ResizeGrid { width, height, depth }),
        Grid3dOperationDsl::ChangeCellSizes { axis, sizes } => Grid3dMutation::ChangeCellSizes(ChangeCellSizes { axis, sizes }),
        Grid3dOperationDsl::ChangePeriodicity { periodic_x, periodic_y, periodic_z } => Grid3dMutation::ChangePeriodicity(ChangePeriodicity { periodic_x, periodic_y, periodic_z }),
        Grid3dOperationDsl::CreateTile { tile } => Grid3dMutation::CreateTile(CreateTile { tile }),
        Grid3dOperationDsl::DeleteTile { id } => Grid3dMutation::DeleteTile(DeleteTile { id }),
        Grid3dOperationDsl::ChangeTileWeight { tile_id, weight } => Grid3dMutation::ChangeTileWeight(ChangeTileWeight { tile_id, weight }),
        Grid3dOperationDsl::ChangeTileMedia { tile_id, media } => Grid3dMutation::ChangeTileMedia(ChangeTileMedia { tile_id, media }),
        Grid3dOperationDsl::CreateRule { rule } => Grid3dMutation::CreateRule(CreateRule { rule }),
        Grid3dOperationDsl::DeleteRule { id } => Grid3dMutation::DeleteRule(DeleteRule { id }),
        Grid3dOperationDsl::PinCell { pinned } => Grid3dMutation::PinCell(PinCell { pinned }),
        Grid3dOperationDsl::UnpinCell { x, y, z } => Grid3dMutation::UnpinCell(UnpinCell { x, y, z }),
        Grid3dOperationDsl::MaskCell { cell } => Grid3dMutation::MaskCell(MaskCell { cell }),
        Grid3dOperationDsl::UnmaskCell { x, y, z } => Grid3dMutation::UnmaskCell(UnmaskCell { x, y, z }),
    }
}
//#endregion 🔖️OpTextMirror

//#region 🔖️HandcraftedOpCodecs
/// ⚡️ Handcrafted `OpText` — `dsl::DslEnum` emits `DslVariants` only (P6).
impl protocol::OpText for Grid3dOperationDsl {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        let variants = <Self as dsl::DslVariants>::variants();
        for (keyword, spec_fn) in &variants {
            let probe = format!("{keyword} ");
            if line == keyword.as_str() || line.starts_with(&probe) {
                let record = dsl::parse(line, &(spec_fn.ordinary)(), &dsl::ParseOptions { limits: semio_framework_diagnostic::Limits::default(), mode: dsl::SourceMode::Inline })?;
                return <Self as dsl::DslVariants>::from_named_record(keyword, &record);
            }
        }
        Err(dsl::__rt::field_error(format!("unknown wfc grid3d mutation line '{line}'")))
    }
    fn print_op(&self) -> String {
        let (keyword, record) = <Self as dsl::DslVariants>::to_named_record(self);
        let variants = <Self as dsl::DslVariants>::variants();
        let spec_fn = variants.iter().find(|(candidate, _)| candidate == &keyword).map(|(_, spec)| *spec).expect("variant spec must exist for its own keyword");
        dsl::print(&record, &(spec_fn.ordinary)(), dsl::JoinMode::Inline)
    }
}

/// ⚡️ `Grid3dMutation`'s compact single-line op encoding, bridged through the twin above.
impl protocol::OpText for Grid3dMutation {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        Ok(operation_from_dsl(<Grid3dOperationDsl as protocol::OpText>::parse_op(line)?))
    }

    fn print_op(&self) -> String {
        <Grid3dOperationDsl as protocol::OpText>::print_op(&operation_to_dsl(self))
    }
}
//#endregion 🔖️HandcraftedOpCodecs

/// 📖️ Parses one `.wfcgrid3d` mutation line.
pub fn parse_op(line: &str) -> Result<Grid3dMutation, semio_framework_diagnostic::TextError> {
    <Grid3dMutation as protocol::OpText>::parse_op(line)
}

/// 🖨️ Prints one `Grid3dMutation` back to its single-line form.
pub fn print_op(operation: &Grid3dMutation) -> String {
    protocol::OpText::print_op(operation)
}

//#region 🚚️Carrier
/// 🚚️ The carrier this facet's `parse_op`/`print_op` speak.
pub type Grid3dMutationText = String;
//#endregion 🚚️Carrier

//! 🗿️ generation3d ← `s.stdio.obj@3.0` — a real Wavefront OBJ becomes a real, previewable document.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf discarded the bytes and returned an
//! empty document (see the stl sibling's doc comment for the shared defect and the fixture design).
//!
//! OBJ is the one mesh format besides STL/DWG with its own flow operator, and its `data` channel
//! takes PLAIN TEXT rather than base64 (`brep.io.importObj` reads the channel with `read_text`), so
//! the note carries the OBJ source verbatim and stays human-readable in the graph. The text is
//! parsed first (obj's own `decode_obj`) so a non-OBJ payload fails here, not at evaluation time.
use crate::standards::v1::subsets::any::io::mesh_bridge::{import_document, io_error};
use crate::Generation3dSnapshot;
use semio_framework_plugin::ArtifactDeserializer;
use semio_s_artifact_stdio_obj::ObjSnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::import::deserializers::artifacts::obj::v3_0::any::SemioMeshFromObj;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;

/// 🔧️ The neuron kind that re-enters OBJ text into the flow graph.
pub const IMPORT_NEURON_KIND: &str = "brep.io.importObj";

pub fn register() {}

pub fn mesh_from_bytes(bytes: &[u8]) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_snapshot(&decode(bytes)?)
}

pub fn mesh_from_snapshot(from: &ObjSnapshot) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    ::semio_framework_async::poll::resolve_ready(SemioMeshFromObj::deserialize(from)).map_err(|error| io_error(format!("generation3d←obj: {error}")))
}

fn decode(bytes: &[u8]) -> Result<ObjSnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|error| io_error(format!("generation3d←obj: obj is not valid utf-8: {error}")))?;
    semio_s_artifact_stdio_obj::engine::decode_obj(text).map_err(|error| io_error(format!("generation3d←obj: {error}")))
}

pub fn deserialize(from: &ObjSnapshot) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_snapshot(from)?;
    Ok(import_document(IMPORT_NEURON_KIND, semio_s_artifact_stdio_obj::engine::encode_obj(from)))
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    deserialize(&decode(bytes)?)
}

//! 🧱️ generation3d ← `s.stdio.ply@1.0` — a real PLY file becomes a real, previewable document.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf discarded the bytes and returned an
//! empty document (see the stl sibling's doc comment for the shared defect and the fixture design).
//!
//! The flow evaluator has no `brep.io.importPly` operator, so this import NORMALIZES: ply's own
//! `decode_ply` → `SemioMeshFromPly` → `SemioMeshToStl` → ASCII STL, planted on a
//! `brep.io.importStl` neuron. That is a real conversion through two already-tested bridges, not a
//! second PLY grammar, and it is honest about its limit — a PLY with no `face` element is a point
//! cloud, `SemioMeshToStl` refuses it by name, and the refusal reaches the caller as a typed error
//! instead of an empty document.
use crate::standards::v1::subsets::any::io::mesh_bridge::{base64_encode, import_document, io_error, stl_ascii_bytes};
use crate::Generation3dSnapshot;
use semio_framework_plugin::ArtifactDeserializer;
use semio_s_artifact_stdio_ply::PlySnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::import::deserializers::artifacts::ply::v1_0::any::SemioMeshFromPly;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;

/// 🔧️ The neuron kind PLY geometry re-enters the flow graph through, after normalization.
pub const IMPORT_NEURON_KIND: &str = "brep.io.importStl";

pub fn register() {}

pub fn mesh_from_bytes(bytes: &[u8]) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_snapshot(&semio_s_artifact_stdio_ply::engine::decode_ply(bytes).map_err(|error| io_error(format!("generation3d←ply: {error}")))?)
}

pub fn mesh_from_snapshot(from: &PlySnapshot) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    ::semio_framework_async::poll::resolve_ready(SemioMeshFromPly::deserialize(from)).map_err(|error| io_error(format!("generation3d←ply: {error}")))
}

pub fn deserialize(from: &PlySnapshot) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(&stl_ascii_bytes(&mesh_from_snapshot(from)?)?)))
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(&stl_ascii_bytes(&mesh_from_bytes(bytes)?)?)))
}

//! 🖊️ generation3d ← `s.stdio.dwg` — a real DWG drawing becomes a real, previewable document.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf discarded the bytes and returned an
//! empty document (see the stl sibling's doc comment for the shared defect and the fixture design).
//! That was the exact path the plugin root's registered mesh-import host-media handler leans on
//! (`register_mesh_dwg_import_handler`, `✏️s/🔌️plugins/🌀️procedural/🦀️.rs`), so dropping a DWG on
//! this app produced a blank canvas.
//!
//! DWG has its own flow operator (`brep.io.importDwg`, base64 `data` channel), so the native bytes
//! are planted verbatim rather than normalized through STL — the kernel's own DWG reader keeps the
//! layer/entity structure this artifact's export writes. The container is decoded first
//! (`decode_dwg`) and the drawing is required to actually carry mesh geometry
//! (`SemioMeshFromDwg`), so a curve-only or non-DWG file fails loudly here rather than evaluating
//! to nothing later.
use crate::standards::v1::subsets::any::io::mesh_bridge::{base64_encode, import_document, io_error};
use crate::Generation3dSnapshot;
use semio_framework_plugin::ArtifactDeserializer;
use semio_s_artifact_stdio_dwg::DwgSnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::import::deserializers::artifacts::dwg::v_ac1024::any::SemioMeshFromDwg;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;

/// 🔧️ The neuron kind that re-enters DWG bytes into the flow graph.
pub const IMPORT_NEURON_KIND: &str = "brep.io.importDwg";

pub fn register() {}

pub fn mesh_from_bytes(bytes: &[u8]) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_snapshot(&semio_s_artifact_stdio_dwg::schema::snapshot::decode_dwg(bytes).map_err(|error| io_error(format!("generation3d←dwg: {error}")))?)
}

pub fn mesh_from_snapshot(from: &DwgSnapshot) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    let mesh = ::semio_framework_async::poll::resolve_ready(SemioMeshFromDwg::deserialize(from)).map_err(|error| io_error(format!("generation3d←dwg: {error}")))?;
    if mesh.meshes.iter().all(|entry| entry.primitives.is_empty()) {
        return Err(io_error("generation3d←dwg: the drawing carries no polyface-mesh or 3d-face entity, so it holds no geometry this artifact can preview"));
    }
    Ok(mesh)
}

pub fn deserialize(from: &DwgSnapshot) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_snapshot(from)?;
    let bytes = semio_s_artifact_stdio_dwg::schema::snapshot::encode_dwg(from).map_err(|error| io_error(format!("generation3d←dwg: {error}")))?;
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(&bytes)))
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_bytes(bytes)?;
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(bytes)))
}

//! 🔤️ generation3d ← `s.stdio.txt@utf-8` — the exact inverse of the txt export leaf.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END both halves were
//! `Err("txt import not yet implemented")`.
//!
//! The artifact's native serialization already IS UTF-8 text, so importing txt means parsing that
//! grammar: `ArtifactDsl::parse_dsl`, the same entry point `derived_analysis` and
//! `Generation3dBuilder::from_text` use — one parser, never a second reader for the same grammar.
//! This is the only FULL-FIDELITY import in this artifact's IO surface: the whole flow graph and
//! generation history come back, not just evaluated geometry.
use crate::Generation3dSnapshot;
use semio_s_artifact_stdio_txt::TxtSnapshot;

pub fn register() {}

pub fn deserialize(from: &TxtSnapshot) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    <Generation3dSnapshot as store::ArtifactDsl>::parse_dsl(&from.to_body())
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|error| semio_framework_diagnostic::TextError::new(format!("generation3d←txt: not valid utf-8: {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    deserialize(&TxtSnapshot::from_body(text))
}

//! 🔺️ generation3d ← `s.stdio.stl@ascii` — a real STL file becomes a real, previewable document.
//!
//! 🐛️ Before ticket 26/09/09/PROCEDURAL-3D-END-TO-END this leaf was `let _ = bytes;
//! Ok(Generation3dSnapshot::default())` — it discarded the file and reported success, so importing
//! an STL silently produced an EMPTY document.
//!
//! A generation3d document has no mesh field to put a mesh in: its geometry is whatever its flow
//! graph EVALUATES to. So the import plants the file in the graph — a note holding the STL bytes
//! feeding a `brep.io.importStl` neuron (`preview: true`) feeding a preview sink — which the flow
//! evaluator turns into real BRep geometry through the same kernel every bundled example uses. The
//! bytes are decoded FIRST (stl's own `decode_stl_auto`, ASCII or binary) so a file that is not STL
//! fails loudly here instead of becoming a graph that fails later at evaluation time.
use crate::standards::v1::subsets::any::io::mesh_bridge::{base64_encode, import_document, io_error};
use crate::Generation3dSnapshot;
use semio_framework_plugin::ArtifactDeserializer;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::import::deserializers::artifacts::stl::v_ascii::any::SemioMeshFromStl;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::SemioMeshSnapshot;
use semio_s_artifact_stdio_stl::StlSnapshot;

/// 🔧️ The neuron kind that re-enters STL bytes into the flow graph.
pub const IMPORT_NEURON_KIND: &str = "brep.io.importStl";

pub fn register() {}

/// 🔺️ The geometry half, isolated so the round-trip test can assert triangle counts and bounds
/// without a live flow evaluator.
pub fn mesh_from_bytes(bytes: &[u8]) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    let stl = semio_s_artifact_stdio_stl::engine::decode_stl_auto(bytes).map_err(|error| io_error(format!("generation3d←stl: {error}")))?;
    mesh_from_snapshot(&stl)
}

pub fn mesh_from_snapshot(from: &StlSnapshot) -> Result<SemioMeshSnapshot, semio_framework_diagnostic::TextError> {
    ::semio_framework_async::poll::resolve_ready(SemioMeshFromStl::deserialize(from)).map_err(|error| io_error(format!("generation3d←stl: {error}")))
}

pub fn deserialize(from: &StlSnapshot) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_snapshot(from)?;
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(&semio_s_artifact_stdio_stl::engine::encode_stl_ascii(from).into_bytes())))
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    mesh_from_bytes(bytes)?;
    Ok(import_document(IMPORT_NEURON_KIND, base64_encode(bytes)))
}

//! generation3d <- json
//!
//! 🩹️ w5b-close fix (stdio_gap/foreign-lag, not svg/dwg-pattern scope — see the paired export
//! leaf's doc comment and w5b-close-report.md): `JsonSnapshot::to_serde_value`/stdio's own real
//! `parse_json_text` do the structural conversion — no hand-rolled bridge needed here.
use crate::Generation3dSnapshot;
use semio_s_artifact_stdio_json::schema::snapshot::{parse_json_text, JsonSnapshot};
use semio_s_artifact_stdio_json::STDIO_JSON_DOCUMENT_SCHEMA;

pub fn register() {}

pub fn deserialize(from: &JsonSnapshot) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    let _ = STDIO_JSON_DOCUMENT_SCHEMA;
    let snap = <Generation3dSnapshot as protocol::FromValue>::from_value(protocol::DslValue::from(from.to_serde_value())).map_err(|e| semio_framework_diagnostic::TextError::new(format!("generation3d<-json: {e}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;

    Ok(snap)
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Generation3dSnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|e| semio_framework_diagnostic::TextError::new(e.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    let value = parse_json_text(text).map_err(|e| semio_framework_diagnostic::TextError::new(e.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    deserialize(&JsonSnapshot::from_value(value))
}

//! 🧮️ Lowpoly play app — view state (`LowpolyConfig`) and its patch operations
//! (`LowpolyConfigMutation`). Absorbs every field that used to live in the old ui crate's
//! `LowpolyPlayRuntime` app-struct `RefCell` (selection, active object, paint utility/layer, selection
//! method/mode, hover, world camera, sun, and show-edges) — session-only editor settings round-trip through the config
//! `ArtifactStore` exactly like document content, with a real `backwards` per
//! `LowpolyConfigMutation`, mirroring the `shooting_engine::ShootingConfig` pilot. Nested value types
//! (`LowpolySelection`, the world camera, hover target, sun, paint color) are flattened into scalar
//! fields rather than embedded as DSL blocks — `LowpolySelection`/`WorldSunConfig` aren't
//! `dsl::DslField`-capable today and flattening avoids widening that surface just for this migration.

use protocol::Mutation;
use semio_framework_plugin::WorldSunConfig;
#[cfg(test)]
use serde::{Deserialize, Serialize};

//#region 🔖️Config
#[derive(Clone, Debug, PartialEq, dsl::DslArtifact, value_derive::ToValue, value_derive::FromValue)]
#[cfg_attr(test, derive(Serialize, Deserialize))]
#[cfg_attr(test, serde(rename_all = "camelCase", default))]
#[value(rename_all = "camelCase", default)]
#[dsl(extension = "lowpoly.lowpolycfg")]
#[dsl(layout = "lines")]
pub struct LowpolyConfig {
    /// 👁️ Was `LowpolyPlayRuntime::active_object_id`.
    pub active_object_id: String,
    /// 👁️ Was `LowpolyPlayRuntime::paint_utility`.
    pub paint_utility: String,
    /// 👁️ Was `LowpolyPlayRuntime::active_paint_layer`.
    pub active_paint_layer: u32,
    /// 👁️ Was `LowpolyPlayRuntime::utility_params` (`serde_json::Value`) — carried as canonical JSON
    /// text since a raw `Value` field has no direct DSL binding.
    pub utility_params_json: String,
    /// 🎨️ Was `LowpolyPlayRuntime::paint_color` (`[u8; 4]`), flattened.
    pub paint_color_r: u8,
