            retaining_walls: snapshot.retaining_walls,
            slopes: snapshot.slopes,
            uplift_cases: snapshot.uplift_cases,
        }
    }

    pub fn set_snapshot(&mut self, snapshot: En1997Snapshot) {
        *self = Self::from_snapshot(snapshot);
    }
}
