    pub fn label(self, annex: AnnexChoice) -> &'static str {
        match (self, annex) {
            (Self::Da2 | Self::Geo2, AnnexChoice::De) => "DA2*/GEO-2",
            (Self::Da2 | Self::Geo2, AnnexChoice::En) => "DA2",
            (Self::Geo3, _) => "GEO-3",
            (Self::Da1Str, _) => "DA1-C1",
            (Self::Da1Geo, _) => "DA1-C2",
            (Self::Da3, _) => "DA3",
