//! lowpoly -> las
//!
//! Real LAS 1.x export through `io::encode_las`: every world-space mesh vertex becomes one point
//! record.
//!
//! 🔖 `IoFidelity::Lossy`: a point cloud of the vertices — faces, objects and paint do not survive,
//! so there is no las import.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_las::io::encode_las;
use semio_s_artifact_stdio_las::schema::snapshot::{LasHeader, LasPoint};
use semio_s_artifact_stdio_las::LasSnapshot;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<LasSnapshot, semio_framework_diagnostic::TextError> {
    let mut points = Vec::new();
    let mut min = [f64::INFINITY; 3];
    let mut max = [f64::NEG_INFINITY; 3];
    for part in world_parts("las", snapshot)? {
        for p in &part.positions {
            for i in 0..3 {
                min[i] = min[i].min(p[i]);
                max[i] = max[i].max(p[i]);
            }
            points.push(LasPoint {
                x: p[0],
                y: p[1],
                z: p[2],
                intensity: 0,
                return_number: 1,
                number_of_returns: 1,
                scan_direction_flag: false,
                edge_of_flight_line: false,
                classification: 0,
                scan_angle_rank: 0,
                user_data: 0,
                point_source_id: 0,
                gps_time: None,
                rgb: None,
            });
        }
    }
    if min[0].is_infinite() {
        min = [0.0; 3];
        max = [0.0; 3];
    }
    let mut header = LasHeader::default();
    header.system_identifier = "semio.lowpoly".into();
    header.generating_software = "semio.lowpoly".into();
    header.min_x = min[0];
    header.min_y = min[1];
    header.min_z = min[2];
    header.max_x = max[0];
    header.max_y = max[1];
    header.max_z = max[2];
    header.number_of_point_records = points.len() as u32;
    Ok(LasSnapshot {
        header,
        points,
        ..Default::default()
    })
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    encode_las(&serialize(snapshot)?).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! lowpoly -> obj
//!
//! Writes real Wavefront OBJ geometry through `engine::encode_obj` (never a second bespoke
//! grammar): every object whose persisted `mesh_content` is non-empty contributes an `o <name>`
//! block of world-space `v` positions (scale → Euler-degree rotation → translation) and its
//! original n-gon `f` polygons. Object names are made single-token (OBJ readers, including
//! `decode_obj`, keep only the first token of `o`) and unique (same-named `o` blocks merge on
//! read).
//!
//! 🔖 `IoFidelity::Lossy`: geometry and object names survive; paint, materials and the object
//! transforms (already applied to the positions) do not.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_obj::engine::encode_obj;
use semio_s_artifact_stdio_obj::schema::snapshot::{ObjFace, ObjFaceVertex, ObjObject, ObjVertex};
use semio_s_artifact_stdio_obj::ObjSnapshot;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<ObjSnapshot, semio_framework_diagnostic::TextError> {
    let mut obj = ObjSnapshot::default();
    let mut used_names: std::collections::HashSet<String> = std::collections::HashSet::new();
    for part in world_parts("obj", snapshot)? {
        let base: String = part.name.split_whitespace().collect::<Vec<_>>().join("_");
        let base = if base.is_empty() { "Object".to_string() } else { base };
        let mut name = base.clone();
        let mut suffix = 2;
        while !used_names.insert(name.clone()) {
            name = format!("{base}.{suffix}");
            suffix += 1;
        }
        let offset = obj.vertices.len() as u32;
        obj.vertices.extend(part.positions.iter().map(|p| ObjVertex { x: p[0], y: p[1], z: p[2], w: None }));
        let mut object = ObjObject { name, faces: Vec::with_capacity(part.faces.len()) };
        for face in &part.faces {
            object.faces.push(u64::try_from(obj.faces.len()).map_err(|_| crate::io::mesh_geometry::text_error("OBJ face occurrence exceeds u64"))?);
            obj.faces.push(ObjFace { vertices: face.iter().map(|&v| ObjFaceVertex { vertex: v + offset, texcoord: None, normal: None }).collect() });
        }
        obj.objects.push(object);
    }
    Ok(obj)
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    Ok(encode_obj(&serialize(snapshot)?).into_bytes())
}

//! lowpoly -> ply
//!
//! Real ASCII PLY export through `engine::encode_ply`: a `vertex` element (`float x/y/z`, world
//! space — scale → Euler-degree rotation → translation) and a `face` element
//! (`list uchar int vertex_indices`, widened to a `uint` count past 255 corners) holding every
//! object's original n-gons, concatenated. Objects with empty `mesh_content` contribute nothing.
//!
//! 🔖 `IoFidelity::Lossy`: geometry survives with n-gons kept; object boundaries, names and paint
//! do not.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_ply::engine::encode_ply;
use semio_s_artifact_stdio_ply::schema::snapshot::{PlyElement, PlyProperty, PlyRow, PlyScalarType, PlyValue};
use semio_s_artifact_stdio_ply::PlySnapshot;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<PlySnapshot, semio_framework_diagnostic::TextError> {
    let mut vertex_rows = Vec::new();
    let mut face_rows = Vec::new();
    let mut max_corners = 0usize;
    for part in world_parts("ply", snapshot)? {
        let offset = vertex_rows.len() as u32;
        vertex_rows.extend(part.positions.iter().map(|p| PlyRow { values: vec![PlyValue::Float(p[0] as f32), PlyValue::Float(p[1] as f32), PlyValue::Float(p[2] as f32)] }));
        for face in &part.faces {
            max_corners = max_corners.max(face.len());
            face_rows.push(PlyRow { values: vec![PlyValue::List(face.iter().map(|&v| PlyValue::Int((v + offset) as i32)).collect())] });
        }
    }
    let mut ply = PlySnapshot::default();
    if !vertex_rows.is_empty() {
        let count_kind = if max_corners > 255 { PlyScalarType::UInt } else { PlyScalarType::UChar };
        ply.elements.push(PlyElement {
            name: "vertex".into(),
            count: u64::try_from(vertex_rows.len()).map_err(|_| crate::io::mesh_geometry::text_error("PLY vertex occurrence count exceeds u64"))?,
            properties: ["x", "y", "z"].iter().map(|n| PlyProperty::Scalar { name: (*n).into(), kind: PlyScalarType::Float }).collect(),
            rows: vertex_rows,
        });
        ply.elements.push(PlyElement { name: "face".into(), count: u64::try_from(face_rows.len()).map_err(|_| crate::io::mesh_geometry::text_error("PLY face occurrence count exceeds u64"))?, properties: vec![PlyProperty::List { name: "vertex_indices".into(), count_kind, value_kind: PlyScalarType::Int }], rows: face_rows });
    }
    Ok(ply)
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    encode_ply(&serialize(snapshot)?).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! lowpoly -> dwg
//!
//! Real DWG export: mesh vertices/faces (world space, fan-triangulated) go through
//! `mesh_to_dwg_drawing` -> `DwgSnapshot::from_drawing` -> `encode_dwg` (AC1024).
//!
//! 🔖 `IoFidelity::Lossy`: one polyface mesh of triangles — objects, names and paint do not survive.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_framework_plugin::MeshData;
use semio_s_artifact_stdio_dwg::{dwg_to_bytes, mesh_to_dwg_drawing, DwgSnapshot};

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<DwgSnapshot, semio_framework_diagnostic::TextError> {
    let mut mesh = MeshData::default();
    for part in world_parts("dwg", snapshot)? {
        let base = (mesh.positions.len() / 3) as u32;
        for p in &part.positions {
            mesh.positions.extend_from_slice(&[p[0] as f32, p[1] as f32, p[2] as f32]);
        }
        for face in &part.faces {
            if face.len() < 3 {
                continue;
            }
            for i in 1..face.len() - 1 {
                mesh.indices.extend_from_slice(&[base + face[0], base + face[i], base + face[i + 1]]);
            }
        }
    }
    let drawing = mesh_to_dwg_drawing(&mesh);
    DwgSnapshot::from_drawing(&drawing).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    let snap = serialize(snapshot)?;
    let drawing = snap.drawing.to_native().map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    dwg_to_bytes(&drawing).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! 🎚️ SpaceIndexEditor view-state — the folded-directory read model slice (members/visibility) plus
//! per-artifact live presence, both host-pushed via the `fold-directory-events`/`presence-heartbeat`
//! commands (never duplicated into the shared `SSpaceSnapshot` document — contract §C4: "space
//! name/kind/visibility/members are directory-owned ... never duplicated into this document"). Local
//! view state only, mirrors `DrawConfig`'s handcrafted DSL/pack codec shape.

