//! 💠️ lowpoly -> png — a shaded isometric picture of the model: every object's world-space n-gons
//! (`world_parts`, fan-triangulated) become one `s.stdio.semio/v1/mesh` painted by that subset's own
//! view leaf. Lowpoly is y-up and the view is z-up, so `(x, y, z)` is drawn as `(x, -z, y)`.
//!
//! 🔖 `IoFidelity::Lossy`: a picture, not the model — there is no png import.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::base::schema::geometry::SemioPoint3;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::{encode_mesh, SemioMeshFormat};
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::{SemioMesh, SemioMeshSnapshot, SemioPrimitive, SemioTopology};

pub fn register() {}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    let meshes = world_parts("png", snapshot)?
        .into_iter()
        .map(|part| SemioMesh {
            id: part.name.clone(),
            primitives: vec![SemioPrimitive {
                id: part.name,
                topology: SemioTopology::Triangles,
                positions: part.positions.iter().map(|p| SemioPoint3 { x: p[0], y: -p[2], z: p[1] }).collect(),
                normals: Vec::new(),
                uvs: Vec::new(),
                colors: Vec::new(),
                indices: part.faces.iter().filter(|face| face.len() >= 3).flat_map(|face| (1..face.len() - 1).flat_map(move |i| [face[0], face[i], face[i + 1]])).collect(),
                material_id: None,
            }],
        })
        .collect();
    encode_mesh(&SemioMeshSnapshot { meshes, ..SemioMeshSnapshot::default() }, SemioMeshFormat::Png).map_err(|error| semio_framework_diagnostic::TextError::new(format!("lowpoly->png: {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! lowpoly -> txt
//!
//! 📜️ `s.stdio.txt@utf-8/*` is CARRIER_TEXT (its native `Text` payload IS the raw external file
//! text, verbatim -- see `TxtSnapshot`'s own `store::ArtifactDsl` impl doc, "CARRIER LAW"). The
//! honest lowpoly.txt representation is therefore lowpoly's OWN canonical `.lowpoly` DSL text
//! (`store::ArtifactDsl for LowpolySnapshot`, `../../../../../../🧬️schema/📸️snapshot/📝️text/🦀️.rs`)
//! carried verbatim as the txt body -- never a second bespoke grammar.
use crate::schema::snapshot::text::print_dsl;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_txt::TxtSnapshot;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<TxtSnapshot, semio_framework_diagnostic::TextError> {
    Ok(TxtSnapshot::from_body(&print_dsl(snapshot)))
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    Ok(serialize(snapshot)?.to_body().into_bytes())
}

//! lowpoly -> stl
//!
//! Real ASCII STL export through `engine::encode_stl_ascii`: every object whose persisted
//! `mesh_content` is non-empty is transformed into world space (scale -> Euler-degree rotation ->
//! translation) and each n-gon is fan-triangulated, one facet per triangle with its computed unit
//! face normal.
//!
//! 🔖 `IoFidelity::Lossy`: STL is one triangle soup — object boundaries, names, n-gons, paint and
//! transforms (already applied) do not survive.
use crate::io::mesh_geometry::{triangle_normal, world_parts};
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_stl::engine::encode_stl_ascii;
use semio_s_artifact_stdio_stl::schema::snapshot::StlTriangle;
use semio_s_artifact_stdio_stl::StlSnapshot;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<StlSnapshot, semio_framework_diagnostic::TextError> {
    let mut stl = StlSnapshot { solid_name: "lowpoly".into(), ..Default::default() };
    for part in world_parts("stl", snapshot)? {
        for face in &part.faces {
            let corner = |i: usize| part.positions[face[i] as usize];
            for i in 1..face.len() - 1 {
                let vertices = [corner(0), corner(i), corner(i + 1)];
                stl.triangles.push(StlTriangle { normal: triangle_normal(vertices[0], vertices[1], vertices[2]), vertices });
            }
        }
    }
    Ok(stl)
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    Ok(encode_stl_ascii(&serialize(snapshot)?).into_bytes())
}

//! lowpoly -> json
use crate::LowpolySnapshot;
use semio_s_artifact_stdio_json::schema::snapshot::write_json_pretty;
use semio_s_artifact_stdio_json::{JsonSnapshot, STDIO_JSON_DOCUMENT_SCHEMA};

/// 🌉 Bridges via json's own RFC8259 text codec (`JsonSnapshot::value` is `JsonValue`, json's
/// own key-order/lexeme-preserving model, not `serde_json::Value` -- see json's snapshot module).
pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<JsonSnapshot, semio_framework_diagnostic::TextError> {
    let _ = STDIO_JSON_DOCUMENT_SCHEMA;
    let value: serde_json::Value = dsl::ToValue::to_value(snapshot).into();
    Ok(JsonSnapshot::from_value(value))
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    Ok(write_json_pretty(&serialize(snapshot)?.value).into_bytes())
}

