#[value(rename_all = "camelCase")]
pub struct HomePresence {}

impl protocol::MutationDiff<HomePresence> for HomePresence {
    fn apply(&self, base: &HomePresence) -> protocol::MutationApplyResult<HomePresence> {
        Ok(base.clone())
    }
    fn absorb(&mut self, _other: Self) {}
}

impl store::ArtifactDsl for HomePresence {
    const EXTENSION: &'static str = "home.presence";
    fn envelope_id() -> &'static str {
        "home.presence"
    }
    fn parse_dsl(text: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        if text.trim().is_empty() {
            return Ok(Self::default());
        }
        Err(semio_framework_diagnostic::TextError::new("home presence", semio_framework_diagnostic::TextSpan::at(1, 1)))
    }
    fn print_dsl(&self) -> String {
        String::new()
    }
}

impl ArtifactPack for HomePresence {
    fn encode_pack_with(&self, _options: &store::PackEncodeOptions) -> Result<Vec<u8>, store::PackError> {
        Ok(Vec::new())
    }
    fn decode_pack_with(bytes: &[u8], _options: &store::PackDecodeOptions) -> Result<Self, store::PackError> {
        if bytes.is_empty() {
            return Ok(Self::default());
        }
        let (envelope, inner) = store::semio_format::unwrap_binary(bytes).map_err(|e| store::PackError::Schema(e.to_string()))?;
        if !envelope.matches_identity(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1) {
            return Err(store::PackError::Schema(format!("pack envelope mismatch: expected {}.pack v1, got {}", <Self as store::ArtifactDsl>::envelope_id(), envelope.binary_token())));
        }
        if !inner.is_empty() {
            return Err(store::PackError::Schema("home presence pack must be empty".into()));
        }
        Ok(Self::default())
    }
}
