/// 📦️ JSON text of the bundled Nakagin fixture — `RewritingSnapshot`'s own `_json` fields keep their
/// JSON contract, so the `.trinity` DSL source is parsed once and re-serialized here.
fn nakagin_fixture_json() -> String {
