//! 🏔️ Controlled terrain emission through its actual three-field native record authority.
use super::*;
use dsl::DslField;
pub(super) fn producer()->dsl::RecordSpecProducer{Terrain::__dsl_spec_producer()}
pub(super) fn project(snapshot:&GisTerrainSnapshot,control:&mut dsl::NativeEncodeControl<'_>)->Result<dsl::RecordValue,semio_framework_diagnostic::TextError>{
 control.begin_stage(3).map_err(dsl::__rt::field_error)?;
 let mut fields=dsl::native_encoding::EncodedRecord::new(3,control).map_err(dsl::__rt::field_error)?;
 fields.insert(0,control.scoped_stage(|control|{control.begin_stage(0)?;snapshot.exaggeration.to_value_controlled(control)}).map_err(dsl::__rt::field_error)?);control.step().map_err(dsl::__rt::field_error)?;
 fields.insert(1,control.scoped_stage(|control|{control.begin_stage(0)?;snapshot.imported_features_json.to_value_controlled(control)}).map_err(dsl::__rt::field_error)?);control.step().map_err(dsl::__rt::field_error)?;
 let mesh=control.scoped_stage(|control|{if let Some(child)=&snapshot.mesh{
  control.begin_stage(5).map_err(dsl::__rt::field_error)?;
  let mut owned=dsl::native_encoding::EncodedRecord::new(5,control).map_err(dsl::__rt::field_error)?;
  for(id,text)in[(0,&child.child_id),(1,&child.target.artifact_id),(2,&child.target.dialect.artifact_kind),(3,&child.target.dialect.standard),(4,&child.target.dialect.subset)]{
   owned.insert(id,control.scoped_stage(|control|{control.begin_stage(0)?;text.to_value_controlled(control)}).map_err(dsl::__rt::field_error)?);control.step().map_err(dsl::__rt::field_error)?;
  }
  Ok(dsl::FieldValue::Record(owned.take()))
 }else{Ok(dsl::FieldValue::Absent)}})?;
 fields.insert(2,mesh);control.step().map_err(dsl::__rt::field_error)?;Ok(fields.take())
}

