/// that reads `None` keeps the default scene camera, which the host fits to the world.
pub fn current<'a, C>(view: &'a semio_framework_plugin::ConfigView<'_, C>) -> Option<&'a GisMapViewerWindowConfig> {
    view.window::<GisMapViewerWindowConfigOwner>()
}

/// 🪟️ Binds one config mutation to the EXACT window instance the gesture came from — a camera is per
/// instance, so a dispatch with no addressed window, or one addressed at another window kind, is a
/// refusal rather than a write to the wrong pane.
pub fn addressed(view: &semio_framework_plugin::ViewModel, mutation: GisMapViewerWindowConfigMutation) -> Result<semio_framework_plugin::WindowConfigMutation, semio_framework_plugin::Fault> {
    let window_id = view
        .window_id
        .as_deref()
        .ok_or_else(|| semio_framework_plugin::Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("gis.map.viewer.window-required"), "a camera change requires a concrete map window"))?;
    let kind = view.window_instances.iter().find(|window| window.id == window_id).map(|window| window.window_kind_id.as_str());
    if kind != Some(super::WINDOW_KIND_ID) {
        return Err(semio_framework_plugin::Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("gis.map.viewer.window-kind"), "a camera change requires a map window"));
    }
    Ok(semio_framework_plugin::WindowConfigMutation::of::<GisMapViewerWindowConfigOwner>(window_id, mutation))
}

