//! 🩹️ `stdio_gap`/foreign-lag fix (not part of this wave's svg/dwg-pattern scope — see
//! `w5b--puzzle-report.md`): `JsonSnapshot.value` was retyped from `serde_json::Value` to stdio's
//! own lexeme-preserving `JsonValue` (own type, `#[serde(tag = "kind")]` — an intentional boundary
//! per that schema's own doc comment, NOT structurally plain JSON) by a concurrent stdio wave,
//! breaking this pre-existing leaf's compile. Fixed as a minimal lagging-call-site update: routes
//! through `JsonSnapshot::to_serde_value` (stdio's own real `JsonValue -> serde_json::Value`
//! bridge) plus stdio's own real `parse_json_text` — no hand-rolled converter here.
//!
//! 🩹️ Ticket `26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS`: no longer
//! routes through `serde_json::from_value` — `Puzzle2dSnapshot` only derives `Deserialize` under
//! `#[cfg(test)]` now. The number lexemes cross into `dsl::DslValue` through stdio's own
//! first-party `to_pack_value()` bridge, then `dsl::FromValue::from_value` hydrates the typed
//! snapshot — same shape the sibling `block2d` leaf already uses. NOT through
//! `to_serde_value()`: `serde_json`'s default (no `float_roundtrip`) number parser reconstructs an
//! f64 as `significand as f64 * 10^exponent`, which is off by one ULP for any 17-significant-digit
//! literal (`0.42839899821678995` came back as `0.4283989982167899`) and made every example whose
//! geometry needs full f64 precision fail its lossless-round-trip oracle.
use crate::Puzzle2dSnapshot;
use semio_s_artifact_stdio_json::schema::snapshot::parse_json_text;
use semio_s_artifact_stdio_json::{JsonSnapshot, STDIO_JSON_DOCUMENT_SCHEMA};

pub fn register() {}

pub fn deserialize(from: &JsonSnapshot) -> Result<Puzzle2dSnapshot, semio_framework_diagnostic::TextError> {
    let _ = STDIO_JSON_DOCUMENT_SCHEMA;
    let raw: dsl::DslValue = dsl::json::to_dsl_value(&from.to_pack_value());
    let snap: Puzzle2dSnapshot = dsl::FromValue::from_value(raw).map_err(|e| semio_framework_diagnostic::TextError::new(format!("puzzle2d<-json: {e}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    Ok(snap)
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<Puzzle2dSnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|e| semio_framework_diagnostic::TextError::new(e.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    let value = parse_json_text(text)?;
    deserialize(&JsonSnapshot::from_value(value))
}

//! 🚪️ vcs <- json — foreign `Deserializer<VcsSnapshot>` (ticket 26/08/17/CLEAN-ARTIFACT-STANDARD-
//! SUBSET-MECHANISM design.md §3). Bridges via json's own text codec (`parse_json_text`) then a
//! genuine `pack::JsonValue -> DslValue -> VcsSnapshot` structural deserialize (ticket
//! 26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS — no `serde_json` left in
//! this hop), so this hop is `IoFidelity::Exact`.

use crate::VcsSnapshot;
use dsl::FromValue;
use semio_framework::io::io_mechanism::Deserializer;
use semio_framework::io_schema::{Dialect, IoError, IoFidelity, IoOutcome, IoPayload, IoResult};
use semio_framework_plugin::{StandardId, SubsetId};
use semio_s_artifact_stdio_json::schema::snapshot::parse_json_text;
use semio_s_artifact_stdio_json::{JsonSnapshot, STDIO_JSON_DOCUMENT_SCHEMA};

pub const JSON_DIALECT: Dialect = Dialect { artifact_kind: "s.stdio.json", standard: StandardId("rfc8259"), subset: SubsetId::ANY };

pub fn deserialize(from: &JsonSnapshot) -> Result<VcsSnapshot, semio_framework_diagnostic::TextError> {
    let _ = STDIO_JSON_DOCUMENT_SCHEMA;
    VcsSnapshot::from_value(dsl::json::to_dsl_value(&from.to_pack_value())).map_err(|error| semio_framework_diagnostic::TextError::new(format!("vcs<-json: {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<VcsSnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|error| semio_framework_diagnostic::TextError::new(error.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    let value = parse_json_text(text)?;
    deserialize(&JsonSnapshot::from_value(value))
}

pub struct JsonIntoVcs;

impl Deserializer<VcsSnapshot> for JsonIntoVcs {
    const FROM: Dialect = JSON_DIALECT;
    const FIDELITY: IoFidelity = IoFidelity::Exact;
    async fn deserialize(payload: &IoPayload) -> IoResult<VcsSnapshot> {
        let IoPayload::Binary(bytes) = payload else {
            return Err(IoError { message: "JsonIntoVcs: expected a binary json payload".to_string(), diagnostics: Vec::new() });
        };
        deserialize_bytes(bytes).map(IoOutcome::clean).map_err(|error| IoError { message: format!("JsonIntoVcs: {error}"), diagnostics: Vec::new() })
    }
}

