    /// 🔧 Directional method — resultant of σ⊥, τ⊥, τ∥ with equal share assumption.
    pub fn fillet_weld_directional_n(a: f64, length: f64, f_u: f64, beta_w: f64, gamma_m2: f64, f_ed: f64) -> (f64, f64) {
