impl Default for Puzzle5dPresence {
    fn default() -> Self {
        Self { camera2d_x: 0.0, camera2d_y: 0.0, camera2d_zoom: 1.0, camera3d_position: [8.0, -8.0, 8.0], camera3d_target: [0.0, 0.0, 0.0], camera3d_zoom: 1.0}
    }
