            for source in sources {
                match source {
                    AnalyzeSource::Text(text) => match <Puzzle2dSnapshot as store::ArtifactDsl>::parse_dsl(text) {
                        Ok(snapshot) => parts.snapshot = Some(snapshot),
                        Err(err) => {
