impl<'a> Cells<'a> {
    fn new(values: &[Cell<'a>]) -> Self {
        let mut row = Self { values: [Cell::Null; 40], len: 0 };
        for value in values {
            row.push(*value);
        }
        row
    }
    fn push(&mut self, value: Cell<'a>) {
        self.values[self.len] = value;
        self.len += 1;
    }
    fn f64(&mut self, value: f64) {
