fn admit_schema(c: &SqliteSnapshotControl<'_>) -> Result<(), String> {
    let bytes = TABLES.iter().try_fold(Puzzle3dSnapshot::SQLITE_SCHEMA.len(), |sum, (name, _)| sum.checked_add(name.len()).ok_or("Puzzle3d schema count overflow"))?;
