fn forecast(v: &Puzzle3dSnapshot, c: &mut SqliteSnapshotControl<'_>, phase: SqliteSnapshotPhase) -> Result<usize, String> {
    admit_schema(c)?;
    let mut total = 2;
    c.check_rows(total)?;
    c.checkpoint(phase, 0, 0)?;
    for count in [v.meta.kind_compatibility.len(), v.attractions.len(), v.references.len().checked_mul(2).ok_or("Puzzle3d reference count overflow")?] {
        add(&mut total, count, c)?;
    }
    for (n, o) in v.objects.iter().enumerate() {
        add(&mut total, 1 + usize::from(o.scale.is_some()), c)?;
        add(&mut total, o.vortices.len(), c)?;
        if n % 256 == 0 {
            c.checkpoint(phase, n, v.objects.len())?;
        }
    }
    for (n, t) in v.target_volumes.iter().enumerate() {
        add(&mut total, 1 + usize::from(t.scale.is_some()), c)?;
        if n % 256 == 0 {
            c.checkpoint(phase, n, v.target_volumes.len())?;
        }
    }
    if let Some(e) = &v.meta.kind_catalogs {
        add(&mut total, 1, c)?;
        add(&mut total, e.cables.len(), c)?;
        add(&mut total, e.attractions.len(), c)?;
        for (n, k) in e.objects.iter().enumerate() {
            for count in [1, k.base_kinds.len(), k.vortices.len(), k.attributes.len(), k.authors.len()] {
                add(&mut total, count, c)?;
            }
            for (i, r) in k.representations.iter().enumerate() {
                add(&mut total, 1, c)?;
                add(&mut total, r.tags.len(), c)?;
                if i % 256 == 0 {
                    c.checkpoint(phase, i, k.representations.len())?;
                }
            }
            if n % 256 == 0 {
                c.checkpoint(phase, n, e.objects.len())?;
            }
        }
        for (n, k) in e.vortices.iter().enumerate() {
            add(&mut total, 1, c)?;
            add(&mut total, k.compatible_with.len(), c)?;
            if n % 256 == 0 {
                c.checkpoint(phase, n, e.vortices.len())?;
            }
        }
    }
    c.checkpoint(phase, total, total)?;
    Ok(total)
}
fn native_record(value: Option<&dsl::FieldValue>) -> Result<Option<&dsl::RecordValue>, String> {
    match value {
        None | Some(dsl::FieldValue::Absent) => Ok(None),
        Some(dsl::FieldValue::Record(record)) => Ok(Some(record)),
        Some(dsl::FieldValue::Block(value)) => native_record(Some(value)),
        _ => Err("Puzzle3d native entity requires its literal record".into()),
    }
}
fn native_list(value: Option<&dsl::FieldValue>) -> Result<&[dsl::FieldValue], String> {
    match value {
        None | Some(dsl::FieldValue::Absent) => Ok(&[]),
        Some(dsl::FieldValue::List(values)) => Ok(values),
        _ => Err("Puzzle3d native collection requires its literal list".into()),
    }
}
fn native_add(total: &mut usize, count: usize, maximum: usize) -> Result<(), String> {
    *total = total.checked_add(count).ok_or("Puzzle3d native entity count overflow")?;
    if *total > maximum {
        return Err("Puzzle3d native entity count exceeds row limit".into());
    }
    Ok(())
}
fn admit_native_rows(record: &dsl::RecordValue, maximum: usize, native: &mut dsl::NativeDecodeControl<'_>) -> Result<(), semio_framework_diagnostic::TextError> {
    native
        .scoped_stage(|native| -> Result<(), String> {
            let mut count = 2;
            native_add(&mut count, 0, maximum)?;
            if let Some(meta) = native_record(record.get(2))? {
                native_add(&mut count, native_list(meta.get(1))?.len(), maximum)?;
                if let Some(catalog) = native_record(meta.get(0))? {
                    native_add(&mut count, 1, maximum)?;
                    native_add(&mut count, native_list(catalog.get(2))?.len(), maximum)?;
                    native_add(&mut count, native_list(catalog.get(3))?.len(), maximum)?;
                    let objects = native_list(catalog.get(0))?;
                    native.begin_stage(objects.len())?;
                    for object in objects {
                        let k = native_record(Some(object))?.ok_or("Puzzle3d catalog object missing")?;
                        for number in [1, native_list(k.get(8))?.len(), native_list(k.get(10))?.len(), native_list(k.get(11))?.len(), native_list(k.get(12))?.len()] {
                            native_add(&mut count, number, maximum)?;
                        }
                        let representations = native_list(k.get(9))?;
                        native.scoped_stage(|native| -> Result<(), String> {
                            native.begin_stage(representations.len())?;
                            for representation in representations {
                                let r = native_record(Some(representation))?.ok_or("Puzzle3d representation missing")?;
                                native_add(&mut count, 1, maximum)?;
                                native_add(&mut count, native_list(r.get(4))?.len(), maximum)?;
                                native.step()?;
                            }
                            Ok(())
                        })?;
                        native.step()?;
                    }
                    let vortices = native_list(catalog.get(1))?;
                    native.begin_stage(vortices.len())?;
                    for vortex in vortices {
                        let k = native_record(Some(vortex))?.ok_or("Puzzle3d catalog vortex missing")?;
                        native_add(&mut count, 1, maximum)?;
                        native_add(&mut count, native_list(k.get(4))?.len(), maximum)?;
                        native.step()?;
                    }
                }
            }
            let objects = native_list(record.get(3))?;
            native.begin_stage(objects.len())?;
            for object in objects {
                let o = native_record(Some(object))?.ok_or("Puzzle3d object missing")?;
                native_add(&mut count, 1 + usize::from(o.get(6).is_some_and(|v| !matches!(v, dsl::FieldValue::Absent))), maximum)?;
                native_add(&mut count, native_list(o.get(8))?.len(), maximum)?;
                native.step()?;
            }
            native_add(&mut count, native_list(record.get(4))?.len(), maximum)?;
            let targets = native_list(record.get(5))?;
            native.begin_stage(targets.len())?;
            for target in targets {
                let t = native_record(Some(target))?.ok_or("Puzzle3d target missing")?;
                native_add(&mut count, 1 + usize::from(t.get(3).is_some_and(|v| !matches!(v, dsl::FieldValue::Absent))), maximum)?;
                native.step()?;
            }
            native_add(&mut count, native_list(record.get(6))?.len().checked_mul(2).ok_or("Puzzle3d native reference count overflow")?, maximum)?;
            native.checkpoint()?;
            Ok(())
        })
        .map_err(dsl::__rt::field_error)
}
