#[value(rename_all = "camelCase")]
pub struct SpatialNode {
    pub id: String,
    pub kind: SpatialKind,
    pub name: String,
    #[value(default)]
    pub parent_id: Option<String>,
    #[value(default)]
    pub placement: SemioTransform,
}
