fn write_element_class(out: &mut Vec<u8>, c: &ElementClass) {
    match c {
        ElementClass::Wall => out.push(0),
        ElementClass::Slab => out.push(1),
        ElementClass::Column => out.push(2),
        ElementClass::Beam => out.push(3),
        ElementClass::Door => out.push(4),
