fn absorb_run_diff(a: DocRunDiff, b: DocRunDiff) -> DocRunDiff {
    DocRunDiff {
        text: b.text.or(a.text),
        style: match (a.style, b.style) {
            (None, x) => x,
            (x, None) => x,
            (Some(sa), Some(sb)) => Some(absorb_run_style_diff(sa, sb)),
