            Err(_) => text,
        };
        parse_audio_snapshot_body(body).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
    }

    fn print_dsl(&self) -> String {
        let body = print_audio_snapshot_body(self);
