//! 🚦️ ZIP native ownership and literal semantic row admission under one caller control.
use super::super::{ZipSnapshot,ZipExtraField};
use semio_framework_os_kernel as store;
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,SqliteSnapshotPhase};
use store::{FieldValue,RecordValue};
use semio_framework_diagnostic::TextError;
fn error(message:impl Into<String>)->TextError{store::__rt::field_error(message)}
struct Rows{count:usize,maximum:usize}
impl Rows{fn new(maximum:usize)->Result<Self,String>{let mut result=Self{count:0,maximum};result.add(1)?;Ok(result)}fn add(&mut self,count:usize)->Result<(),String>{self.count=self.count.checked_add(count).filter(|n|*n<=self.maximum).ok_or("ZIP native semantic rows exceed caller limit")?;Ok(())}}
fn list(value:Option<&FieldValue>)->Result<&[FieldValue],TextError>{match value{None|Some(FieldValue::Absent)=>Ok(&[]),Some(FieldValue::List(values))=>Ok(values),_=>Err(error("ZIP requires an ordered native collection"))}}
fn record(value:Option<&FieldValue>)->Result<&RecordValue,TextError>{match value{Some(FieldValue::Record(value))=>Ok(value),_=>Err(error("ZIP requires its declared native metadata record"))}}
fn octets(value:Option<&FieldValue>)->Result<usize,TextError>{match value{None|Some(FieldValue::Absent)=>Ok(0),Some(FieldValue::Bytes64(value))=>Ok(value.len()),_=>Err(error("ZIP requires intrinsic base64 octets"))}}
fn legacy(value:Option<&FieldValue>)->Result<usize,TextError>{list(value).map(<[FieldValue]>::len)}
fn native_fields(values:&[FieldValue],rows:&mut Rows,native:&mut store::NativeDecodeControl<'_>)->Result<(),TextError>{
 native.scoped_stage(|native|->Result<(),TextError>{native.begin_stage(values.len()).map_err(error)?;for value in values{let value=record(Some(value))?;rows.add(1).map_err(error)?;rows.add(octets(value.fields.get(&1))?).map_err(error)?;native.step().map_err(error)?;}Ok(())})
}
fn admit_record(value:&RecordValue,maximum:usize,native:&mut store::NativeDecodeControl<'_>)->Result<(),TextError>{
 let mut rows=Rows::new(maximum).map_err(error)?;let entries=list(value.fields.get(&1))?;
 native.scoped_stage(|native|->Result<(),TextError>{native.begin_stage(entries.len()).map_err(error)?;for entry in entries{
  let entry=record(Some(entry))?;rows.add(3).map_err(error)?;rows.add(octets(entry.fields.get(&1))?).map_err(error)?;
  if matches!(entry.fields.get(&2),None|Some(FieldValue::Absent)){native.step().map_err(error)?;continue;}
  let metadata=record(entry.fields.get(&2))?;let local=record(metadata.fields.get(&1))?;let central=record(metadata.fields.get(&2))?;
  native_fields(list(local.fields.get(&4))?,&mut rows,native)?;native_fields(list(central.fields.get(&5))?,&mut rows,native)?;
  rows.add(legacy(local.fields.get(&5))?).map_err(error)?;rows.add(legacy(central.fields.get(&6))?).map_err(error)?;rows.add(legacy(central.fields.get(&8))?).map_err(error)?;
  native.step().map_err(error)?;
 }Ok(())})
}
fn fields(values:&[ZipExtraField],rows:&mut Rows,native:&mut store::NativeEncodeControl<'_>)->Result<(),String>{
 native.scoped_stage(|native|->Result<(),String>{native.begin_stage(values.len())?;for value in values{rows.add(1)?;rows.add(value.data.len())?;native.step()?;}Ok(())})
}
fn admit_snapshot(value:&ZipSnapshot,maximum:usize,native:&mut store::NativeEncodeControl<'_>)->Result<(),String>{
 let mut rows=Rows::new(maximum)?;
 native.scoped_stage(|native|->Result<(),String>{native.begin_stage(value.entries.len())?;for entry in &value.entries{
  rows.add(3)?;rows.add(entry.data.len())?;let local=&entry.metadata.local;let central=&entry.metadata.central;
  fields(&local.extra_fields,&mut rows,native)?;fields(&central.extra_fields,&mut rows,native)?;
  for bytes in [&local.unicode_path_legacy_name,&central.unicode_path_legacy_name,&central.unicode_comment_legacy]{rows.add(bytes.as_ref().map(Vec::len).unwrap_or(0))?;}native.step()?;
 }Ok(())})
}
pub(super) fn decode(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<ZipSnapshot,String>{
 control.check_rows(1)?;let maximum=control.limits().max_rows;
 store::decode_sqlite_snapshot_record_native(payload,"stdio.zip",ZipSnapshot::__dsl_spec_producer(),|record,native|{admit_record(record,maximum,native)?;ZipSnapshot::__dsl_from_record_controlled(record,native)},control)
}
pub(super) fn encode(snapshot:&ZipSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,String>{
 control.check_rows(1)?;let limits=control.limits();
 let mut callback=|event:semio_framework_value::native_encoding::NativeEncodeProgress|control.checkpoint(SqliteSnapshotPhase::EncodeNative,event.completed,event.total).is_ok();
 let mut native=store::NativeEncodeControl::new(limits.max_value_bytes,&mut callback);admit_snapshot(snapshot,limits.max_rows,&mut native)?;
 store::encode_sqlite_snapshot_record_native(encoding,"stdio.zip",ZipSnapshot::__dsl_spec_producer(),|native|snapshot.__dsl_to_record_controlled(native),control)
}

//! 🧬️ SemioMutation — the envelope union's own mutation vocabulary. The 18 wrapper variants each
//! carry that subset's OWN, already-real, already-hand-written `SemioXMutation` enum unchanged
//! (`SemioBrepMutation`, `SemioAudioMutation`, …) — every `diff()`/`inverse()` for a wrapped
//! variant delegates straight through to that subset's own `Mutation` impl, so this module never
//! re-derives any of the 18 subsets' own per-field mutation logic; its OWN job is purely the
//! envelope-level routing (does the wrapped mutation's kind match the base snapshot's current
//! kind, and if so thread it through).
//!
//! 🪆️ Mutation-leaf migration: `NoMutation` is dropped (the derive requires every variant to wrap
//! exactly one leaf payload, and `no` is not an approved semantic verb). `#[derive(dsl::Mutations)]`
//! requires each variant's payload to directly implement `protocol::MutationKind<SemioSnapshot,
//! SemioMutation>` + `protocol::MutationLeaf`, and `MutationLeaf`'s provenance is validated against
//! the FILE the `#[derive(dsl::MutationLeaf)]` macro expands in — a subset's own `SemioXMutation` is
//! defined in ITS OWN aggregate file, not under `✉️base/🧬️schema/🧬️mutations/`, so it cannot serve as
//! the direct leaf payload itself. Each of the 18 wrapper variants therefore wraps a THIN leaf struct
//! (`<emoji><kind>/🦀️.rs`, e.g. `🧱brep/🦀️.rs`'s `pub struct Brep { pub(crate) mutation:
//! SemioBrepMutation }`) whose own `MutationKind` impl still does nothing but delegate straight
//! through to the wrapped subset's already-real `Mutation` impl via `agg_diff`/`agg_inverse` — the
//! envelope still routes, it still never redefines a wrapped subset's own vocabulary.
//!
//! Some of the 18 wrapped subsets are migrated onto this same leaf pattern (`model`, `document`,
//! `cad`, `image`, `video`, `audio`, `animation`, `presentation`, `value`, `table`, `graph`,
//! `object`, `kit` — no `NoMutation`/`Default` of their own any more, so their harmless
//! representative case below is `SetSnapshot` with a default snapshot); `flow` is not yet migrated
//! (still carries its own `NoMutation`/`Default`), so its representative case uses `::default()`
//! until its own lane migrates it.

