            Quantity::new(QuantityKind::Dimensionless, 100.0),
            loc(
                "Areal mass is recorded for Table 3 column selection (informational Pass).",
                "Flächenbezogene Masse wird für die Tab.3-Spalte erfasst (informativ bestanden).",
            ),
        ))
