        DxfEntityDiff::Line(x) => x == &DxfLineDiff::default(),
        DxfEntityDiff::Circle(x) => x == &DxfCircleDiff::default(),
        DxfEntityDiff::Arc(x) => x == &DxfArcDiff::default(),
        DxfEntityDiff::Polyline(x) => x == &DxfPolylineDiff::default(),
