    <EquationSnapshot as ArtifactDsl>::parse_dsl(text)
}

/// 🖨️ Prints a `EquationSnapshot` back to `.equation` DSL text.
pub fn print_dsl(projection: &EquationSnapshot) -> String {
    ArtifactDsl::print_dsl(projection)
}
