//! 🛫️ Paid flat Equation records preserve the exact authored expression and child addresses.
use super::*;
use dsl::NativeEncodeControl;
fn child_paid(id:&str,target:&store::os_io::ArtifactRef,c:&mut NativeEncodeControl<'_>)->Result<Child,String>{Ok(Child{child_id:c.copy_text(id)?,artifact_id:c.copy_text(&target.artifact_id)?,artifact_kind:c.copy_text(&target.dialect.artifact_kind)?,standard:c.copy_text(&target.dialect.standard)?,subset:c.copy_text(&target.dialect.subset)?})}
fn children(node:&EquationNode)->impl Iterator<Item=&EquationNode>{let(slice,first,second):(&[EquationNode],Option<&EquationNode>,Option<&EquationNode>)=match&node.kind{EquationNodeKind::Add{terms}=>(terms,None,None),EquationNodeKind::Mul{factors}=>(factors,None,None),EquationNodeKind::Pow{base,exponent}=>(&[],Some(base),Some(exponent)),_=>(&[],None,None)};slice.iter().chain(first).chain(second)}
fn frontier<'a>(snapshot:&'a EquationSnapshot,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<Vec<&'a EquationNode>,String>{
 c.scoped_stage(|c|{c.begin_stage(0)?;let mut rows=5usize;if rows>maximum{return Err("Equation semantic row limit exceeded".into())}let mut nodes=c.allocate_vec(1)?;nodes.push(&snapshot.equation.expr);let mut index=0;while index<nodes.len(){let node=nodes[index];let child_count=match&node.kind{EquationNodeKind::Add{terms}=>terms.len(),EquationNodeKind::Mul{factors}=>factors.len(),EquationNodeKind::Pow{..}=>2,_=>0};let edges=if matches!(node.kind,EquationNodeKind::Add{..}|EquationNodeKind::Mul{..}){child_count}else{0};rows=rows.checked_add(2).and_then(|rows|rows.checked_add(edges)).ok_or("Equation semantic row count overflow")?;let minimum=nodes.len().checked_sub(index+1).and_then(|count|count.checked_add(child_count)).and_then(|count|count.checked_mul(2)).and_then(|count|count.checked_add(rows)).ok_or("Equation semantic row count overflow")?;if minimum>maximum{return Err("Equation semantic row limit exceeded".into())}let required=nodes.len().checked_add(child_count).ok_or("Equation frontier overflow")?;if required>nodes.capacity(){let extra=required-nodes.capacity();c.charge(extra.checked_mul(std::mem::size_of::<&EquationNode>()).ok_or("Equation frontier allocation overflow")?)?;nodes.try_reserve_exact(required-nodes.len()).map_err(|_|"Equation frontier allocation failed")?;}c.scoped_stage(|c|{c.begin_stage(child_count)?;for child in children(node){nodes.push(child);c.step()?;}Ok::<_,String>(())})?;index+=1;c.step()?;}Ok(nodes)})
}
pub(super) fn project(snapshot:&EquationSnapshot,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<dsl::RecordValue,semio_framework_diagnostic::TextError>{
 let result=(||->Result<dsl::RecordValue,String>{let source=frontier(snapshot,maximum,c)?;c.begin_stage(source.len())?;let mut nodes=c.allocate_vec(source.len())?;let mut next=1u64;
  for value in source{let mut node=Node{label:value.label.0,kind:Kind::Integer,lexeme:None,numer:None,denom:None,name:None,terms:Vec::new(),factors:Vec::new(),base:None,exponent:None};match&value.kind{
   EquationNodeKind::Integer{lexeme}=>node.lexeme=Some(c.copy_text(lexeme)?),
   EquationNodeKind::Rational{numer,denom}=>{node.kind=Kind::Rational;node.numer=Some(c.copy_text(numer)?);node.denom=Some(c.copy_text(denom)?);},
   EquationNodeKind::Symbol{name}=>{node.kind=Kind::Symbol;node.name=Some(c.copy_text(name)?);},
   EquationNodeKind::Add{terms}|EquationNodeKind::Mul{factors:terms}=>{let mut indices=c.allocate_vec(terms.len())?;c.scoped_stage(|c|{c.begin_stage(terms.len())?;for _ in terms{indices.push(next);next=next.checked_add(1).ok_or("Equation child identity overflow")?;c.step()?;}Ok::<_,String>(())})?;if matches!(value.kind,EquationNodeKind::Add{..}){node.kind=Kind::Add;node.terms=indices;}else{node.kind=Kind::Mul;node.factors=indices;}},
   EquationNodeKind::Pow{..}=>{node.kind=Kind::Pow;node.base=Some(next);node.exponent=Some(next.checked_add(1).ok_or("Equation child identity overflow")?);next=next.checked_add(2).ok_or("Equation child identity overflow")?;}
  }nodes.push(node);c.step()?;}
  let value=EquationPackRecord{notation:child_paid(&snapshot.notation.child_id,&snapshot.notation.target,c)?,results:child_paid(&snapshot.results.child_id,&snapshot.results.target,c)?,computed:child_paid(&snapshot.computed.child_id,&snapshot.computed.target,c)?,equation:Expression{next_label:snapshot.equation.next_label,nodes}};value.__dsl_to_record_controlled(c).map_err(|error|error.message)
 })();result.map_err(dsl::__rt::field_error)
}

//! 📦️ Equation artifact — binary document surface + laws (constitutional: pack). The
//! `store::ArtifactPack` impl for `EquationSnapshot` encodes the derived `EquationPackRecord` spec.

use crate::EquationSnapshot;
use store::PackError;

//#region 📡️SemioProtocol
/// 📡️ Normative handcrafted binary protocol for this facet (`dialect protocol`).
pub const COMPONENT_PROTOCOL_SEMIO: &str = include_str!("📡️.protocol.semio");
pub const COMPONENT_PROTOCOL_PATH: &str = concat!(module_path!(), "::📡️.protocol.semio");
//#endregion 📡️SemioProtocol

use crate::standards::v1::subsets::any::schema::snapshot::{EquationNode,EquationNodeLabel,EquationNodeKind,EquationExprSnapshot};
#[derive(dsl::DslRecord)]
struct Child{child_id:String,artifact_id:String,artifact_kind:String,standard:String,subset:String}
#[derive(dsl::DslScalar)]
enum Kind{Integer,Rational,Symbol,Add,Mul,Pow}
#[derive(dsl::DslRecord)]
struct Node{label:u64,kind:Kind,lexeme:Option<String>,numer:Option<String>,denom:Option<String>,name:Option<String>,terms:Vec<u64>,factors:Vec<u64>,base:Option<u64>,exponent:Option<u64>}
#[derive(dsl::DslRecord)]
struct Expression{next_label:u64,nodes:Vec<Node>}
#[derive(dsl::DslRecord)]
#[dsl(extension="equation")]
struct EquationPackRecord{notation:Child,results:Child,computed:Child,equation:Expression}
fn child(child_id:&str,target:&store::os_io::ArtifactRef)->Child{Child{child_id:child_id.into(),artifact_id:target.artifact_id.clone(),artifact_kind:target.dialect.artifact_kind.clone(),standard:target.dialect.standard.clone(),subset:target.dialect.subset.clone()}}
fn target(value:Child)->(String,store::os_io::ArtifactRef){(value.child_id,store::os_io::ArtifactRef{artifact_id:value.artifact_id,dialect:store::os_io::ArtifactDialect{artifact_kind:value.artifact_kind,standard:value.standard,subset:value.subset}})}
fn retire_node(node:EquationNode){let mut pending=vec![node];while let Some(node)=pending.pop(){match node.kind{EquationNodeKind::Add{terms}=>pending.extend(terms),EquationNodeKind::Mul{factors}=>pending.extend(factors),EquationNodeKind::Pow{base,exponent}=>{pending.push(*base);pending.push(*exponent);},_=>{}}}}
struct Values(Vec<Option<EquationNode>>);
impl Drop for Values{fn drop(&mut self){for value in self.0.iter_mut().filter_map(Option::take){retire_node(value);}}}
fn owned_child(values:&mut[Option<EquationNode>],parent:usize,key:u64)->Result<EquationNode,String>{let key=usize::try_from(key).map_err(|_|"Equation child index exceeds native domain")?;if key<=parent||key>=values.len(){return Err("Equation child topology differs".into())}values[key].take().ok_or_else(||"Equation child has repeated owner".into())}
fn group(values:&mut[Option<EquationNode>],parent:usize,keys:Vec<u64>)->Result<Vec<EquationNode>,String>{let mut result=Values(Vec::with_capacity(keys.len()));for key in keys{result.0.push(Some(owned_child(values,parent,key)?));}Ok(result.0.iter_mut().filter_map(Option::take).collect())}
impl EquationPackRecord{
