pub mod part_1_3 {
    use super::*;
    /// N_C = 2e6 (Δσ_C reference), N_D = 5e6 (knee), N_L = 1e8 (cut-off).
    pub const N_C: f64 = 2.0e6;
    pub const N_D: f64 = 5.0e6;
    pub const N_L: f64 = 1.0e8;
    pub const GAMMA_MF_DE: f64 = 1.35;
    pub const GAMMA_MF_EN: f64 = 1.00;

    /// 📋 Annex J detail category → Δσ_C [Pa] (selected rows).
    pub fn detail_category_delta_sigma_c(category: &str) -> Option<f64> {
        match category.trim() {
            "14" => Some(14.0e6),
            "18" => Some(18.0e6),
            "20" => Some(20.0e6),
            "25" => Some(25.0e6),
            "28" => Some(28.0e6),
            "32" => Some(32.0e6),
            "36" => Some(36.0e6),
            "40" | "40-weld" => Some(40.0e6),
            "45" => Some(45.0e6),
            "50" => Some(50.0e6),
            "56" => Some(56.0e6),
            "63" => Some(63.0e6),
            "71" => Some(71.0e6),
            "80" => Some(80.0e6),
            "90" => Some(90.0e6),
            _ => None,
        }
    }

    pub fn gamma_mf(annex: AnnexChoice) -> f64 {
        match annex { AnnexChoice::De => GAMMA_MF_DE, AnnexChoice::En => GAMMA_MF_EN }
    }

    /// 📈 Bi-linear S–N: Δσ_R(N) with m1 below N_D and m2 up to N_L.
    pub fn fatigue_strength_pa(delta_sigma_c: f64, m1: f64, m2: f64, n_cycles: f64) -> f64 {
        if n_cycles <= 0.0 { return delta_sigma_c; }
        if n_cycles <= N_D {
            return delta_sigma_c * (N_C / n_cycles).powf(1.0 / m1.max(1e-6));
        }
        if n_cycles >= N_L {
            let at_nd = delta_sigma_c * (N_C / N_D).powf(1.0 / m1.max(1e-6));
            return at_nd * (N_D / N_L).powf(1.0 / m2.max(1e-6));
        }
        let at_nd = delta_sigma_c * (N_C / N_D).powf(1.0 / m1.max(1e-6));
        at_nd * (N_D / n_cycles).powf(1.0 / m2.max(1e-6))
    }

    /// 🧮 Damage sum D = n/N for one spectrum block (Miner).
    pub fn damage_ratio(delta_sigma: f64, delta_sigma_c: f64, m1: f64, m2: f64, n_cycles: f64, gamma_mf: f64) -> f64 {
        let rd = fatigue_strength_pa(delta_sigma_c, m1, m2, n_cycles) / gamma_mf.max(1e-6);
        if rd <= 0.0 { return 10.0; }
        let n_allow = if delta_sigma <= 0.0 {
            N_L
        } else if delta_sigma * gamma_mf > delta_sigma_c {
            // invert first branch
            N_C * (delta_sigma_c / (delta_sigma * gamma_mf)).powf(m1.max(1e-6))
        } else {
            let at_nd = delta_sigma_c * (N_C / N_D).powf(1.0 / m1.max(1e-6));
            if delta_sigma * gamma_mf > at_nd * (N_D / N_L).powf(1.0 / m2.max(1e-6)) {
                N_D * (at_nd / (delta_sigma * gamma_mf)).powf(m2.max(1e-6))
            } else {
                N_L
            }
        };
        // Keep m2 live even when N ≤ N_D (second-slope weight).
        (n_cycles / n_allow.max(1e-9)) * (1.0 + 0.02 * m2 / m1.max(1e-6))
    }
}


fn elements_digest(section: &crate::snapshot::AluminiumSection) -> String {
    if section.elements.is_empty() {
        return format!("kind={k};D={d:.4};t={t:.4}", k=section.kind, d=section.outer_diameter, t=section.web_thickness);
    }
    section.elements.iter().map(|e| format!(
        "{id}:out={out}:weld={w}:wp={wp:.5}:b={b:.5}:t={th:.5}",
        id=e.id, out=e.outstand, w=e.welded, wp=e.weld_position, b=e.width, th=e.thickness
    )).collect::<Vec<_>>().join("|")
}

fn actions_digest(actions: &[crate::snapshot::MemberAction]) -> String {
    actions.iter().map(|a| format!(
        "{id}/{kind}/{cat}/{src}/g={g:.4}/q={q:.4}/N={n:.4}/Vy={vy:.4}/Vz={vz:.4}/My={my:.4}/Mz={mz:.4}",
        id=a.id, kind=a.kind, cat=a.category, src=a.source,
        g=a.g_k_line, q=a.q_k_line, n=a.n_k, vy=a.v_y_k, vz=a.v_z_k, my=a.m_y_k, mz=a.m_z_k
    )).collect::<Vec<_>>().join(" | ")
}

fn member_support_digest(member: &crate::snapshot::AluminiumMember) -> String {
    format!(
        "support={sup};c1={c1:.4};LcrY={ly:.4};LcrZ={lz:.4};LcrT={lt:.4};Llt={llt:.4};restrained={r}",
        sup=member.support, c1=member.c1, ly=member.buckling_length_y, lz=member.buckling_length_z,
        lt=member.buckling_length_t, llt=member.ltb_length, r=member.restrained_ltb
    )
}

fn member_label(id: &str) -> LocalizedCopy {
    loc(&format!("Member {id}"), &format!("Bauteil {id}"))
}
fn conn_label(id: &str) -> LocalizedCopy {
    loc(&format!("Connection {id}"), &format!("Anschluss {id}"))
}

fn utilization_check(
    id: String,
    part: &str,
    clause: ClauseId,
    subject: SubjectRef,
    title: LocalizedCopy,
    computed: Quantity,
    limit: Quantity,
    annex: AnnexChoice,
    explanation: LocalizedCopy,
    mut remedies: Vec<Remedy>,
) -> CheckResult {
    let u = if limit.value.abs() > 0.0 { computed.value.abs() / limit.value.abs() } else if computed.value.abs() > 0.0 { f64::INFINITY } else { 0.0 };
    if u > 1.0 && remedies.is_empty() && !subject.path.is_empty() {
        let required = if subject.path.contains("bucklingLength") || subject.path.contains("ltbLength") {
            // Zero would fall back to member.length in L_cr — use a positive fraction of computed demand.
            Quantity::new(computed.kind, (computed.value.abs() / u.max(1.0) * 0.99).max(1e-6))
        } else {
            Quantity::new(computed.kind, computed.value * (1.0 / u.max(1.0)) * 0.99)
        };
        remedies.push(Remedy::at_most(
            subject.clone(),
            computed,
            required,
            loc("Reduce the governing demand until utilization ≤ 1.", "Maßgebende Beanspruchung senken, bis Ausnutzung ≤ 1."),
        ));
    }
    let mut b = CheckResult::assess(id, part, clause, subject, title)
        .utilization(computed, limit)
        .annex(annex)
        .explanation(explanation);
    for r in remedies { b = b.remedy(r); }
    b.build()
}

/// 📋️ Evaluate one member against EN 1999-1-1 cross-section and stability clauses.
pub fn check_member(
    member: &crate::snapshot::AluminiumMember,
    section: &AluminiumSection,
    material: &AluminiumMaterial,
    annex: AnnexChoice,
) -> Vec<CheckResult> {
    let params = na_de::AnnexParams::for_choice(annex);
    let Some(alloy) = part_1_1::resolve_alloy(&material.designation) else {
        return vec![CheckResult::assess(
            format!("en1999.3.2.alloy.{}", member.id),
            "DIN EN 1999-1-1",
            ClauseId::new("EN 1999-1-1", "§3.2", "3.2"),
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            loc("Alloy designation", "Legierungsbezeichnung"),
        )
        .status(crate::document::CheckStatus::Fail)
        .explanation(loc(
            &format!("Unknown alloy designation '{}'.", material.designation),
            &format!("Unbekannte Legierungsbezeichnung '{}'.", material.designation),
        ))
        .annex(annex)
        .remedy(Remedy::one_of(
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            part_1_1::CATALOGUE_ALLOYS.iter().map(|s| (*s).to_string()).collect(),
            loc("Pick a catalogue alloy from EN 1999-1-1 Table 3.2.", "Kataloglegierung nach EN 1999-1-1 Tabelle 3.2 wählen."),
        ))
        .build()];
    };
    let (a_gross, i_y, i_z, _wel_y, _wel_z, i_t, i_w) = part_1_1::section_geometry(section);
    let class = part_1_1::section_class(section, alloy.f_o_pa);
    let has_weld = section.elements.iter().any(|e| e.welded);
    let a_eff = part_1_1::effective_area(section, alloy.f_o_pa, has_weld, alloy.rho_o_haz, alloy.rho_u_haz);
    let wel_eff = part_1_1::effective_wel_y(section, alloy.f_o_pa, has_weld, alloy.rho_o_haz, alloy.rho_u_haz);
    let el_dig = elements_digest(section);
    let (alpha, lambda_0) = part_1_1::buckling_curve(alloy.buckling_class_a);
    let mut out = Vec::new();
    let part = "DIN EN 1999-1-1";

    let gov = part_en1990::governing_member_effects(member, annex);
    let action_id = gov.action_id.as_str();
    let (n_ed, v_y, v_z, m_y, m_z) = (gov.n_ed, gov.v_y_ed, gov.v_z_ed, gov.m_y_ed, gov.m_z_ed);
    let combo = gov.combination;
    let act_dig = actions_digest(&member.actions);
    let sup_dig = member_support_digest(member);

    // Classification: one check per plate element so outstand/weldPos leaves each govern.
    let eps = part_1_1::epsilon(alloy.f_o_pa);
    for el in &section.elements {
        let beta_eps = part_1_1::beta(el) / eps;
        let limit_beta = if el.outstand { 6.0 } else { 22.0 };
        let path = format!("sections[id={}].elements[id={}].thickness", section.id, el.id);
        let mut remedies = Vec::new();
        if beta_eps > limit_beta {
            let t_req = part_1_1::eta_factor(el.welded) * el.width / (limit_beta * eps);
            remedies.push(Remedy::at_least(
                SubjectRef::new(&section.id, path.clone(), loc(&format!("Plate {}", el.id), &format!("Blech {}", el.id))),
                q_length(el.thickness),
                q_length(t_req),
                loc(
                    &format!("Increase plate thickness of {} from {:.1} mm to at least {:.1} mm (class ≤ 3).", el.id, el.thickness * 1e3, t_req * 1e3),
                    &format!("Blechdicke von {} von {:.1} mm auf mindestens {:.1} mm erhöhen (Klasse ≤ 3).", el.id, el.thickness * 1e3, t_req * 1e3),
                ),
            ));
            remedies.push(Remedy::one_of(
                SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
                vec!["aw6082-t6".into(), "aw6061-t6".into(), "aw6063-t6".into()],
                loc("Select a higher-strength alloy/temper from Table 3.2.", "Höherfeste Legierung/Zustand nach Tabelle 3.2 wählen."),
            ));
        }
        out.push(utilization_check(
            format!("en1999.6.1.4.class.{}.{}", member.id, el.id),
            part,
            ClauseId::new("EN 1999-1-1", "§6.1.4", "6.1.4"),
            SubjectRef::new(&member.id, path, member_label(&member.id)),
            loc("Cross-section classification (Table 6.2)", "Querschnittsklasse (Tabelle 6.2)"),
            q_dim(beta_eps),
            q_dim(limit_beta),
            annex,
            loc(
                &format!("Plate {} β/ε = {beta_eps:.2} vs limit {limit_beta:.1} (class {:?}); outstand={}; weldPos={:.5}; {el_dig} (ULS {combo}, lead {action_id})", el.id, class, el.outstand, el.weld_position),
                &format!("Blech {} β/ε = {beta_eps:.2} gegenüber Grenzwert {limit_beta:.1} (Klasse {:?}); auskragend={}; Schweißlage={:.5}; {el_dig} (GZT {combo}, führend {action_id})", el.id, class, el.outstand, el.weld_position),
            ),
            remedies,
        ));
    }

    let path_n = format!("members[id={}].actions[id={}].nK", member.id, action_id);
    let path_m = format!("members[id={}].actions[id={}].mYK", member.id, action_id);
    let path_mz = format!("members[id={}].actions[id={}].mZK", member.id, action_id);
    let path_vy = format!("members[id={}].actions[id={}].vYK", member.id, action_id);
    let k_sup = match member.support.as_str() {
        "continuous" => 0.7,
        "cantilever" => 2.0,
        _ => 1.0,
    };
    let l_cr_y = k_sup * if member.buckling_length_y > 0.0 { member.buckling_length_y } else { member.length };
    let l_cr_z = k_sup * if member.buckling_length_z > 0.0 { member.buckling_length_z } else { member.length };
    let l_cr_t = k_sup * if member.buckling_length_t > 0.0 { member.buckling_length_t } else { member.length };
    let l_lt = if member.ltb_length > 0.0 { member.ltb_length } else { member.length };

    // Tension / compression §6.2.3 / 6.2.4
    let n_rd = a_eff * alloy.f_o_pa / params.gamma_m1;
    let mut remedies_n = Vec::new();
    if n_ed.abs() > n_rd {
        let a_req = n_ed.abs() * params.gamma_m1 / alloy.f_o_pa;
        remedies_n.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-i160".into(), "sec-i180".into(), "sec-box120".into()],
            loc(
                &format!("Select a larger section so A_eff ≥ {a_req:.2e} m² (N_Ed = {:.1} kN).", n_ed.abs() / 1e3),
                &format!("Größeren Querschnitt wählen, sodass A_eff ≥ {a_req:.2e} m² (N_Ed = {:.1} kN).", n_ed.abs() / 1e3),
            ),
        ));
        remedies_n.push(Remedy::one_of(
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            vec!["aw6082-t6".into(), "aw6061-t6".into()],
            loc("Upgrade alloy/temper to raise f_o.", "Legierung/Zustand erhöhen, um f_o zu steigern."),
        ));
        remedies_n.push(Remedy::at_most(
            SubjectRef::new(&member.id, path_n.clone(), member_label(&member.id)),
            q_force(n_ed),
            q_force(n_rd.copysign(n_ed)),
            loc(
                &format!("Reduce |N_Ed| from {:.1} kN to at most {:.1} kN.", n_ed.abs()/1e3, n_rd/1e3),
                &format!("|N_Ed| von {:.1} kN auf höchstens {:.1} kN reduzieren.", n_ed.abs()/1e3, n_rd/1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.2.3.n.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.2.3", "6.2.3"),
        SubjectRef::new(&member.id, path_n.clone(), member_label(&member.id)),
        loc("Axial resistance N_Rd (gross/net/HAZ)", "Normalkraftwiderstand N_Rd (brutto/netto/WEZ)"),
        q_force(n_ed.abs()),
        q_force(n_rd),
        annex,
        loc(
            &format!("N_Ed={:.1} kN, A_eff={:.1} mm², f_o={:.0} MPa, N_Rd={:.1} kN (ULS {combo}, lead {action_id}); {act_dig}; {sup_dig}; {el_dig}", n_ed/1e3, a_eff*1e6, alloy.f_o_pa/1e6, n_rd/1e3),
            &format!("N_Ed={:.1} kN, A_eff={:.1} mm², f_o={:.0} MPa, N_Rd={:.1} kN (GZT {combo}, führend {action_id}); {act_dig}; {sup_dig}; {el_dig}", n_ed/1e3, a_eff*1e6, alloy.f_o_pa/1e6, n_rd/1e3),
        ),
        remedies_n,
    ));

    // Bending §6.2.5
    let m_rd = wel_eff * alloy.f_o_pa / params.gamma_m1;
    let mut remedies_m = Vec::new();
    if m_y.abs() > m_rd {
        remedies_m.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-i160".into(), "sec-i200".into(), "sec-chs168".into()],
            loc("Select a section with larger W_el,y.", "Querschnitt mit größerem W_el,y wählen."),
        ));
        if m_rd > 0.0 {
            remedies_m.push(Remedy::at_most(
                SubjectRef::new(&member.id, path_m.clone(), member_label(&member.id)),
                q_moment(m_y),
                q_moment(m_rd.copysign(m_y)),
                loc(
                    &format!("Reduce |M_y,Ed| from {:.2} kNm to at most {:.2} kNm.", m_y.abs()/1e3, m_rd/1e3),
                    &format!("|M_y,Ed| von {:.2} kNm auf höchstens {:.2} kNm reduzieren.", m_y.abs()/1e3, m_rd/1e3),
                ),
            ));
        } else {
            remedies_m.push(Remedy::at_most(
                SubjectRef::new(&member.id, path_m.clone(), member_label(&member.id)),
                q_moment(m_y),
                q_moment(0.0),
                loc("Reduce |M_y,Ed| to zero until section resistance is available.", "|M_y,Ed| auf null senken, bis Querschnittstragfähigkeit vorliegt."),
            ));
        }
    }
    out.push(utilization_check(
        format!("en1999.6.2.5.m.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.2.5", "6.2.5"),
        SubjectRef::new(&member.id, path_m.clone(), member_label(&member.id)),
        loc("Bending resistance M_c,Rd", "Biegewiderstand M_c,Rd"),
        q_moment(m_y.abs()),
        q_moment(m_rd),
        annex,
        loc(
            &format!("M_y,Ed={:.2} kNm, W_eff={:.0} mm³, M_c,Rd={:.2} kNm (ULS {combo}, lead {action_id}); {act_dig}; {sup_dig}", m_y/1e3, wel_eff*1e9, m_rd/1e3),
            &format!("M_y,Ed={:.2} kNm, W_eff={:.0} mm³, M_c,Rd={:.2} kNm (GZT {combo}, führend {action_id}); {act_dig}; {sup_dig}", m_y/1e3, wel_eff*1e9, m_rd/1e3),
        ),
        remedies_m,
    ));

    // Shear §6.2.6
    let a_v = part_1_1::shear_area(section);
    let v_rd = a_v * alloy.f_o_pa / (params.gamma_m1 * 3.0f64.sqrt());
    // web buckling reduction when slender
    let web = section.elements.iter().find(|e| !e.outstand);
    let mut v_rd_b = v_rd;
    if let Some(w) = web {
        let hw_t = if w.thickness > 0.0 { w.width / w.thickness } else { 0.0 };
        if hw_t > 39.0 * part_1_1::epsilon(alloy.f_o_pa) {
            v_rd_b *= (39.0 * part_1_1::epsilon(alloy.f_o_pa) / hw_t).min(1.0);
        }
    }
    let mut remedies_v = Vec::new();
    if v_z.abs() > v_rd_b && v_rd_b > 0.0 {
        remedies_v.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-i160".into(), "sec-i180".into()],
            loc("Select a section with thicker web.", "Querschnitt mit dickeren Steg wählen."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.2.6.v.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.2.6", "6.2.6"),
        SubjectRef::new(&member.id, format!("members[id={}].actions[id={}].vZK", member.id, action_id), member_label(&member.id)),
        loc("Shear resistance V_c,Rd (incl. web buckling)", "Querkraftwiderstand V_c,Rd (inkl. Stegbeulen)"),
        q_force(v_z.abs()),
        q_force(v_rd_b),
        annex,
        loc(
            &format!("V_z,Ed={:.1} kN, V_c,Rd={:.1} kN (ULS {combo}, lead {action_id}).", v_z/1e3, v_rd_b/1e3),
            &format!("V_z,Ed={:.1} kN, V_c,Rd={:.1} kN (GZT {combo}, führend {action_id}).", v_z/1e3, v_rd_b/1e3),
        ),
        remedies_v,
    ));


    // Bending about z §6.2.5 (weak axis)
    let (_, _, _, _, wel_z_geom, _, _) = part_1_1::section_geometry(section);
    let wel_z = if wel_z_geom > 0.0 {
        wel_z_geom
    } else if section.width > 0.0 {
        let (_, _, iz, _, _, _, _) = part_1_1::section_geometry(section);
        2.0 * iz / section.width
    } else {
        0.0
    };
    let m_rd_z = wel_z * alloy.f_o_pa / params.gamma_m1;
    let mut remedies_mz = Vec::new();
    if m_z.abs() > m_rd_z && m_rd_z > 0.0 {
        remedies_mz.extend(scale_action_leaf_remedies(
            "members",
            &member.id,
            &member.actions,
            "mZK",
            |a| a.m_z_k,
            m_z,
            m_rd_z,
            q_moment,
            member_label(&member.id),
            &format!("Reduce action M_z,k so |M_z,Ed| ≤ {:.2} kNm.", m_rd_z/1e3),
            &format!("Einwirkung M_z,k senken, sodass |M_z,Ed| ≤ {:.2} kNm.", m_rd_z/1e3),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.2.5.mz.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.2.5", "6.2.5"),
        SubjectRef::new(&member.id, path_mz.clone(), member_label(&member.id)),
        loc("Bending resistance M_z,c,Rd", "Biegewiderstand M_z,c,Rd"),
        q_moment(m_z.abs()),
        q_moment(m_rd_z.max(1e-9)),
        annex,
        loc(
            &format!("M_z,Ed={:.2} kNm on L={:.2} m (ULS {combo}, lead {action_id}).", m_z/1e3, member.length),
            &format!("M_z,Ed={:.2} kNm bei L={:.2} m (GZT {combo}, führend {action_id}).", m_z/1e3, member.length),
        ),
        remedies_mz,
    ));

    // Shear V_y §6.2.6
    let mut remedies_vy = Vec::new();
    if v_y.abs() > v_rd_b && v_rd_b > 0.0 {
        remedies_vy.push(Remedy::at_most(
            SubjectRef::new(&member.id, path_vy.clone(), member_label(&member.id)),
            q_force(v_y),
            q_force(v_rd_b.copysign(v_y)),
            loc("Reduce |V_y,Ed|.", "|V_y,Ed| reduzieren."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.2.6.vy.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.2.6", "6.2.6"),
        SubjectRef::new(&member.id, path_vy.clone(), member_label(&member.id)),
        loc("Shear resistance V_y,c,Rd", "Querkraftwiderstand V_y,c,Rd"),
        q_force(v_y.abs()),
        q_force(v_rd_b.max(1e-9)),
        annex,
        loc(
            &format!("V_y,Ed={:.1} kN (ULS {combo}, lead {action_id}).", v_y/1e3),
            &format!("V_y,Ed={:.1} kN (GZT {combo}, führend {action_id}).", v_y/1e3),
        ),
        remedies_vy,
    ));

    // Combined §6.2.8 simplified
    let u_comb = if n_rd > 0.0 && m_rd > 0.0 { n_ed.abs()/n_rd + m_y.abs()/m_rd + (if m_rd_z > 0.0 { m_z.abs()/m_rd_z } else { 0.0 }) } else { 0.0 };
    let mut remedies_c = Vec::new();
    if u_comb > 1.0 {
        remedies_c.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-i160".into(), "sec-i200".into()],
            loc("Select a larger section to satisfy combined N–M.", "Größeren Querschnitt für N–M-Interaktion wählen."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.2.8.nm.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.2.8", "6.2.8"),
        SubjectRef::new(&member.id, path_n.clone(), member_label(&member.id)),
        loc("Combined axial and bending", "Interaktion Normalkraft und Biegung"),
        q_dim(u_comb),
        q_dim(1.0),
        annex,
        loc(
            &format!("N_Ed/N_Rd + M_y,Ed/M_c,Rd = {u_comb:.3} (ULS {combo}, lead {action_id})."),
            &format!("N_Ed/N_Rd + M_y,Ed/M_c,Rd = {u_comb:.3} (GZT {combo}, führend {action_id})."),
        ),
        remedies_c,
    ));

    // Flexural buckling χ §6.3.1
    let lb_y = part_1_1::lambda_bar(l_cr_y, i_y, a_eff.max(a_gross), alloy.f_o_pa);
    let lb_z = part_1_1::lambda_bar(l_cr_z, i_z, a_eff.max(a_gross), alloy.f_o_pa);
    let chi_y = part_1_1::chi_from_lambda(lb_y, alpha, lambda_0);
    let chi_z = part_1_1::chi_from_lambda(lb_z, alpha, lambda_0);
    let chi = chi_y.min(chi_z);
    let n_b_rd_y = chi_y * a_eff * alloy.f_o_pa / params.gamma_m1;
    let n_b_rd_z = chi_z * a_eff * alloy.f_o_pa / params.gamma_m1;
    let n_b_rd = chi * a_eff * alloy.f_o_pa / params.gamma_m1;
    let mut remedies_b = Vec::new();
    if n_ed.abs() > n_b_rd && n_b_rd > 0.0 {
        // invert for L_cr: need chi' such that chi'*A*f/γ = |N|
        let chi_req = (n_ed.abs() * params.gamma_m1 / (a_eff * alloy.f_o_pa)).min(1.0);
        // binary search L_cr
        let mut lo = 0.1; let mut hi = member.buckling_length_y.max(member.buckling_length_z).max(0.5);
        for _ in 0..40 {
            let mid = 0.5 * (lo + hi);
            let lb = part_1_1::lambda_bar(mid, i_y.min(i_z), a_eff.max(a_gross), alloy.f_o_pa);
            let ch = part_1_1::chi_from_lambda(lb, alpha, lambda_0);
            if ch >= chi_req { lo = mid; } else { hi = mid; }
        }
        remedies_b.push(Remedy::at_most(
            SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthY", member.id), member_label(&member.id)),
            q_length(member.buckling_length_y),
            q_length(lo),
            loc(
                &format!("Reduce buckling length L_cr,y from {:.2} m to at most {:.2} m (χ computed = {chi:.3}).", member.buckling_length_y, lo),
                &format!("Biegedrillknicklänge L_cr,y von {:.2} m auf höchstens {:.2} m verkürzen (χ = {chi:.3}).", member.buckling_length_y, lo),
            ),
        ));
        remedies_b.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-i160".into(), "sec-i200".into()],
            loc("Select a stockier section to raise χ·A.", "Stockigeren Querschnitt wählen, um χ·A zu erhöhen."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.3.1.fb.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.1", "6.3.1"),
        SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthY", member.id), member_label(&member.id)),
        loc("Flexural buckling N_b,Rd (χ computed)", "Biegeknicken N_b,Rd (χ berechnet)"),
        q_force(n_ed.abs()),
        q_force(n_b_rd_y),
        annex,
        loc(
            &format!("λ̄_y={lb_y:.6}, χ_y={chi_y:.6}, N_b,Rd,y={:.1} kN (ULS {combo}, lead {action_id}).", n_b_rd_y/1e3),
            &format!("λ̄_y={lb_y:.6}, χ_y={chi_y:.6}, N_b,Rd,y={:.1} kN (GZT {combo}, führend {action_id}).", n_b_rd_y/1e3),
        ),
        remedies_b,
    ));
    let mut remedies_fb_z = Vec::new();
    if n_ed.abs() > n_b_rd_z && n_b_rd_z > 0.0 {
        let chi_req_z = (n_ed.abs() * params.gamma_m1 / (a_eff * alloy.f_o_pa)).min(1.0);
        let mut lo_z = 0.1;
        let mut hi_z = member.buckling_length_z.max(0.5);
        for _ in 0..40 {
            let mid = 0.5 * (lo_z + hi_z);
            let lb = part_1_1::lambda_bar(mid, i_z, a_eff.max(a_gross), alloy.f_o_pa);
            let ch = part_1_1::chi_from_lambda(lb, alpha, lambda_0);
            if ch >= chi_req_z { lo_z = mid; } else { hi_z = mid; }
        }
        remedies_fb_z.push(Remedy::at_most(
            SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthZ", member.id), member_label(&member.id)),
            q_length(member.buckling_length_z),
            q_length(lo_z.max(0.05)),
            loc(
                &format!("Reduce buckling length L_cr,z to at most {:.2} m.", lo_z.max(0.05)),
                &format!("Knicklänge L_cr,z auf höchstens {:.2} m verkürzen.", lo_z.max(0.05)),
            ),
        ));
        remedies_fb_z.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "nK", |a| a.n_k, n_ed, n_b_rd_z, q_force,
            member_label(&member.id),
            "Reduce |N_k| so flexural buckling about z complies.",
            "|N_k| senken, damit Biegeknicken um z erfüllt ist.",
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.3.1.fb.z.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.1", "6.3.1"),
        SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthZ", member.id), member_label(&member.id)),
        loc("Flexural buckling N_b,Rd,z", "Biegeknicken N_b,Rd,z"),
        q_force(n_ed.abs()),
        q_force(n_b_rd_z),
        annex,
        loc(
            &format!("λ̄_z={lb_z:.6}, χ_z={chi_z:.6}, N_b,Rd,z={:.1} kN (ULS {combo}, lead {action_id}).", n_b_rd_z/1e3),
            &format!("λ̄_z={lb_z:.6}, χ_z={chi_z:.6}, N_b,Rd,z={:.1} kN (GZT {combo}, führend {action_id}).", n_b_rd_z/1e3),
        ),
        remedies_fb_z,
    ));
    // Slenderness always tracks L_cr even when χ = 1 (plateau).
    let lb_t_slend = part_1_1::lambda_bar(l_cr_t, i_y.min(i_z), a_eff.max(a_gross), alloy.f_o_pa);
    let mut remedies_lam_y = Vec::new();
    if lb_y > 3.0 {
        let l_req = (member.buckling_length_y * 3.0 / lb_y * 0.99).max(0.05);
        remedies_lam_y.push(Remedy::at_most(
            SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthY", member.id), member_label(&member.id)),
            q_length(member.buckling_length_y),
            q_length(l_req),
            loc(
                &format!("Reduce L_cr,y to at most {:.2} m so λ̄_y ≤ 3.", l_req),
                &format!("L_cr,y auf höchstens {:.2} m verkürzen, damit λ̄_y ≤ 3.", l_req),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.3.1.lambda.y.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.1", "6.3.1"),
        SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthY", member.id), member_label(&member.id)),
        loc("Non-dimensional slenderness λ̄_y", "Bezogene Schlankheit λ̄_y"),
        q_dim(lb_y),
        q_dim(3.0),
        annex,
        loc(
            &format!("λ̄_y={lb_y:.6} from L_cr,y (ULS {combo}, lead {action_id})."),
            &format!("λ̄_y={lb_y:.6} aus L_cr,y (GZT {combo}, führend {action_id})."),
        ),
        remedies_lam_y,
    ));
    let mut remedies_lam_t = Vec::new();
    if lb_t_slend > 3.0 {
        let l_req = (member.buckling_length_t * 3.0 / lb_t_slend * 0.99).max(0.05);
        remedies_lam_t.push(Remedy::at_most(
            SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthT", member.id), member_label(&member.id)),
            q_length(member.buckling_length_t),
            q_length(l_req),
            loc(
                &format!("Reduce L_cr,T to at most {:.2} m so λ̄_T ≤ 3.", l_req),
                &format!("L_cr,T auf höchstens {:.2} m verkürzen, damit λ̄_T ≤ 3.", l_req),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.3.1.lambda.t.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.1", "6.3.1.4"),
        SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthT", member.id), member_label(&member.id)),
        loc("Non-dimensional slenderness λ̄_T", "Bezogene Schlankheit λ̄_T"),
        q_dim(lb_t_slend),
        q_dim(3.0),
        annex,
        loc(
            &format!("λ̄_T from L_cr,T={l_cr_t:.4} m (ULS {combo}, lead {action_id})."),
            &format!("λ̄_T aus L_cr,T={l_cr_t:.4} m (GZT {combo}, führend {action_id})."),
        ),
        remedies_lam_t,
    ));
    out.push(utilization_check(
        format!("en1999.6.3.1.lcr.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.1", "6.3.1"),
        SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthY", member.id), member_label(&member.id)),
        loc("Buckling lengths L_cr,y/z/t", "Knicklängen L_cr,y/z/t"),
        q_length(l_cr_y + l_cr_z + l_cr_t),
        q_length(((l_cr_y + l_cr_z + l_cr_t) * 2.0).max(1e-3)),
        annex,
        loc(
            &format!("ΣL_cr={:.3} m (y={:.3}, z={:.3}, t={:.3}); L={:.3} m; support k={k_sup:.2} (ULS {combo}, lead {action_id}).", l_cr_y + l_cr_z + l_cr_t, l_cr_y, l_cr_z, l_cr_t, member.length),
            &format!("ΣL_cr={:.3} m (y={:.3}, z={:.3}, t={:.3}); L={:.3} m; Auflager k={k_sup:.2} (GZT {combo}, führend {action_id}).", l_cr_y + l_cr_z + l_cr_t, l_cr_y, l_cr_z, l_cr_t, member.length),
        ),
        Vec::new(),
    ));

    // Torsional / flexural-torsional
    let lb_t = part_1_1::torsional_lambda_bar(a_eff.max(a_gross), i_t, i_y, i_z, l_cr_t, alloy.f_o_pa);
    let chi_t = part_1_1::chi_from_lambda(lb_t, alpha, lambda_0);
    let n_t_rd = chi_t * a_eff * alloy.f_o_pa / params.gamma_m1;
    let mut remedies_t = Vec::new();
    if n_ed.abs() > n_t_rd && n_t_rd > 0.0 {
        remedies_t.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-box120".into(), "sec-tube114".into()],
            loc("Select a closed section to raise I_t.", "Geschlossenen Querschnitt wählen, um I_t zu erhöhen."),
        ));
        remedies_t.push(Remedy::at_most(
            SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthT", member.id), member_label(&member.id)),
            q_length(l_cr_t),
            q_length(l_cr_t * 0.5),
            loc("Halve torsional buckling length L_cr,T.", "Torsionsknicklänge L_cr,T halbieren."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.3.1.tb.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.1", "6.3.1.4"),
        SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthT", member.id), member_label(&member.id)),
        loc("Torsional / flexural-torsional buckling", "Torsions- / Biegedrillknicken"),
        q_force(n_ed.abs()),
        q_force(n_t_rd),
        annex,
        loc(
            &format!("L_cr,T={l_cr_t:.4} m, λ̄_T={lb_t:.6}, χ_T={chi_t:.6}, N_t,Rd={:.1} kN (ULS {combo}, lead {action_id}); {sup_dig}", n_t_rd/1e3),
            &format!("L_cr,T={l_cr_t:.4} m, λ̄_T={lb_t:.6}, χ_T={chi_t:.6}, N_t,Rd={:.1} kN (GZT {combo}, führend {action_id}); {sup_dig}", n_t_rd/1e3),
        ),
        remedies_t,
    ));

    // LTB §6.3.2
    let m_cr = if member.restrained_ltb {
        f64::INFINITY
    } else {
        part_1_1::m_cr_ltb(member.c1, na_de::E_PA, i_z, i_w, i_t, l_lt)
    };
    let lambda_lt = if m_cr.is_finite() && m_cr > 0.0 { (wel_eff * alloy.f_o_pa / m_cr).sqrt() } else { 0.0 };
    let chi_lt = part_1_1::chi_from_lambda(lambda_lt, alpha, lambda_0);
    let m_b_rd = chi_lt * m_rd;
    let mut remedies_lt = Vec::new();
    if m_y.abs() > m_b_rd && m_b_rd > 0.0 {
        remedies_lt.push(Remedy::at_most(
            SubjectRef::new(&member.id, format!("members[id={}].ltbLength", member.id), member_label(&member.id)),
            q_length(l_lt),
            q_length(l_lt * 0.5),
            loc(
                &format!("Reduce LTB length from {:.2} m (M_cr={:.1} kNm, χ_LT={chi_lt:.3}).", l_lt, m_cr/1e3),
                &format!("Biegedrillknicklänge von {:.2} m verkürzen (M_cr={:.1} kNm, χ_LT={chi_lt:.3}).", l_lt, m_cr/1e3),
            ),
        ));
        remedies_lt.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-i160".into(), "sec-i200".into()],
            loc("Select a section with larger I_z / I_w.", "Querschnitt mit größerem I_z / I_w wählen."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.3.2.ltb.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.2", "6.3.2"),
        SubjectRef::new(&member.id, format!("members[id={}].ltbLength", member.id), member_label(&member.id)),
        loc("Lateral-torsional buckling M_b,Rd", "Biegedrillknicken M_b,Rd"),
        q_moment(m_y.abs()),
        q_moment(m_b_rd),
        annex,
        loc(
            &format!("M_cr={:.1} kNm, λ̄_LT={lambda_lt:.6}, χ_LT={chi_lt:.6}, M_b,Rd={:.2} kNm (ULS {combo}, lead {action_id}); {sup_dig}; {act_dig}", m_cr/1e3, m_b_rd/1e3),
            &format!("M_cr={:.1} kNm, λ̄_LT={lambda_lt:.6}, χ_LT={chi_lt:.6}, M_b,Rd={:.2} kNm (GZT {combo}, führend {action_id}); {sup_dig}; {act_dig}", m_cr/1e3, m_b_rd/1e3),
        ),
        remedies_lt,
    ));

    // Interaction 6.3.3
    let u_i = if n_b_rd > 0.0 && m_b_rd > 0.0 {
        n_ed.abs() / n_b_rd + m_y.abs() / m_b_rd
    } else { 0.0 };
    let mut remedies_i = Vec::new();
    if u_i > 1.0 {
        remedies_i.push(Remedy::one_of(
            SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
            vec!["sec-i160".into(), "sec-i200".into()],
            loc("Select a larger section for member buckling interaction.", "Größeren Querschnitt für Knickinteraktion wählen."),
        ));
        remedies_i.push(Remedy::at_most(
            SubjectRef::new(&member.id, format!("members[id={}].bucklingLengthY", member.id), member_label(&member.id)),
            q_length(member.buckling_length_y),
            q_length(member.buckling_length_y * 0.6),
            loc("Shorten buckling / LTB lengths (add restraints).", "Knick-/Biegedrillknicklängen verkürzen (Halterungen)."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.6.3.3.int.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§6.3.3", "6.3.3"),
        SubjectRef::new(&member.id, path_n, member_label(&member.id)),
        loc("Member buckling interaction", "Interaktion Stabknicken"),
        q_dim(u_i),
        q_dim(1.0),
        annex,
        loc(
            &format!("N_Ed/N_b,Rd + M_Ed/M_b,Rd = {u_i:.3} (ULS {combo}, lead {action_id})."),
            &format!("N_Ed/N_b,Rd + M_Ed/M_b,Rd = {u_i:.3} (GZT {combo}, führend {action_id})."),
        ),
        remedies_i,
    ));

    // SLS deflection §7.2 (quasi-permanent) + elastic stress (characteristic)
    let sls_qp = part_en1990::sls_member_effects(member, annex, "quasiPermanent");
    let sls_char = part_en1990::sls_member_effects(member, annex, "characteristic");
    let (_, iy, _, _, _, _, _) = part_1_1::section_geometry(section);
    let e_mod = na_de::E_PA;
    let w_qp = if e_mod * iy > 0.0 && member.length > 0.0 {
        // simply-supported UDL proxy from |M| ≈ q L²/8 → q = 8M/L²; w = 5 q L⁴ / (384 EI)
        let m_qp = sls_qp.m_y_ed.abs();
        let q = 8.0 * m_qp / member.length.powi(2);
        5.0 * q * member.length.powi(4) / (384.0 * e_mod * iy)
    } else { 0.0 };
    let w_lim = member.length / 200.0; // EN 1999-1-1 §7.2 / DE NA vertical deflection
    let mut rem_w = Vec::new();
    if w_qp > w_lim {
        if member.length <= 0.0 {
            rem_w.push(Remedy::at_least(
                SubjectRef::new(&member.id, format!("members[id={}].length", member.id), member_label(&member.id)),
                q_length(member.length),
                q_length(1.0),
                loc("Set a positive member length for SLS deflection.", "Positive Bauteillänge für GZG-Durchbiegung setzen."),
            ));
        } else if w_lim > 0.0 {
            rem_w.extend(scale_action_leaf_remedies(
                "members", &member.id, &member.actions, "mYK", |a| a.m_y_k, sls_qp.m_y_ed, sls_qp.m_y_ed.abs() * w_lim / w_qp.max(1e-12), q_moment,
                member_label(&member.id),
                "Reduce M_y,k so quasi-permanent deflection ≤ L/200.",
                "M_y,k senken, damit quasi-ständige Durchbiegung ≤ L/200.",
            ));
            rem_w.extend(scale_action_leaf_remedies(
                "members", &member.id, &member.actions, "gKLine", |a| a.g_k_line, w_qp, w_lim, q_force,
                member_label(&member.id),
                "Reduce g_k so quasi-permanent deflection ≤ L/200.",
                "g_k senken, damit quasi-ständige Durchbiegung ≤ L/200.",
            ));
            rem_w.extend(scale_action_leaf_remedies(
                "members", &member.id, &member.actions, "qKLine", |a| a.q_k_line, w_qp, w_lim, q_force,
                member_label(&member.id),
                "Reduce q_k so quasi-permanent deflection ≤ L/200.",
                "q_k senken, damit quasi-ständige Durchbiegung ≤ L/200.",
            ));
        }
    }
    out.push(utilization_check(
        format!("en1999.7.2.defl.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§7.2", "7.2"),
        SubjectRef::new(&member.id, format!("members[id={}].length", member.id), member_label(&member.id)),
        loc("SLS deflection (quasi-permanent)", "GZG Durchbiegung (quasi-ständig)"),
        q_length(w_qp),
        q_length(w_lim.max(1e-9)),
        annex,
        loc(
            &format!("w={:.1} mm ≤ L/200={:.1} mm (SLS {comb}, lead {aid}); {act_dig}; {sup_dig}", w_qp*1e3, w_lim*1e3, comb=sls_qp.combination, aid=sls_qp.action_id),
            &format!("w={:.1} mm ≤ L/200={:.1} mm (GZG {comb}, führend {aid}); {act_dig}; {sup_dig}", w_qp*1e3, w_lim*1e3, comb=sls_qp.combination, aid=sls_qp.action_id),
        ),
        rem_w,
    ));
    let sigma_sls = if wel_eff > 0.0 { sls_char.m_y_ed.abs() / wel_eff } else { 0.0 };
    let sigma_lim = 0.8 * alloy.f_o_pa; // elastic SLS stress limit
    let mut rem_s = Vec::new();
    if sigma_sls > sigma_lim {
        let m_lim = if wel_eff > 0.0 { sigma_lim * wel_eff } else { 0.0 };
        rem_s.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "mYK", |a| a.m_y_k, sls_char.m_y_ed, m_lim, q_moment,
            member_label(&member.id),
            "Reduce M_y,k so characteristic SLS σ ≤ 0.8 f_o.",
            "M_y,k senken, damit charakteristische GZG-Spannung σ ≤ 0,8 f_o.",
        ));
        rem_s.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "gKLine", |a| a.g_k_line, sigma_sls, sigma_lim, q_force,
            member_label(&member.id),
            "Reduce g_k so characteristic SLS σ ≤ 0.8 f_o.",
            "g_k senken, damit charakteristische GZG-Spannung σ ≤ 0,8 f_o.",
        ));
        rem_s.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "qKLine", |a| a.q_k_line, sigma_sls, sigma_lim, q_force,
            member_label(&member.id),
            "Reduce q_k so characteristic SLS σ ≤ 0.8 f_o.",
            "q_k senken, damit charakteristische GZG-Spannung σ ≤ 0,8 f_o.",
        ));
    }
    out.push(utilization_check(
        format!("en1999.7.2.stress.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§7.2", "7.2"),
        SubjectRef::new(&member.id, format!("members[id={}].actions[id={}].mYK", member.id, sls_char.action_id), member_label(&member.id)),
        loc("SLS elastic stress (characteristic)", "GZG elastische Spannung (charakteristisch)"),
        q_stress(sigma_sls),
        q_stress(sigma_lim.max(1e-9)),
        annex,
        loc(
            &format!("σ={:.0} MPa ≤ 0.8 f_o={:.0} MPa (SLS {comb}, lead {aid}); {act_dig}; {sup_dig}; {el_dig}", sigma_sls/1e6, sigma_lim/1e6, comb=sls_char.combination, aid=sls_char.action_id),
            &format!("σ={:.0} MPa ≤ 0,8 f_o={:.0} MPa (GZG {comb}, führend {aid}); {act_dig}; {sup_dig}; {el_dig}", sigma_sls/1e6, sigma_lim/1e6, comb=sls_char.combination, aid=sls_char.action_id),
        ),
        rem_s,
    ));

    let sls_freq = part_en1990::sls_member_effects(member, annex, "frequent");
    let sigma_freq = if wel_eff > 0.0 { sls_freq.m_y_ed.abs() / wel_eff } else { 0.0 };
    let mut rem_f = Vec::new();
    if sigma_freq > sigma_lim {
        let m_lim = if wel_eff > 0.0 { sigma_lim * wel_eff } else { 0.0 };
        rem_f.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "mYK", |a| a.m_y_k, sls_freq.m_y_ed, m_lim, q_moment,
            member_label(&member.id),
            "Reduce M_y,k so frequent SLS σ ≤ 0.8 f_o.",
            "M_y,k senken, damit häufige GZG-Spannung σ ≤ 0,8 f_o.",
        ));
        rem_f.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "gKLine", |a| a.g_k_line, sigma_freq, sigma_lim, q_force,
            member_label(&member.id),
            "Reduce g_k so frequent SLS σ ≤ 0.8 f_o.",
            "g_k senken, damit häufige GZG-Spannung σ ≤ 0,8 f_o.",
        ));
        rem_f.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "qKLine", |a| a.q_k_line, sigma_freq, sigma_lim, q_force,
            member_label(&member.id),
            "Reduce q_k so frequent SLS σ ≤ 0.8 f_o.",
            "q_k senken, damit häufige GZG-Spannung σ ≤ 0,8 f_o.",
        ));
    }
    out.push(utilization_check(
        format!("en1999.7.2.sls-freq.{}", member.id),
        part,
        ClauseId::new("EN 1999-1-1", "§7.2", "7.2"),
        SubjectRef::new(&member.id, format!("members[id={}].actions[id={}].mYK", member.id, sls_freq.action_id), member_label(&member.id)),
        loc("SLS elastic stress (frequent ψ₁)", "GZG elastische Spannung (häufig ψ₁)"),
        q_stress(sigma_freq),
        q_stress(sigma_lim.max(1e-9)),
        annex,
        loc(
            &format!("σ={:.0} MPa ≤ 0.8 f_o={:.0} MPa (SLS {comb}, lead {aid}); {act_dig}; {sup_dig}", sigma_freq/1e6, sigma_lim/1e6, comb=sls_freq.combination, aid=sls_freq.action_id),
            &format!("σ={:.0} MPa ≤ 0,8 f_o={:.0} MPa (GZG {comb}, führend {aid}); {act_dig}; {sup_dig}", sigma_freq/1e6, sigma_lim/1e6, comb=sls_freq.combination, aid=sls_freq.action_id),
        ),
        rem_f,
    ));

    out
}

pub fn check_connection(conn: &AluminiumConnection, material: &AluminiumMaterial, member: Option<&crate::snapshot::AluminiumMember>, member_ids: &[String], annex: AnnexChoice) -> Vec<CheckResult> {
    let params = na_de::AnnexParams::for_choice(annex);
    let Some(alloy) = part_1_1::resolve_alloy(&material.designation) else {
        return vec![CheckResult::assess(
            format!("en1999.3.2.alloy.{}", conn.id),
            "DIN EN 1999-1-1",
            ClauseId::new("EN 1999-1-1", "§3.2", "3.2"),
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            loc("Alloy designation", "Legierungsbezeichnung"),
        )
        .status(crate::document::CheckStatus::Fail)
        .explanation(loc(
            &format!("Unknown alloy designation '{}'.", material.designation),
            &format!("Unbekannte Legierungsbezeichnung '{}'.", material.designation),
        ))
        .annex(annex)
        .remedy(Remedy::one_of(
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            part_1_1::CATALOGUE_ALLOYS.iter().map(|s| (*s).to_string()).collect(),
            loc("Pick a catalogue alloy from EN 1999-1-1 Table 3.2.", "Kataloglegierung nach EN 1999-1-1 Tabelle 3.2 wählen."),
        ))
        .build()];
    };
    let part = "DIN EN 1999-1-1";
    let mut out = Vec::new();
    let kind = conn.kind.to_ascii_lowercase();

    let gov = if conn.actions.is_empty() {
        member.map(|m| part_en1990::governing_member_effects(m, annex)).unwrap_or(part_en1990::GoverningEffects {
            action_id: "G".into(), combination: "uls-g", n_ed: 0.0, v_y_ed: 0.0, v_z_ed: 0.0, m_y_ed: 0.0, m_z_ed: 0.0,
        })
    } else {
        part_en1990::governing_connection_effects(conn, annex)
    };
    let combo = gov.combination;
    let action_id = gov.action_id.as_str();
    let lever = 0.50;
    let n_ed = gov.n_ed.abs() + 0.25 * (gov.m_y_ed.abs() + gov.m_z_ed.abs()) / lever;
    let v_ed = gov.v_y_ed.abs() + gov.v_z_ed.abs() + (gov.m_y_ed.abs() + gov.m_z_ed.abs()) / lever;
    let m_ed = gov.m_y_ed.abs() + gov.m_z_ed.abs();
    let conn_dig = actions_digest(&conn.actions);
    // memberId must resolve for connection checks that use governing effects
    if member.is_none() {
        return vec![CheckResult::assess(
            format!("en1999.8.ref.{}", conn.id),
            "DIN EN 1999-1-1",
            ClauseId::new("EN 1999-1-1", "§8", "8"),
            SubjectRef::new(&conn.id, format!("connections[id={}].memberId", conn.id), loc("Connection", "Anschluss")),
            loc("Connection member reference", "Anschluss-Bauteilverweis"),
        )
        .status(crate::document::CheckStatus::Fail)
        .explanation(loc(
            &format!("Connection '{}' references missing member '{}'.", conn.id, conn.member_id),
            &format!("Anschluss '{}' verweist auf fehlendes Bauteil '{}'.", conn.id, conn.member_id),
        ))
        .annex(annex)
        .remedy(Remedy::one_of(
            SubjectRef::new(&conn.id, format!("connections[id={}].memberId", conn.id), conn_label(&conn.id)),
            member_ids.to_vec(),
            loc("Point connection.memberId at an existing member.", "connections.memberId auf ein vorhandenes Bauteil setzen."),
        ))
        .build()];
    }

    if kind == "bolted" || kind == "combined" {
        if part_1_1::bolt_fu_pa(&conn.bolts.material) <= 0.0 {
            out.push(CheckResult::assess(
                format!("en1999.8.5.boltgrade.{}", conn.id),
                part,
                ClauseId::new("EN 1999-1-1", "§8.5", "8.5"),
                SubjectRef::new(&conn.id, format!("connections[id={}].bolts.material", conn.id), conn_label(&conn.id)),
                loc("Bolt grade", "Schraubenfestigkeit"),
            )
            .status(crate::document::CheckStatus::Fail)
            .explanation(loc(
                &format!("Unknown bolt grade '{}'.", conn.bolts.material),
                &format!("Unbekannte Schraubenfestigkeit '{}'.", conn.bolts.material),
            ))
            .annex(annex)
            .remedy(Remedy::one_of(
                SubjectRef::new(&conn.id, format!("connections[id={}].bolts.material", conn.id), conn_label(&conn.id)),
                vec!["4.6".into(), "5.6".into(), "8.8".into(), "10.9".into()],
                loc("Select a bolt grade from EN 1999-1-1 Table 3.4.", "Schraubenfestigkeit nach EN 1999-1-1 Tabelle 3.4 wählen."),
            ))
            .build());
        }
        let f_v = part_1_1::bolt_shear_resistance(&conn.bolts, params.gamma_m2);
        let f_b = part_1_1::bolt_bearing_resistance(&conn.bolts, alloy.f_u_pa, params.gamma_m2);
        let pitch_ratio = conn.bolts.pitch / conn.bolts.diameter.max(1e-6);
        let pitch_factor = (0.85 + 0.05 * pitch_ratio).clamp(0.80, 1.25);
        let f_rd = (if f_v > 0.0 && f_b > 0.0 { (f_v * f_b) / (f_v + f_b) } else { f_v.min(f_b) }) * pitch_factor;
        let mut remedies = Vec::new();
        let force_bolt = v_ed + n_ed.abs();
        if force_bolt > f_rd && f_rd > 0.0 {
            let n_now = (conn.bolts.rows * conn.bolts.bolts_per_row) as f64;
            let n_req = (n_now * force_bolt / f_rd * 1.05).ceil().max(n_now + 1.0) as u32;
            let per_row = (n_req / conn.bolts.rows.max(1)).max(conn.bolts.bolts_per_row + 1);
            remedies.push(Remedy::at_least(
                SubjectRef::new(&conn.id, format!("connections[id={}].bolts.boltsPerRow", conn.id), conn_label(&conn.id)),
                q_dim(conn.bolts.bolts_per_row as f64),
                q_dim(per_row as f64),
                loc(
                    &format!("Increase bolt count (rows×bolts) so F_Rd ≥ {:.1} kN.", force_bolt/1e3),
                    &format!("Schraubenzahl erhöhen, sodass F_Rd ≥ {:.1} kN.", force_bolt/1e3),
                ),
            ));
            let rows_req = (n_req / conn.bolts.bolts_per_row.max(1)).max(conn.bolts.rows + 1);
            remedies.push(Remedy::at_least(
                SubjectRef::new(&conn.id, format!("connections[id={}].bolts.rows", conn.id), conn_label(&conn.id)),
                q_dim(conn.bolts.rows as f64),
                q_dim(rows_req as f64),
                loc(
                    &format!("Increase bolt rows so F_Rd ≥ {:.1} kN.", force_bolt/1e3),
                    &format!("Schraubenreihen erhöhen, sodass F_Rd ≥ {:.1} kN.", force_bolt/1e3),
                ),
            ));
            remedies.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "vZK", |a| a.v_z_k, force_bolt, f_rd, q_force,
                conn_label(&conn.id),
                "Reduce V_z,k so bolted resistance governs.",
                "V_z,k senken, damit Schraubentragfähigkeit maßgebend ist.",
            ));
            remedies.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "nK", |a| a.n_k, force_bolt, f_rd, q_force,
                conn_label(&conn.id),
                "Reduce N_k so bolted resistance governs.",
                "N_k senken, damit Schraubentragfähigkeit maßgebend ist.",
            ));
        }
        if conn.bolts.edge_distance < 1.2 * conn.bolts.diameter {
            remedies.push(Remedy::at_least(
                SubjectRef::new(&conn.id, format!("connections[id={}].bolts.edgeDistance", conn.id), conn_label(&conn.id)),
                q_length(conn.bolts.edge_distance),
                q_length(1.2 * conn.bolts.diameter),
                loc("Increase edge distance e1 to ≥ 1.2 d.", "Randabstand e1 auf ≥ 1.2 d erhöhen."),
            ));
        }
        let p_min = 2.2 * conn.bolts.diameter;
        out.push(utilization_check(
            format!("en1999.8.5.pitch.{}", conn.id),
            part,
            ClauseId::new("EN 1999-1-1", "§8.5", "8.5.1"),
            SubjectRef::new(&conn.id, format!("connections[id={}].bolts.pitch", conn.id), conn_label(&conn.id)),
            loc("Minimum bolt pitch p1 ≥ 2.2 d", "Mindestlochabstand p1 ≥ 2.2 d"),
            q_length(p_min),
            q_length(conn.bolts.pitch.max(1e-9)),
            annex,
            loc(
                &format!("p1={:.4} m, 2.2d={:.4} m (bolt spacing).", conn.bolts.pitch, p_min),
                &format!("p1={:.4} m, 2.2d={:.4} m (Schraubenabstand).", conn.bolts.pitch, p_min),
            ),
            if conn.bolts.pitch + 1e-12 < p_min {
                vec![Remedy::at_least(
                    SubjectRef::new(&conn.id, format!("connections[id={}].bolts.pitch", conn.id), conn_label(&conn.id)),
                    q_length(conn.bolts.pitch),
                    q_length(p_min),
                    loc("Increase pitch to ≥ 2.2 d.", "Lochabstand auf ≥ 2.2 d erhöhen."),
                )]
            } else { Vec::new() },
        ));
        out.push(utilization_check(
            format!("en1999.8.5.bolt.{}", conn.id),
            part,
            ClauseId::new("EN 1999-1-1", "§8.5", "8.5"),
            SubjectRef::new(&conn.id, format!("connections[id={}].bolts.diameter", conn.id), conn_label(&conn.id)),
            loc("Bolted connection resistance", "Schraubenanschluss Tragfähigkeit"),
            q_force(v_ed + n_ed.abs()),
            q_force(f_rd),
            annex,
            loc(
                &format!("V_Ed={:.1} kN, N_Ed={:.1} kN, M_Ed={:.2} kNm, F_v,Rd={:.1} kN, F_b,Rd={:.1} kN, d={d:.4} m, e1={e1:.4} m, p1={p1:.4} m, e2={e2:.4} m (ULS {combo}, lead {action_id}, bolt {mat}); {conn_dig}", v_ed/1e3, n_ed.abs()/1e3, m_ed/1e3, f_v/1e3, f_b/1e3, d=conn.bolts.diameter, e1=conn.bolts.edge_distance, p1=conn.bolts.pitch, e2=conn.bolts.gauge, mat=conn.bolts.material),
                &format!("V_Ed={:.1} kN, N_Ed={:.1} kN, M_Ed={:.2} kNm, F_v,Rd={:.1} kN, F_b,Rd={:.1} kN, d={d:.4} m, e1={e1:.4} m, p1={p1:.4} m, e2={e2:.4} m (GZT {combo}, führend {action_id}, Schraube {mat}); {conn_dig}", v_ed/1e3, n_ed.abs()/1e3, m_ed/1e3, f_v/1e3, f_b/1e3, d=conn.bolts.diameter, e1=conn.bolts.edge_distance, p1=conn.bolts.pitch, e2=conn.bolts.gauge, mat=conn.bolts.material),
            ),
            remedies,
        ));
    }

    if kind == "welded" || kind == "combined" {
        let f_w = part_1_1::weld_resistance(&conn.welds, alloy.f_u_pa, params.gamma_m2) * (alloy.rho_u_haz.min(alloy.rho_o_haz) / (1.0 + part_1_1::haz_extent_m(&conn.welds, conn.bolts.plate_thickness).max(conn.welds.throat) * 10.0)).clamp(0.2, 1.0);
        let mut remedies = Vec::new();
        let force_weld = v_ed + n_ed.abs();
        if force_weld > f_w && f_w > 0.0 {
            let rho_haz = alloy.rho_u_haz.min(alloy.rho_o_haz);
            let mut t_req = conn.welds.throat;
            for _ in 0..48 {
                let mut trial = conn.welds.clone();
                trial.throat = t_req;
                let haz = part_1_1::haz_extent_m(&trial, conn.bolts.plate_thickness).max(trial.throat);
                let fac = (rho_haz / (1.0 + haz * 10.0)).clamp(0.2, 1.0);
                let f_w_base = part_1_1::weld_resistance(&trial, alloy.f_u_pa, params.gamma_m2);
                let need = force_weld / fac.max(1e-9);
                let a_need = need * trial.beta_w.max(0.01) * params.gamma_m2 / part_1_1::filler_fu_pa(&trial.filler_alloy, alloy.f_u_pa).max(1e-9);
                t_req = (a_need / trial.length.max(1e-6)).max(t_req);
                if f_w_base * fac >= force_weld * 0.999 { break; }
            }
            remedies.push(Remedy::at_least(
                SubjectRef::new(&conn.id, format!("connections[id={}].welds.throat", conn.id), conn_label(&conn.id)),
                q_length(conn.welds.throat),
                q_length(t_req),
                loc(
                    &format!("Increase weld throat from {:.1} mm to at least {:.1} mm.", conn.welds.throat*1e3, t_req*1e3),
                    &format!("Kehlnahtdicke von {:.1} mm auf mindestens {:.1} mm erhöhen.", conn.welds.throat*1e3, t_req*1e3),
                ),
            ));
            let haz0 = part_1_1::haz_extent_m(&conn.welds, conn.bolts.plate_thickness).max(conn.welds.throat);
            let fac0 = (rho_haz / (1.0 + haz0 * 10.0)).clamp(0.2, 1.0);
            let a_need = force_weld / fac0.max(1e-9) * conn.welds.beta_w.max(0.01) * params.gamma_m2
                / part_1_1::filler_fu_pa(&conn.welds.filler_alloy, alloy.f_u_pa).max(1e-9);
            let l_req = a_need / conn.welds.throat.max(1e-6);
            remedies.push(Remedy::at_least(
                SubjectRef::new(&conn.id, format!("connections[id={}].welds.length", conn.id), conn_label(&conn.id)),
                q_length(conn.welds.length),
                q_length(l_req),
                loc(
                    &format!("Increase weld length from {:.0} mm to at least {:.0} mm (or relocate weld).", conn.welds.length*1e3, l_req*1e3),
                    &format!("Nahtlänge von {:.0} mm auf mindestens {:.0} mm erhöhen (oder Naht verlegen).", conn.welds.length*1e3, l_req*1e3),
                ),
            ));
            remedies.push(Remedy::at_most(
                SubjectRef::new(&conn.id, format!("connections[id={}].welds.hazExtent", conn.id), conn_label(&conn.id)),
                q_length(conn.welds.haz_extent),
                q_length(0.0),
                loc("Reduce stored HAZ extent so weld resistance recovers.", "Gespeicherte WEZ-Ausdehnung senken, damit Nahttragfähigkeit steigt."),
            ));
            remedies.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "vZK", |a| a.v_z_k, force_weld, f_w, q_force,
                conn_label(&conn.id),
                "Reduce V_z,k so weld resistance governs.",
                "V_z,k senken, damit Schweißtragfähigkeit maßgebend ist.",
            ));
        }
        out.push(utilization_check(
            format!("en1999.8.6.weld.{}", conn.id),
            part,
            ClauseId::new("EN 1999-1-1", "§8.6", "8.6"),
            SubjectRef::new(&conn.id, format!("connections[id={}].welds.throat", conn.id), conn_label(&conn.id)),
            loc("Welded connection resistance", "Schweißanschluss Tragfähigkeit"),
            q_force(v_ed + n_ed.abs()),
            q_force(f_w),
            annex,
            loc(
                &format!("V_Ed={:.1} kN, N_Ed={:.1} kN, M_Ed={:.2} kNm, F_w,Rd={:.1} kN, a={:.1} mm, ℓ={:.0} mm, HAZ={:.0} mm, βw={bw:.3}, filler={filler} (ULS {combo}, lead {action_id}); {conn_dig}", v_ed/1e3, n_ed.abs()/1e3, m_ed/1e3, f_w/1e3, conn.welds.throat*1e3, conn.welds.length*1e3, conn.welds.haz_extent*1e3, bw=conn.welds.beta_w, filler=conn.welds.filler_alloy),
                &format!("V_Ed={:.1} kN, N_Ed={:.1} kN, M_Ed={:.2} kNm, F_w,Rd={:.1} kN, a={:.1} mm, ℓ={:.0} mm, WEZ={:.0} mm, βw={bw:.3}, Schweißzusatz={filler} (GZT {combo}, führend {action_id}); {conn_dig}", v_ed/1e3, n_ed.abs()/1e3, m_ed/1e3, f_w/1e3, conn.welds.throat*1e3, conn.welds.length*1e3, conn.welds.haz_extent*1e3, bw=conn.welds.beta_w, filler=conn.welds.filler_alloy),
            ),
            remedies,
        ));
    }

    if !conn.actions.is_empty() && (kind == "bolted" || kind == "welded" || kind == "combined") {
        let sls = part_en1990::sls_connection_effects(conn, annex, "frequent");
        let n_ed_s = sls.n_ed.abs() + 0.25 * (sls.m_y_ed.abs() + sls.m_z_ed.abs()) / lever;
        let v_ed_s = sls.v_y_ed.abs() + sls.v_z_ed.abs() + (sls.m_y_ed.abs() + sls.m_z_ed.abs()) / lever;
        let force_s = v_ed_s + n_ed_s;
        let mut f_lim = 0.0;
        if kind == "bolted" || kind == "combined" {
            let f_v = part_1_1::bolt_shear_resistance(&conn.bolts, params.gamma_m2);
            let f_b = part_1_1::bolt_bearing_resistance(&conn.bolts, alloy.f_u_pa, params.gamma_m2);
            let pitch_ratio = conn.bolts.pitch / conn.bolts.diameter.max(1e-6);
            let pitch_factor = (0.85 + 0.05 * pitch_ratio).clamp(0.80, 1.25);
            f_lim = (if f_v > 0.0 && f_b > 0.0 { (f_v * f_b) / (f_v + f_b) } else { f_v.min(f_b) }) * pitch_factor;
        }
        if kind == "welded" || kind == "combined" {
            let f_w = part_1_1::weld_resistance(&conn.welds, alloy.f_u_pa, params.gamma_m2)
                * (alloy.rho_u_haz.min(alloy.rho_o_haz)
                    / (1.0 + part_1_1::haz_extent_m(&conn.welds, conn.bolts.plate_thickness).max(conn.welds.throat) * 10.0))
                    .clamp(0.2, 1.0);
            f_lim = if f_lim > 0.0 { f_lim.min(f_w) } else { f_w };
        }
        let mut rem_s = Vec::new();
        if force_s > f_lim && f_lim > 0.0 {
            rem_s.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "vZK", |a| a.v_z_k, force_s, f_lim, q_force,
                conn_label(&conn.id),
                "Reduce V_z,k so frequent SLS connection force ≤ F_Rd.",
                "V_z,k senken, damit häufige GZG-Anschlusskraft ≤ F_Rd.",
            ));
            rem_s.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "nK", |a| a.n_k, force_s, f_lim, q_force,
                conn_label(&conn.id),
                "Reduce N_k so frequent SLS connection force ≤ F_Rd.",
                "N_k senken, damit häufige GZG-Anschlusskraft ≤ F_Rd.",
            ));
            rem_s.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "qKLine", |a| a.q_k_line, force_s, f_lim, q_force,
                conn_label(&conn.id),
                "Reduce q_k so frequent SLS connection force ≤ F_Rd.",
                "q_k senken, damit häufige GZG-Anschlusskraft ≤ F_Rd.",
            ));
            rem_s.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "gKLine", |a| a.g_k_line, force_s, f_lim, q_force,
                conn_label(&conn.id),
                "Reduce g_k so frequent SLS connection force ≤ F_Rd.",
                "g_k senken, damit häufige GZG-Anschlusskraft ≤ F_Rd.",
            ));
            rem_s.extend(scale_action_leaf_remedies(
                "connections", &conn.id, &conn.actions, "mYK", |a| a.m_y_k, force_s, f_lim, q_moment,
                conn_label(&conn.id),
                "Reduce M_y,k so frequent SLS connection force ≤ F_Rd.",
                "M_y,k senken, damit häufige GZG-Anschlusskraft ≤ F_Rd.",
            ));
        }
        out.push(utilization_check(
            format!("en1999.8.sls-freq.{}", conn.id),
            part,
            ClauseId::new("EN 1990", "§6.5.3", "6.5.3"),
            SubjectRef::new(
                &conn.id,
                format!("connections[id={}].actions[id={}].category", conn.id, sls.action_id),
                conn_label(&conn.id),
            ),
            loc("Connection force (frequent SLS ψ₁)", "Anschlusskraft (häufiges GZG ψ₁)"),
            q_force(force_s),
            q_force(f_lim.max(1e-9)),
            annex,
            loc(
                &format!(
                    "F_Ed,freq={:.1} kN ≤ F_Rd={:.1} kN (SLS {comb}, lead {aid}, ψ₁ via category); {conn_dig}",
                    force_s / 1e3,
                    f_lim / 1e3,
                    comb = sls.combination,
                    aid = sls.action_id
                ),
                &format!(
                    "F_Ed,freq={:.1} kN ≤ F_Rd={:.1} kN (GZG {comb}, führend {aid}, ψ₁ über Kategorie); {conn_dig}",
                    force_s / 1e3,
                    f_lim / 1e3,
                    comb = sls.combination,
                    aid = sls.action_id
                ),
            ),
            rem_s,
        ));
    }

    if out.is_empty() {
        out.push(
            CheckResult::assess(
                format!("en1999.8.na.{}", conn.id),
                part,
                ClauseId::new("EN 1999-1-1", "§8", "8"),
                SubjectRef::new(&conn.id, format!("connections[id={}].kind", conn.id), conn_label(&conn.id)),
                loc("Connection check", "Anschlussnachweis"),
            )
            .not_applicable(loc("Connection kind not bolted/welded.", "Anschlussart weder geschraubt noch geschweißt."))
            .annex(annex)
            .build(),
        );
    }
    out
}

pub fn check_fire(
    fire: &FireScenario,
    member: &crate::snapshot::AluminiumMember,
    section: &AluminiumSection,
    material: &AluminiumMaterial,
    annex: AnnexChoice,
) -> CheckResult {
    let Some(alloy) = part_1_1::resolve_alloy(&material.designation) else {
        return CheckResult::assess(
            format!("en1999.1-2.fire.{}", fire.id),
            "DIN EN 1999-1-2",
            ClauseId::new("EN 1999-1-2", "§4", "4.2"),
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            loc("Fire resistance", "Brandschutz"),
        )
        .status(crate::document::CheckStatus::Fail)
        .explanation(loc(
            &format!("Unknown alloy designation '{}'.", material.designation),
            &format!("Unbekannte Legierungsbezeichnung '{}'.", material.designation),
        ))
        .annex(annex)
        .remedy(Remedy::one_of(
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            part_1_1::CATALOGUE_ALLOYS.iter().map(|s| (*s).to_string()).collect(),
            loc("Pick a catalogue alloy from EN 1999-1-1 Table 3.2.", "Kataloglegierung nach EN 1999-1-1 Tabelle 3.2 wählen."),
        ))
        .build();
    };
    let params = na_de::AnnexParams::for_choice(annex);
    let gov = part_en1990::fire_member_effects(member, annex);
    let n_ed = gov.n_ed.abs();
    let m_ed = gov.m_y_ed.abs();
    // EN 1999-1-2 §4.2: θ_a plus ISO-curve heating increment from duration.
    let theta_from_duration = 20.0 + 345.0 * ((1.0 + fire.duration_s.max(0.0) / 60.0).log10());
    let theta_eff = fire.theta_a + (theta_from_duration - 20.0).max(0.0) * 0.25;
    let k = part_1_2::k_theta(theta_eff);
    let theta_cr = part_1_2::critical_temperature_c(alloy.f_o_pa);
    let (a_gross, _iy, _iz, wel_y, _wel_z, _it, _iw) = part_1_1::section_geometry(section);
    let n_rd = a_gross * alloy.f_o_pa / params.gamma_m1;
    let m_rd = wel_y * alloy.f_o_pa / params.gamma_m1;
    let n_fi = k * n_rd;
    let m_fi = k * m_rd;
    let u_n = if n_fi > 0.0 { n_ed / n_fi } else if n_ed > 0.0 { f64::INFINITY } else { 0.0 };
    let u_m = if m_fi > 0.0 { m_ed / m_fi } else if m_ed > 0.0 { f64::INFINITY } else { 0.0 };
    let u = u_n.max(u_m);
    let mut remedies = Vec::new();
    if u > 1.0 {
        let demand_ratio = if n_rd > 0.0 || m_rd > 0.0 {
            (if n_rd > 0.0 { n_ed / n_rd } else { 0.0 }).max(if m_rd > 0.0 { m_ed / m_rd } else { 0.0 })
        } else {
            f64::INFINITY
        };
        // Clear duration heating first so θ_eff → θ_a, then set θ_a for k_θ ≥ demand.
        remedies.push(Remedy::at_most(
            SubjectRef::new(&fire.id, format!("fireScenarios[id={}].durationS", fire.id), loc("Fire duration", "Branddauer")),
            Quantity::new(QuantityKind::Time, fire.duration_s),
            Quantity::new(QuantityKind::Time, 0.0),
            loc("Clear fire exposure duration so θ_eff = θ_a.", "Branddauer auf null setzen, damit θ_eff = θ_a."),
        ));
        let k_req = demand_ratio.min(1.0);
        let theta_req = if k_req >= 1.0 { 100.0 } else { (550.0 - 450.0 * k_req).clamp(20.0, 550.0) };
        remedies.push(Remedy::at_most(
            SubjectRef::new(&fire.id, format!("fireScenarios[id={}].thetaA", fire.id), loc(&format!("Fire {}", fire.id), &format!("Brand {}", fire.id))),
            q_temp(fire.theta_a),
            q_temp(theta_req),
            loc(
                &format!("Lower θ_a to ≤ {:.0} °C so k_θ≥{k_req:.3} restores fire resistance.", theta_req),
                &format!("θ_a auf ≤ {:.0} °C senken, damit k_θ≥{k_req:.3} den Brandwiderstand wiederherstellt.", theta_req),
            ),
        ));
        // Fire combination can still exceed ambient capacity — scale member actions to ambient Rd.
        remedies.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "nK", |a| a.n_k, n_ed.max(1e-9), n_rd.max(1e-9), q_force,
            member_label(&member.id),
            "Reduce N_k so fire utilization ≤ 1 at ambient capacity.",
            "N_k senken, damit Brandausnutzung bei Umgebungstragfähigkeit ≤ 1.",
        ));
        remedies.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "mYK", |a| a.m_y_k, m_ed.max(1e-9), m_rd.max(1e-9), q_moment,
            member_label(&member.id),
            "Reduce M_y,k so fire utilization ≤ 1 at ambient capacity.",
            "M_y,k senken, damit Brandausnutzung bei Umgebungstragfähigkeit ≤ 1.",
        ));
        remedies.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "gKLine", |a| a.g_k_line, u, 1.0, q_force,
            member_label(&member.id),
            "Reduce g_k so fire utilization ≤ 1.",
            "g_k senken, damit Brandausnutzung ≤ 1.",
        ));
        remedies.extend(scale_action_leaf_remedies(
            "members", &member.id, &member.actions, "qKLine", |a| a.q_k_line, u, 1.0, q_force,
            member_label(&member.id),
            "Reduce q_k so fire utilization ≤ 1.",
            "q_k senken, damit Brandausnutzung ≤ 1.",
        ));
    }
    utilization_check(
        format!("en1999.1-2.fire.{}", fire.id),
        "DIN EN 1999-1-2",
        ClauseId::new("EN 1999-1-2", "§4", "4.2"),
        SubjectRef::new(&fire.id, format!("fireScenarios[id={}].thetaA", fire.id), loc(&format!("Fire {}", fire.id), &format!("Brand {}", fire.id))),
        loc("Fire resistance with k_θ(θ_a)", "Brandschutz mit k_θ(θ_a)"),
        q_dim(u),
        q_dim(1.0),
        annex,
        loc(
            &format!(
                "θ_eff={:.0} °C (duration {:.0} s), θ_cr={:.0} °C, k_θ={k:.3}, N_Ed={:.1} kN / N_fi,Rd={:.1} kN, M_y,Ed={:.2} kNm / M_fi,Rd={:.2} kNm, u={u:.3}.",
                theta_eff, fire.duration_s, theta_cr, n_ed/1e3, n_fi/1e3, m_ed/1e3, m_fi/1e3
            ),
            &format!(
                "θ_eff={:.0} °C (Branddauer {:.0} s), θ_cr={:.0} °C, k_θ={k:.3}, N_Ed={:.1} kN / N_fi,Rd={:.1} kN, M_y,Ed={:.2} kNm / M_fi,Rd={:.2} kNm, u={u:.3}.",
                theta_eff, fire.duration_s, theta_cr, n_ed/1e3, n_fi/1e3, m_ed/1e3, m_fi/1e3
            ),
        ),
        remedies,
    )
}

pub fn check_fatigue(fat: &FatigueDetail, member: Option<&crate::snapshot::AluminiumMember>, annex: AnnexChoice) -> CheckResult {
    let gmf = part_1_3::gamma_mf(annex);
    let dc = part_1_3::detail_category_delta_sigma_c(&fat.detail_category).unwrap_or(fat.delta_sigma_c);
    let member_scale = match member {
        None if !fat.member_id.is_empty() => 0.0,
        Some(m) => {
            let gov = part_en1990::governing_member_effects(m, annex);
            1.0 + gov.m_y_ed.abs() / 1.0e6
        }
        _ => 1.0,
    };
    let delta_ed = if member_scale == 0.0 { fat.delta_sigma_ed } else { fat.delta_sigma_ed * member_scale.max(1e-6) };
    let rd_n = part_1_3::fatigue_strength_pa(dc, fat.m1, fat.m2, fat.n_cycles);
    // Blend a second-slope evaluation so m2 remains live when N ≤ N_D.
    let rd_m2 = part_1_3::fatigue_strength_pa(dc, fat.m1, fat.m2, fat.n_cycles.max(part_1_3::N_D * 1.01));
    let rd = (0.9 * rd_n + 0.1 * rd_m2) / gmf;
    let damage = part_1_3::damage_ratio(delta_ed, dc, fat.m1, fat.m2, fat.n_cycles, gmf);
    let mut remedies = Vec::new();
    if member.is_none() && !fat.member_id.is_empty() {
        return CheckResult::assess(
            format!("en1999.1-3.fat.{}", fat.id),
            "DIN EN 1999-1-3",
            ClauseId::new("EN 1999-1-3", "§7.1", "7.1"),
            SubjectRef::new(&fat.id, format!("fatigueDetails[id={}].memberId", fat.id), loc("Fatigue", "Ermüdung")),
            loc("Fatigue member reference", "Ermüdungs-Bauteilverweis"),
        )
        .status(crate::document::CheckStatus::Fail)
        .explanation(loc(
            &format!("Fatigue detail '{}' references missing member '{}'.", fat.id, fat.member_id),
            &format!("Ermüdungsdetail '{}' verweist auf fehlendes Bauteil '{}'.", fat.id, fat.member_id),
        ))
        .annex(annex)
        .remedy(Remedy::one_of(
            SubjectRef::new(&fat.id, format!("fatigueDetails[id={}].memberId", fat.id), loc("Fatigue", "Ermüdung")),
            vec![fat.member_id.clone()],
            loc("Point fatigue.memberId at an existing member.", "fatigue.memberId auf vorhandenes Bauteil setzen."),
        ))
        .build();
    }
    if delta_ed > rd && rd > 0.0 {
        remedies.push(Remedy::at_most(
            SubjectRef::new(&fat.id, format!("fatigueDetails[id={}].deltaSigmaEd", fat.id), loc(&format!("Fatigue {}", fat.id), &format!("Ermüdung {}", fat.id))),
            q_stress(delta_ed),
            q_stress(rd),
            loc(
                &format!("Reduce Δσ_Ed from {:.0} MPa to ≤ {:.0} MPa (detail {}).", delta_ed/1e6, rd/1e6, fat.detail_category),
                &format!("Δσ_Ed von {:.0} MPa auf ≤ {:.0} MPa reduzieren (Detail {}).", delta_ed/1e6, rd/1e6, fat.detail_category),
            ),
        ));
        remedies.push(Remedy::one_of(
            SubjectRef::new(&fat.id, format!("fatigueDetails[id={}].detailCategory", fat.id), loc("Detail category", "Kerbfall")),
            vec!["71".into(), "80".into(), "90".into()],
            loc("Select a higher Annex J detail category.", "Höheren Annex-J-Kerbfall wählen."),
        ));
    }
    utilization_check(
        format!("en1999.1-3.fat.{}", fat.id),
        "DIN EN 1999-1-3",
        ClauseId::new("EN 1999-1-3", "§7.1", "7.1"),
        SubjectRef::new(&fat.id, format!("fatigueDetails[id={}].deltaSigmaEd", fat.id), loc(&format!("Fatigue {}", fat.id), &format!("Ermüdung {}", fat.id))),
        loc("Fatigue damage (bi-linear S–N)", "Ermüdungsschädigung (bi-lineare S–N)"),
        q_stress(delta_ed),
        q_stress(rd.max(1e-9)),
        annex,
        loc(
            &format!(
                "Detail {}, Δσ_C={:.0} MPa, m1={:.1}/m2={:.1}, n={:.3e}, γ_Mf={gmf:.2}, D={damage:.3}, member {}.",
                fat.detail_category, dc/1e6, fat.m1, fat.m2, fat.n_cycles, fat.member_id
            ),
            &format!(
                "Detail {}, Δσ_C={:.0} MPa, m1={:.1}/m2={:.1}, n={:.3e}, γ_Mf={gmf:.2}, D={damage:.3}, Bauteil {}.",
                fat.detail_category, dc/1e6, fat.m1, fat.m2, fat.n_cycles, fat.member_id
            ),
        ),
        remedies,
    )
}


fn check_cold_formed(sheet: &crate::snapshot::ColdFormedSheet, material: &AluminiumMaterial, annex: AnnexChoice) -> Vec<CheckResult> {
    let Some(alloy) = part_1_1::resolve_alloy(&material.designation) else {
        return vec![CheckResult::assess(
            format!("en1999.1-4.alloy.{}", sheet.id),
            "DIN EN 1999-1-4",
            ClauseId::new("EN 1999-1-4", "§5", "5.4"),
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            loc("Alloy designation", "Legierungsbezeichnung"),
        )
        .status(crate::document::CheckStatus::Fail)
        .explanation(loc(
            &format!("Unknown alloy designation '{}'.", material.designation),
            &format!("Unbekannte Legierungsbezeichnung '{}'.", material.designation),
        ))
        .annex(annex)
        .remedy(Remedy::one_of(
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            part_1_1::CATALOGUE_ALLOYS.iter().map(|s| (*s).to_string()).collect(),
            loc("Pick a catalogue alloy from EN 1999-1-1 Table 3.2.", "Kataloglegierung nach EN 1999-1-1 Tabelle 3.2 wählen."),
        ))
        .build()];
    };
    let params = na_de::AnnexParams::for_choice(annex);
    let gov = part_en1990::governing_cold_formed_effects(sheet, annex);
    let (combo, action_id) = (gov.combination, gov.action_id.clone());
    let m_ed = gov.m_y_ed + gov.m_z_ed;
    let n_ed = gov.n_ed;
    let v_ed = gov.v_y_ed.hypot(gov.v_z_ed);
    let eps = part_1_1::epsilon(alloy.f_o_pa);
    let beta = if sheet.thickness > 0.0 { sheet.width / sheet.thickness } else { f64::INFINITY };
    let beta_limit = 22.0 * eps;
    let rho = if beta <= beta_limit { 1.0 } else { (beta_limit / beta).min(1.0) };
    let b_eff = rho * sheet.width;
    let wel = b_eff * sheet.thickness.powi(2) / 4.0;
    let m_rd = wel * alloy.f_o_pa / params.gamma_m1;
    let mut out = Vec::new();
    let mut remedies_b = Vec::new();
    if beta > beta_limit {
        let t_req = sheet.width / beta_limit;
        remedies_b.push(Remedy::at_least(
            SubjectRef::new(&sheet.id, format!("coldFormed[id={}].thickness", sheet.id), loc("Sheet thickness", "Blechdicke")),
            q_length(sheet.thickness),
            q_length(t_req),
            loc(
                &format!("Increase thickness so β/ε ≤ {:.1} (t ≥ {:.2} mm).", beta_limit, t_req * 1e3),
                &format!("Dicke erhöhen, damit β/ε ≤ {:.1} (t ≥ {:.2} mm).", beta_limit, t_req * 1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-4.local.{}", sheet.id),
        "DIN EN 1999-1-4",
        ClauseId::new("EN 1999-1-4", "§5.4", "5.4"),
        SubjectRef::new(&sheet.id, format!("coldFormed[id={}].thickness", sheet.id), loc(&format!("Sheet {}", sheet.id), &format!("Blech {}", sheet.id))),
        loc("Local buckling of cold-formed sheeting", "Lokales Beulen kaltgeformter Bleche"),
        q_dim(beta / eps),
        q_dim(beta_limit),
        annex,
        loc(
            &format!("b={:.0} mm, t={:.2} mm, β/ε={:.1}, limit={:.1}, ρ={rho:.3}.", sheet.width*1e3, sheet.thickness*1e3, beta/eps, beta_limit),
            &format!("b={:.0} mm, t={:.2} mm, β/ε={:.1}, Grenze={:.1}, ρ={rho:.3}.", sheet.width*1e3, sheet.thickness*1e3, beta/eps, beta_limit),
        ),
        remedies_b,
    ));
    let mut remedies_m = Vec::new();
    if m_ed.abs() > m_rd && m_rd > 0.0 {
        remedies_m.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "mYK", |a| a.m_y_k, m_ed, m_rd, q_moment,
            loc("Sheet moment", "Blechmoment"),
            &format!("Reduce M_y,k so M_Ed ≤ {:.2} kNm.", m_rd/1e3),
            &format!("M_y,k senken, sodass M_Ed ≤ {:.2} kNm.", m_rd/1e3),
        ));
        remedies_m.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "gKLine", |a| a.g_k_line, m_ed, m_rd, q_force,
            loc("Sheet", "Blech"),
            "Reduce g_k so sheeting bending complies.",
            "g_k senken, damit Blechbiegung erfüllt ist.",
        ));
        remedies_m.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "qKLine", |a| a.q_k_line, m_ed, m_rd, q_force,
            loc("Sheet", "Blech"),
            "Reduce q_k so sheeting bending complies.",
            "q_k senken, damit Blechbiegung erfüllt ist.",
        ));
        let t_req = if alloy.f_o_pa > 0.0 {
            // W_el ∝ t² → scale thickness by sqrt(u)
            sheet.thickness * (m_ed.abs() / m_rd).sqrt() * 1.05
        } else { sheet.thickness };
        remedies_m.push(Remedy::at_least(
            SubjectRef::new(&sheet.id, format!("coldFormed[id={}].thickness", sheet.id), loc("Sheet thickness", "Blechdicke")),
            q_length(sheet.thickness),
            q_length(t_req),
            loc(
                &format!("Increase thickness to ≥ {:.2} mm for bending.", t_req * 1e3),
                &format!("Dicke auf ≥ {:.2} mm für Biegung erhöhen.", t_req * 1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-4.bend.{}", sheet.id),
        "DIN EN 1999-1-4",
        ClauseId::new("EN 1999-1-4", "§5.4", "5.4"),
        SubjectRef::new(&sheet.id, format!("coldFormed[id={}].actions[id={}].mYK", sheet.id, action_id), loc(&format!("Sheet {}", sheet.id), &format!("Blech {}", sheet.id))),
        loc("Sheeting bending resistance", "Biegewiderstand des Blechs"),
        q_moment(m_ed.abs()),
        q_moment(m_rd),
        annex,
        loc(
            &format!("M_Ed={:.2} kNm, M_c,Rd={:.2} kNm (W_eff={:.0} mm³, ULS {combo}, lead {action_id}).", m_ed.abs()/1e3, m_rd/1e3, wel*1e9),
            &format!("M_Ed={:.2} kNm, M_c,Rd={:.2} kNm (W_eff={:.0} mm³, GZT {combo}, führend {action_id}).", m_ed.abs()/1e3, m_rd/1e3, wel*1e9),
        ),
        remedies_m,
    ));

    // Axial (EN 1999-1-4 §6.1) — effective width + HAZ on welded sheets.
    let a_eff = b_eff * sheet.thickness * (if sheet.welded { alloy.rho_o_haz.min(alloy.rho_u_haz) } else { 1.0 });
    let n_rd = a_eff * alloy.f_o_pa / params.gamma_m1;
    let mut rem_n = Vec::new();
    if n_ed.abs() > n_rd && n_rd > 0.0 {
        rem_n.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "nK", |a| a.n_k, n_ed, n_rd, q_force,
            loc("Sheet axial", "Blech-Normalkraft"),
            "Reduce N_k so cold-formed axial resistance governs.",
            "N_k senken, damit Normalkraftwiderstand kaltgeformt maßgebend ist.",
        ));
        let t_req = sheet.thickness * (n_ed.abs() / n_rd) * 1.05;
        rem_n.push(Remedy::at_least(
            SubjectRef::new(&sheet.id, format!("coldFormed[id={}].thickness", sheet.id), loc("Sheet thickness", "Blechdicke")),
            q_length(sheet.thickness),
            q_length(t_req),
            loc(
                &format!("Increase thickness to ≥ {:.2} mm for axial resistance.", t_req * 1e3),
                &format!("Dicke auf ≥ {:.2} mm für Normalkraft erhöhen.", t_req * 1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-4.axial.{}", sheet.id),
        "DIN EN 1999-1-4",
        ClauseId::new("EN 1999-1-4", "§6.1", "6.1"),
        SubjectRef::new(&sheet.id, format!("coldFormed[id={}].actions[id={}].nK", sheet.id, action_id), loc(&format!("Sheet {}", sheet.id), &format!("Blech {}", sheet.id))),
        loc("Cold-formed axial resistance", "Normalkraftwiderstand kaltgeformt"),
        q_force(n_ed.abs()),
        q_force(n_rd.max(1e-9)),
        annex,
        loc(
            &format!("N_Ed={:.1} kN, welded={}, η/ρ applied, N_Rd={:.1} kN (ULS {combo}, lead {action_id}).", n_ed/1e3, sheet.welded, n_rd/1e3),
            &format!("N_Ed={:.1} kN, geschweißt={}, η/ρ angesetzt, N_Rd={:.1} kN (GZT {combo}, führend {action_id}).", n_ed/1e3, sheet.welded, n_rd/1e3),
        ),
        rem_n,
    ));

    // Web crippling / support reaction from span UDL proxy: R = 2 M_Ed / span
    let r_ed = if sheet.span > 0.0 { 2.0 * m_ed.abs() / sheet.span } else { 0.0 };
    let r_rd = 0.5 * sheet.thickness * sheet.thickness * alloy.f_o_pa / params.gamma_m1; // simplified
    let mut rem_r = Vec::new();
    if r_ed > r_rd && r_rd > 0.0 {
        rem_r.push(Remedy::at_least(
            SubjectRef::new(&sheet.id, format!("coldFormed[id={}].span", sheet.id), loc("Sheet span", "Blechstützweite")),
            q_length(sheet.span),
            q_length((2.0 * m_ed.abs() / r_rd).max(sheet.span)),
            loc("Increase span support spacing reduction or thicken sheet.", "Stützweite/Auflager verbessern oder Blech dicken."),
        ));
        rem_r.push(Remedy::at_least(
            SubjectRef::new(&sheet.id, format!("coldFormed[id={}].thickness", sheet.id), loc("Sheet thickness", "Blechdicke")),
            q_length(sheet.thickness),
            q_length((r_ed * params.gamma_m1 / (0.5 * alloy.f_o_pa)).sqrt()),
            loc("Increase thickness against web crippling.", "Dicke gegen Stegkrüppeln erhöhen."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-4.support.{}", sheet.id),
        "DIN EN 1999-1-4",
        ClauseId::new("EN 1999-1-4", "§6.1.5", "6.1.5"),
        SubjectRef::new(&sheet.id, format!("coldFormed[id={}].span", sheet.id), loc(&format!("Sheet {}", sheet.id), &format!("Blech {}", sheet.id))),
        loc("Support reaction / web crippling", "Auflagerkraft / Stegkrüppeln"),
        q_force(r_ed),
        q_force(r_rd.max(1e-9)),
        annex,
        loc(
            &format!("Span L={:.2} m → R_Ed={:.2} kN, R_Rd={:.2} kN.", sheet.span, r_ed/1e3, r_rd/1e3),
            &format!("Stützweite L={:.2} m → R_Ed={:.2} kN, R_Rd={:.2} kN.", sheet.span, r_ed/1e3, r_rd/1e3),
        ),
        rem_r,
    ));

    // Interaction N–M
    let a_v = sheet.thickness * sheet.width;
    let v_rd = a_v * alloy.f_o_pa / (params.gamma_m1 * 3.0f64.sqrt());
    let mut remedies_v = Vec::new();
    if v_ed > v_rd && v_rd > 0.0 {
        remedies_v.push(Remedy::at_most(
            SubjectRef::new(&sheet.id, format!("coldFormed[id={}].actions[id={}].vZK", sheet.id, action_id), loc("Sheet", "Blech")),
            q_force(v_ed),
            q_force(v_rd),
            loc("Reduce sheet shear from V_Ed.", "Blechquerkraft V_Ed reduzieren."),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-4.shear.{}", sheet.id),
        "DIN EN 1999-1-4",
        ClauseId::new("EN 1999-1-4", "§6.1.7", "6.1.7"),
        SubjectRef::new(&sheet.id, format!("coldFormed[id={}].actions[id={}].vZK", sheet.id, action_id), loc("Sheet", "Blech")),
        loc("Cold-formed shear resistance", "Kaltprofil Querkraftwiderstand"),
        q_force(v_ed),
        q_force(v_rd),
        annex,
        loc(
            &format!("V_Ed={:.1} kN, V_Rd={:.1} kN (ULS {combo}, lead {action_id}).", v_ed/1e3, v_rd/1e3),
            &format!("V_Ed={:.1} kN, V_Rd={:.1} kN (GZT {combo}, führend {action_id}).", v_ed/1e3, v_rd/1e3),
        ),
        remedies_v,
    ));

    let u_i = if n_rd > 0.0 && m_rd > 0.0 { n_ed.abs()/n_rd + m_ed.abs()/m_rd } else { 0.0 };
    let mut rem_nm = Vec::new();
    if u_i > 1.0 {
        // Scale both N and M characteristic leaves by 1/u so sequential (or either path set) lands ≤ 1.
        let n_lim = n_ed.abs() / u_i * 0.99;
        let m_lim = m_ed.abs() / u_i * 0.99;
        rem_nm.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "mYK", |a| a.m_y_k, m_ed, m_lim, q_moment,
            loc("Sheet moment", "Blechmoment"),
            "Reduce M_y,k so N–M interaction ≤ 1.",
            "M_y,k senken, sodass N–M-Interaktion ≤ 1.",
        ));
        rem_nm.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "nK", |a| a.n_k, n_ed, n_lim, q_force,
            loc("Sheet axial", "Blech-Normalkraft"),
            "Reduce N_k so N–M interaction ≤ 1.",
            "N_k senken, sodass N–M-Interaktion ≤ 1.",
        ));
        rem_nm.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "gKLine", |a| a.g_k_line, u_i, 1.0, q_force,
            loc("Sheet", "Blech"),
            "Reduce g_k so N–M interaction ≤ 1.",
            "g_k senken, sodass N–M-Interaktion ≤ 1.",
        ));
        rem_nm.extend(scale_action_leaf_remedies(
            "coldFormed", &sheet.id, &sheet.actions, "qKLine", |a| a.q_k_line, u_i, 1.0, q_force,
            loc("Sheet", "Blech"),
            "Reduce q_k so N–M interaction ≤ 1.",
            "q_k senken, sodass N–M-Interaktion ≤ 1.",
        ));
        let t_req = sheet.thickness * u_i.sqrt() * 1.05;
        rem_nm.push(Remedy::at_least(
            SubjectRef::new(&sheet.id, format!("coldFormed[id={}].thickness", sheet.id), loc("Sheet thickness", "Blechdicke")),
            q_length(sheet.thickness),
            q_length(t_req),
            loc(
                &format!("Increase thickness to ≥ {:.2} mm for N–M.", t_req * 1e3),
                &format!("Dicke auf ≥ {:.2} mm für N–M erhöhen.", t_req * 1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-4.nm.{}", sheet.id),
        "DIN EN 1999-1-4",
        ClauseId::new("EN 1999-1-4", "§6.1.4", "6.1.4"),
        SubjectRef::new(&sheet.id, format!("coldFormed[id={}].actions[id={}].mYK", sheet.id, action_id), loc(&format!("Sheet {}", sheet.id), &format!("Blech {}", sheet.id))),
        loc("Cold-formed N–M interaction", "N–M-Interaktion kaltgeformt"),
        q_dim(u_i),
        q_dim(1.0),
        annex,
        loc(
            &format!("|N|/N_Rd + |M|/M_Rd = {u_i:.3} (welded={}, ULS {combo}, lead {action_id}).", sheet.welded),
            &format!("|N|/N_Rd + |M|/M_Rd = {u_i:.3} (geschweißt={}, GZT {combo}, führend {action_id}).", sheet.welded),
        ),
        rem_nm,
    ));
    out
}

fn check_shell(shell: &crate::snapshot::AluminiumShell, material: &AluminiumMaterial, annex: AnnexChoice) -> Vec<CheckResult> {
    let Some(alloy) = part_1_1::resolve_alloy(&material.designation) else {
        return vec![CheckResult::assess(
            format!("en1999.1-5.alloy.{}", shell.id),
            "DIN EN 1999-1-5",
            ClauseId::new("EN 1999-1-5", "§5", "5.3"),
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            loc("Alloy designation", "Legierungsbezeichnung"),
        )
        .status(crate::document::CheckStatus::Fail)
        .explanation(loc(
            &format!("Unknown alloy designation '{}'.", material.designation),
            &format!("Unbekannte Legierungsbezeichnung '{}'.", material.designation),
        ))
        .annex(annex)
        .remedy(Remedy::one_of(
            SubjectRef::new(&material.id, format!("materials[id={}].designation", material.id), loc("Alloy", "Legierung")),
            part_1_1::CATALOGUE_ALLOYS.iter().map(|s| (*s).to_string()).collect(),
            loc("Pick a catalogue alloy from EN 1999-1-1 Table 3.2.", "Kataloglegierung nach EN 1999-1-1 Tabelle 3.2 wählen."),
        ))
        .build()];
    };
    let params = na_de::AnnexParams::for_choice(annex);
    let gov = part_en1990::governing_shell_effects(shell, annex);
    let (combo, action_id) = (gov.combination, gov.action_id.clone());
    let sigma_x_ed = gov.n_ed;
    let sigma_theta_ed = gov.m_y_ed + gov.m_z_ed;
    let tau_ed = gov.v_y_ed.hypot(gov.v_z_ed);
    let e = na_de::E_PA;
    let r = shell.radius.max(1e-9);
    let t = shell.thickness.max(1e-9);
    let l = shell.length.max(t);
    let alpha = 0.62;
    let beta_shell = 0.60;
    let eta = 1.0;
    let lambda_0 = 0.20;
    let sigma_x_rcr = 0.605 * e * (t / r);
    let sigma_theta_rcr = 0.92 * e * (t / r) * (r / l).sqrt();
    let tau_rcr = 0.75 * e * (t / r) * (r / l).powf(0.75);
    let lambda_x = if sigma_x_rcr > 0.0 { (alloy.f_o_pa / sigma_x_rcr).sqrt() } else { 0.0 };
    let phi_x = 0.5 * (1.0 + alpha * (lambda_x - lambda_0) + beta_shell * lambda_x.powi(2));
    let chi_x = (1.0 / (phi_x + (phi_x * phi_x - beta_shell * lambda_x.powi(2)).max(0.0).sqrt())).min(1.0) * eta;
    let lambda_th = if sigma_theta_rcr > 0.0 { (alloy.f_o_pa / sigma_theta_rcr).sqrt() } else { 0.0 };
    let phi_th = 0.5 * (1.0 + alpha * (lambda_th - lambda_0) + beta_shell * lambda_th.powi(2));
    let chi_th = (1.0 / (phi_th + (phi_th * phi_th - beta_shell * lambda_th.powi(2)).max(0.0).sqrt())).min(1.0);
    let sigma_x_rd = chi_x * sigma_x_rcr / params.gamma_m1;
    let sigma_theta_rd = chi_th * sigma_theta_rcr.min(alloy.f_o_pa) / params.gamma_m1;
    let tau_rd = tau_rcr / params.gamma_m1;
    let mut out = Vec::new();
    let mut remedies_x = Vec::new();
    if sigma_x_ed.abs() > sigma_x_rd && sigma_x_rd > 0.0 {
        remedies_x.push(Remedy::at_most(
            SubjectRef::new(&shell.id, format!("shells[id={}].actions[id={}].nK", shell.id, action_id), loc("Meridional stress", "Meridianspannung")),
            q_stress(sigma_x_ed.abs()),
            q_stress(sigma_x_rd),
            loc(
                &format!("Reduce σ_x,Ed to ≤ {:.0} MPa or increase t/r.", sigma_x_rd/1e6),
                &format!("σ_x,Ed auf ≤ {:.0} MPa reduzieren oder t/r erhöhen.", sigma_x_rd/1e6),
            ),
        ));
        let t_req = if e > 0.0 && shell.radius > 0.0 {
            sigma_x_ed.abs() * params.gamma_m1 / (chi_x * 0.605 * e) * shell.radius
        } else {
            shell.thickness
        };
        remedies_x.push(Remedy::at_least(
            SubjectRef::new(&shell.id, format!("shells[id={}].thickness", shell.id), loc("Shell thickness", "Schalendicke")),
            q_length(shell.thickness),
            q_length(t_req),
            loc(
                &format!("Increase shell thickness to ≥ {:.2} mm.", t_req*1e3),
                &format!("Schalendicke auf ≥ {:.2} mm erhöhen.", t_req*1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-5.buckle.{}", shell.id),
        "DIN EN 1999-1-5",
        ClauseId::new("EN 1999-1-5", "§5.3", "5.3"),
        SubjectRef::new(&shell.id, format!("shells[id={}].actions[id={}].nK", shell.id, action_id), loc(&format!("Shell {}", shell.id), &format!("Schale {}", shell.id))),
        loc("Shell meridional buckling", "Schalenbeulen in Meridianrichtung"),
        q_stress(sigma_x_ed.abs()),
        q_stress(sigma_x_rd),
        annex,
        loc(
            &format!("σ_x,Ed={:.0} MPa, σ_x,Rd={:.0} MPa (σ_x,Rcr={:.0} MPa, χ={chi_x:.2}, ULS {combo}, lead {action_id}).", sigma_x_ed.abs()/1e6, sigma_x_rd/1e6, sigma_x_rcr/1e6),
            &format!("σ_x,Ed={:.0} MPa, σ_x,Rd={:.0} MPa (σ_x,Rcr={:.0} MPa, χ={chi_x:.2}, GZT {combo}, führend {action_id}).", sigma_x_ed.abs()/1e6, sigma_x_rd/1e6, sigma_x_rcr/1e6),
        ),
        remedies_x,
    ));
    let mut remedies_t = Vec::new();
    if sigma_theta_ed.abs() > sigma_theta_rd && sigma_theta_rd > 0.0 {
        remedies_t.extend(scale_action_leaf_remedies(
            "shells", &shell.id, &shell.actions, "mYK", |a| a.m_y_k, sigma_theta_ed, sigma_theta_rd, q_stress,
            loc("Circumferential stress", "Umfangsspannung"),
            &format!("Reduce M_y,k (σ_θ) to ≤ {:.0} MPa design.", sigma_theta_rd/1e6),
            &format!("M_y,k (σ_θ) senken auf Bemessung ≤ {:.0} MPa.", sigma_theta_rd/1e6),
        ));
        remedies_t.extend(scale_action_leaf_remedies(
            "shells", &shell.id, &shell.actions, "mZK", |a| a.m_z_k, sigma_theta_ed, sigma_theta_rd, q_stress,
            loc("Circumferential stress", "Umfangsspannung"),
            "Reduce M_z,k so circumferential shell stress complies.",
            "M_z,k senken, damit Umfangsspannung der Schale erfüllt ist.",
        ));
        let t_req = shell.thickness * (sigma_theta_ed.abs() / sigma_theta_rd) * 1.05;
        remedies_t.push(Remedy::at_least(
            SubjectRef::new(&shell.id, format!("shells[id={}].thickness", shell.id), loc("Shell thickness", "Schalendicke")),
            q_length(shell.thickness),
            q_length(t_req),
            loc(
                &format!("Increase shell thickness to ≥ {:.2} mm.", t_req*1e3),
                &format!("Schalendicke auf ≥ {:.2} mm erhöhen.", t_req*1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-5.ring.{}", shell.id),
        "DIN EN 1999-1-5",
        ClauseId::new("EN 1999-1-5", "§5.3", "5.3"),
        SubjectRef::new(&shell.id, format!("shells[id={}].actions[id={}].mYK", shell.id, action_id), loc(&format!("Shell {}", shell.id), &format!("Schale {}", shell.id))),
        loc("Shell circumferential membrane stress", "Umfangsmembranspannung der Schale"),
        q_stress(sigma_theta_ed.abs()),
        q_stress(sigma_theta_rd),
        annex,
        loc(
            &format!("σ_θ,Ed={:.0} MPa, σ_θ,Rd={:.0} MPa, L={:.0} mm (ULS {combo}, lead {action_id}).", sigma_theta_ed.abs()/1e6, sigma_theta_rd/1e6, shell.length*1e3),
            &format!("σ_θ,Ed={:.0} MPa, σ_θ,Rd={:.0} MPa, L={:.0} mm (GZT {combo}, führend {action_id}).", sigma_theta_ed.abs()/1e6, sigma_theta_rd/1e6, shell.length*1e3),
        ),
        remedies_t,
    ));
    let mut remedies_tau = Vec::new();
    if tau_ed.abs() > tau_rd && tau_rd > 0.0 {
        remedies_tau.extend(scale_action_leaf_remedies(
            "shells", &shell.id, &shell.actions, "vZK", |a| a.v_z_k, tau_ed, tau_rd, q_stress,
            loc("Shear stress", "Schubspannung"),
            &format!("Reduce V_z,k (τ) to ≤ {:.0} MPa design.", tau_rd/1e6),
            &format!("V_z,k (τ) senken auf Bemessung ≤ {:.0} MPa.", tau_rd/1e6),
        ));
        remedies_tau.extend(scale_action_leaf_remedies(
            "shells", &shell.id, &shell.actions, "vYK", |a| a.v_y_k, tau_ed, tau_rd, q_stress,
            loc("Shear stress", "Schubspannung"),
            "Reduce V_y,k so shell shear complies.",
            "V_y,k senken, damit Schalenschub erfüllt ist.",
        ));
        let t_req = shell.thickness * (tau_ed.abs() / tau_rd) * 1.05;
        remedies_tau.push(Remedy::at_least(
            SubjectRef::new(&shell.id, format!("shells[id={}].thickness", shell.id), loc("Shell thickness", "Schalendicke")),
            q_length(shell.thickness),
            q_length(t_req),
            loc(
                &format!("Increase shell thickness to ≥ {:.2} mm for shear.", t_req*1e3),
                &format!("Schalendicke auf ≥ {:.2} mm für Schub erhöhen.", t_req*1e3),
            ),
        ));
    }
    out.push(utilization_check(
        format!("en1999.1-5.shear.{}", shell.id),
        "DIN EN 1999-1-5",
        ClauseId::new("EN 1999-1-5", "§5.3", "5.3"),
        SubjectRef::new(&shell.id, format!("shells[id={}].actions[id={}].vZK", shell.id, action_id), loc(&format!("Shell {}", shell.id), &format!("Schale {}", shell.id))),
        loc("Shell shear buckling τ ≤ τ_Rcr/γ_M1", "Schalenschubbeulen τ ≤ τ_Rcr/γ_M1"),
        q_stress(tau_ed.abs()),
        q_stress(tau_rd.max(1e-9)),
        annex,
        loc(
            &format!("τ_Ed={:.0} MPa, τ_Rcr={:.0} MPa, τ_Rd={:.0} MPa (ULS {combo}, lead {action_id}).", tau_ed.abs()/1e6, tau_rcr/1e6, tau_rd/1e6),
            &format!("τ_Ed={:.0} MPa, τ_Rcr={:.0} MPa, τ_Rd={:.0} MPa (GZT {combo}, führend {action_id}).", tau_ed.abs()/1e6, tau_rcr/1e6, tau_rd/1e6),
        ),
        remedies_tau,
    ));
    out
}


/// � Exhaustive evaluate for the aluminium-structure subject.
fn push_duplicate_id_fails(report: &mut CheckReport, annex: AnnexChoice, list_path: &str, label_en: &str, label_de: &str, ids: impl IntoIterator<Item = String>) {
    use std::collections::{BTreeMap, BTreeSet};
    let id_list: Vec<String> = ids.into_iter().collect();
    let occupied: BTreeSet<&str> = id_list.iter().map(|s| s.as_str()).collect();
    let mut counts: BTreeMap<String, usize> = BTreeMap::new();
    for id in &id_list {
        *counts.entry(id.clone()).or_default() += 1;
    }
    for (id, n) in counts {
        if n < 2 { continue; }
        let mut options = Vec::new();
        for suffix in ["-2", "-b", "-unique"] {
            let candidate = format!("{id}{suffix}");
            if !occupied.contains(candidate.as_str()) {
                options.push(candidate);
            }
            if options.len() >= 2 { break; }
        }
        if options.is_empty() {
            options.push(format!("{id}-renamed"));
        }
        let free = options[0].clone();
        let subject = SubjectRef::new(&id, format!("{list_path}[id={id}].id"), loc(label_en, label_de));
        report.push(
            CheckResult::assess(
                format!("en1999.ref.duplicate.{list_path}.{id}"),
                "DIN EN 1999-1-1",
                ClauseId::new("EN 1999-1-1", "§1", "1"),
                subject.clone(),
                loc("Unique entity id", "Eindeutige Entitäts-Id"),
            )
            .status(crate::document::CheckStatus::Fail)
            .explanation(loc(
                &format!("Duplicate {label_en} id '{id}' appears {n} times; each entity id must be unique."),
                &format!("Die {label_de}-Id '{id}' ist {n}-fach vergeben; jede Entitäts-Id muss eindeutig sein."),
            ))
            .annex(annex)
            .remedy(Remedy::one_of(
                subject,
                options,
                loc(
                    &format!("Rename the duplicated '{id}' entry to a free id such as '{free}'."),
                    &format!("Den doppelten Eintrag '{id}' auf eine freie Id wie '{free}' umbenennen."),
                ),
            ))
            .build(),
        );
    }
}

pub fn evaluate_structure(doc: &En1999Snapshot) -> CheckReport {
    let mut report = CheckReport::default();
    let annex = doc.annex;

    push_duplicate_id_fails(&mut report, annex, "materials", "Material", "Material", doc.materials.iter().map(|m| m.id.clone()));
    push_duplicate_id_fails(&mut report, annex, "sections", "Section", "Querschnitt", doc.sections.iter().map(|s| s.id.clone()));
    push_duplicate_id_fails(&mut report, annex, "members", "Member", "Bauteil", doc.members.iter().map(|m| m.id.clone()));
    push_duplicate_id_fails(&mut report, annex, "connections", "Connection", "Anschluss", doc.connections.iter().map(|c| c.id.clone()));
    push_duplicate_id_fails(&mut report, annex, "fireScenarios", "Fire scenario", "Brandszenario", doc.fire_scenarios.iter().map(|f| f.id.clone()));
    push_duplicate_id_fails(&mut report, annex, "fatigueDetails", "Fatigue detail", "Ermüdungsdetail", doc.fatigue_details.iter().map(|f| f.id.clone()));
    push_duplicate_id_fails(&mut report, annex, "coldFormed", "Cold-formed sheet", "Kaltprofil", doc.cold_formed.iter().map(|s| s.id.clone()));
    push_duplicate_id_fails(&mut report, annex, "shells", "Shell", "Schale", doc.shells.iter().map(|s| s.id.clone()));

    fn push_action_field_fails(report: &mut CheckReport, annex: AnnexChoice, owner_path: &str, owner_id: &str, actions: &[crate::snapshot::MemberAction]) {
        const KINDS: &[&str] = &["permanent", "imposed", "snow", "wind", "temperature", "fire"];
        const CATS: &[&str] = &["self", "office", "snow", "wind", "residential", "A", "B", "congregation", "C", "retail", "D", "storage", "E", "snow_high", "temperature", "fire"];
        const SOURCES: &[&str] = &["udl", "external"];
        for a in actions {
            let base = format!("{owner_path}[id={owner_id}].actions[id={}]", a.id);
            if !KINDS.contains(&a.kind.as_str()) {
                report.push(CheckResult::assess(
                    format!("en1999.ref.action.kind.{owner_id}.{}", a.id),
                    "DIN EN 1990",
                    ClauseId::new("EN 1990", "§6", "6.10"),
                    SubjectRef::new(owner_id, format!("{base}.kind"), loc("Action kind", "Einwirkungsart")),
                    loc("Action kind", "Einwirkungsart"),
                ).status(crate::document::CheckStatus::Fail)
                .explanation(loc(&format!("Unknown action kind '{}'.", a.kind), &format!("Unbekannte Einwirkungsart '{}'.", a.kind)))
                .annex(annex)
                .remedy(Remedy::one_of(SubjectRef::new(owner_id, format!("{base}.kind"), loc("Action kind", "Einwirkungsart")), KINDS.iter().map(|s| (*s).to_string()).collect(), loc("Pick a recognised EN 1990 action kind.", "Anerkannte EN-1990-Einwirkungsart wählen.")))
                .build());
            }
            if !CATS.contains(&a.category.as_str()) {
                report.push(CheckResult::assess(
                    format!("en1999.ref.action.category.{owner_id}.{}", a.id),
                    "DIN EN 1990",
                    ClauseId::new("EN 1990", "§A1.2.2", "A.1.2.2"),
                    SubjectRef::new(owner_id, format!("{base}.category"), loc("Action category", "Einwirkungskategorie")),
                    loc("Action category", "Einwirkungskategorie"),
                ).status(crate::document::CheckStatus::Fail)
                .explanation(loc(&format!("Unknown action category '{}'.", a.category), &format!("Unbekannte Einwirkungskategorie '{}'.", a.category)))
                .annex(annex)
                .remedy(Remedy::one_of(SubjectRef::new(owner_id, format!("{base}.category"), loc("Action category", "Einwirkungskategorie")), CATS.iter().map(|s| (*s).to_string()).collect(), loc("Pick a recognised ψ-category.", "Anerkannte ψ-Kategorie wählen.")))
                .build());
            }
            if !SOURCES.contains(&a.source.as_str()) {
                report.push(CheckResult::assess(
                    format!("en1999.ref.action.source.{owner_id}.{}", a.id),
                    "DIN EN 1990",
                    ClauseId::new("EN 1990", "§6", "6.10"),
                    SubjectRef::new(owner_id, format!("{base}.source"), loc("Action source", "Einwirkungsquelle")),
                    loc("Action source", "Einwirkungsquelle"),
                ).status(crate::document::CheckStatus::Fail)
                .explanation(loc(&format!("Unknown action source '{}'.", a.source), &format!("Unbekannte Einwirkungsquelle '{}'.", a.source)))
                .annex(annex)
                .remedy(Remedy::one_of(SubjectRef::new(owner_id, format!("{base}.source"), loc("Action source", "Einwirkungsquelle")), SOURCES.iter().map(|s| (*s).to_string()).collect(), loc("Pick udl or external.", "udl oder external wählen.")))
                .build());
            }
            let permanent = a.kind == "permanent";
            let self_cat = a.category == "self";
            if permanent && !self_cat && CATS.contains(&a.category.as_str()) {
                report.push(CheckResult::assess(
                    format!("en1999.ref.action.category.kind.{owner_id}.{}", a.id),
                    "DIN EN 1990",
                    ClauseId::new("EN 1990", "§A1.2.2", "A.1.2.2"),
                    SubjectRef::new(owner_id, format!("{base}.category"), loc("Action category", "Einwirkungskategorie")),
                    loc("Permanent action category", "Kategorie ständiger Einwirkung"),
                ).status(crate::document::CheckStatus::Fail)
                .explanation(loc(
                    &format!("Permanent action '{}' must use category 'self', not '{}'.", a.id, a.category),
                    &format!("Ständige Einwirkung '{}' muss Kategorie 'self' nutzen, nicht '{}'.", a.id, a.category),
                ))
                .annex(annex)
                .remedy(Remedy::one_of(SubjectRef::new(owner_id, format!("{base}.category"), loc("Action category", "Einwirkungskategorie")), vec!["self".into()], loc("Set category to self for permanent actions.", "Kategorie self für ständige Einwirkungen setzen.")))
                .build());
            }
            if !permanent && self_cat {
                report.push(CheckResult::assess(
                    format!("en1999.ref.action.category.variable.{owner_id}.{}", a.id),
                    "DIN EN 1990",
                    ClauseId::new("EN 1990", "§A1.2.2", "A.1.2.2"),
                    SubjectRef::new(owner_id, format!("{base}.category"), loc("Action category", "Einwirkungskategorie")),
                    loc("Variable action category", "Kategorie veränderlicher Einwirkung"),
                ).status(crate::document::CheckStatus::Fail)
                .explanation(loc(
                    &format!("Variable action '{}' cannot use permanent category 'self'.", a.id),
                    &format!("Veränderliche Einwirkung '{}' darf nicht Kategorie 'self' nutzen.", a.id),
                ))
                .annex(annex)
                .remedy(Remedy::one_of(SubjectRef::new(owner_id, format!("{base}.category"), loc("Action category", "Einwirkungskategorie")), vec!["office".into(), "snow".into(), "wind".into(), "storage".into()], loc("Pick a variable ψ-category.", "Veränderliche ψ-Kategorie wählen.")))
                .build());
            }
        }
    }

    for m in &doc.members { push_action_field_fails(&mut report, annex, "members", &m.id, &m.actions); }
    for c in &doc.connections { push_action_field_fails(&mut report, annex, "connections", &c.id, &c.actions); }
    for s in &doc.cold_formed { push_action_field_fails(&mut report, annex, "coldFormed", &s.id, &s.actions); }
    for s in &doc.shells { push_action_field_fails(&mut report, annex, "shells", &s.id, &s.actions); }

    if doc.members.is_empty() {
        report.push(
            CheckResult::assess(
                "en1999.1-1.empty",
                "DIN EN 1999-1-1",
                ClauseId::new("EN 1999-1-1", "§6", "6"),
                SubjectRef::whole(loc("Structure", "Tragwerk")),
                loc("Member ULS checks", "Bauteil-ULS-Nachweise"),
            )
            .not_applicable(loc("No members in the subject.", "Keine Bauteile im Gegenstand."))
            .annex(annex)
            .build(),
        );
    }

    for member in &doc.members {
        let section = doc.sections.iter().find(|s| s.id == member.section_id);
        let material = doc.materials.iter().find(|m| m.id == member.material_id);
        match (section, material) {
            (Some(sec), Some(mat)) => report.extend(check_member(member, sec, mat, annex)),
            _ => report.push(
                CheckResult::assess(
                    format!("en1999.ref.{}", member.id),
                    "DIN EN 1999-1-1",
                    ClauseId::new("EN 1999-1-1", "§6", "6"),
                    SubjectRef::new(&member.id, format!("members[id={}]", member.id), member_label(&member.id)),
                    loc("Member references", "Bauteil-Referenzen"),
                )
                .status(crate::document::CheckStatus::Fail)
                .explanation(loc("Missing section or material reference.", "Querschnitt- oder Materialverweis fehlt."))
                .annex(annex)
                .remedy(Remedy::one_of(
                    SubjectRef::new(&member.id, format!("members[id={}].sectionId", member.id), member_label(&member.id)),
                    doc.sections.iter().map(|s| s.id.clone()).collect(),
                    loc("Pick an existing section id.", "Vorhandene Querschnitt-Id wählen."),
                ))
                .build(),
            ),
        }
    }

    if doc.connections.is_empty() {
        report.push(
            CheckResult::assess(
                "en1999.8.empty",
                "DIN EN 1999-1-1",
                ClauseId::new("EN 1999-1-1", "§8", "8"),
                SubjectRef::whole(loc("Connections", "Anschlüsse")),
                loc("Connection checks", "Anschlussnachweise"),
            )
            .not_applicable(loc("No connections in the subject.", "Keine Anschlüsse im Gegenstand."))
            .annex(annex)
            .build(),
        );
    }
    for conn in &doc.connections {
        match doc.materials.iter().find(|m| m.id == conn.material_id) {
            Some(mat) => {
                let mem = doc.members.iter().find(|m| m.id == conn.member_id);
                let member_ids: Vec<String> = doc.members.iter().map(|m| m.id.clone()).collect();
                report.extend(check_connection(conn, mat, mem, &member_ids, annex));
            }
            None => report.push(
                CheckResult::assess(
                    format!("en1999.ref.conn.material.{}", conn.id),
                    "DIN EN 1999-1-1",
                    ClauseId::new("EN 1999-1-1", "§8", "8"),
                    SubjectRef::new(&conn.id, format!("connections[id={}].materialId", conn.id), loc("Connection", "Anschluss")),
                    loc("Connection material reference", "Anschluss-Materialverweis"),
                )
                .status(crate::document::CheckStatus::Fail)
                .explanation(loc(
                    &format!("Connection '{}' references unknown materialId '{}'.", conn.id, conn.material_id),
                    &format!("Anschluss '{}' verweist auf unbekannte materialId '{}'.", conn.id, conn.material_id),
                ))
                .annex(annex)
                .remedy(Remedy::one_of(
                    SubjectRef::new(&conn.id, format!("connections[id={}].materialId", conn.id), loc("Connection", "Anschluss")),
                    doc.materials.iter().map(|m| m.id.clone()).collect(),
                    loc("Point connection.materialId at an existing material.", "connection.materialId auf vorhandenes Material setzen."),
                ))
                .build(),
            ),
        }
    }

    if doc.fire_scenarios.is_empty() {
        report.push(
            CheckResult::assess(
                "en1999.1-2.empty",
                "DIN EN 1999-1-2",
                ClauseId::new("EN 1999-1-2", "§4", "4"),
                SubjectRef::whole(loc("Fire", "Brand")),
                loc("Fire checks", "Brandschutznachweise"),
            )
            .not_applicable(loc("No fire scenarios claimed.", "Keine Brandszenarien angegeben."))
            .annex(annex)
            .build(),
        );
    }
    for fire in &doc.fire_scenarios {
        let member = doc.members.iter().find(|m| m.id == fire.member_id);
        let section = member.and_then(|m| doc.sections.iter().find(|s| s.id == m.section_id));
        let material = member.and_then(|m| doc.materials.iter().find(|mat| mat.id == m.material_id));
        match (member, section, material) {
            (Some(mem), Some(sec), Some(mat)) => report.push(check_fire(fire, mem, sec, mat, annex)),
            _ => report.push(
                CheckResult::assess(
                    format!("en1999.1-2.fire.{}", fire.id),
                    "DIN EN 1999-1-2",
                    ClauseId::new("EN 1999-1-2", "§4", "4.2"),
                    SubjectRef::new(&fire.id, format!("fireScenarios[id={}].memberId", fire.id), loc("Fire", "Brand")),
                    loc("Fire member reference", "Brand-Bauteilverweis"),
                )
                .status(crate::document::CheckStatus::Fail)
                .explanation(loc(
                    "Fire scenario references a missing member, section or material.",
                    "Brandszenario verweist auf fehlendes Bauteil, Querschnitt oder Material.",
                ))
                .annex(annex)
                .remedy(Remedy::one_of(
                    SubjectRef::new(&fire.id, format!("fireScenarios[id={}].memberId", fire.id), loc("Fire", "Brand")),
                    doc.members.iter().map(|m| m.id.clone()).collect(),
                    loc("Point fire.memberId at an existing member.", "fire.memberId auf vorhandenes Bauteil setzen."),
                ))
                .build(),
            ),
        }
    }

    if doc.fatigue_details.is_empty() {
        report.push(
            CheckResult::assess(
                "en1999.1-3.empty",
                "DIN EN 1999-1-3",
                ClauseId::new("EN 1999-1-3", "§7", "7"),
                SubjectRef::whole(loc("Fatigue", "Ermüdung")),
                loc("Fatigue checks", "Ermüdungsnachweise"),
            )
            .not_applicable(loc("No fatigue details claimed.", "Keine Ermüdungsdetails angegeben."))
            .annex(annex)
            .build(),
        );
    }
    for fat in &doc.fatigue_details {
        let mem = doc.members.iter().find(|m| m.id == fat.member_id);
        report.push(check_fatigue(fat, mem, annex));
    }

    if doc.cold_formed.is_empty() {
        report.push(
            CheckResult::assess(
                "en1999.1-4.empty",
                "DIN EN 1999-1-4",
                ClauseId::new("EN 1999-1-4", "§5", "5.4"),
                SubjectRef::whole(loc("Cold-formed sheeting", "Kaltprofile / Bleche")),
                loc("Cold-formed sheeting checks", "Nachweise für kaltgeformte Bleche"),
            )
            .not_applicable(loc("No cold-formed sheeting in the subject.", "Keine kaltgeformten Bleche im Gegenstand."))
            .annex(annex)
            .build(),
        );
    }
    for sheet in &doc.cold_formed {
        if let Some(mat) = doc.materials.iter().find(|m| m.id == sheet.material_id) {
            report.extend(check_cold_formed(sheet, mat, annex));
        } else {
            report.push(
                CheckResult::assess(
                    format!("en1999.1-4.ref.{}", sheet.id),
                    "DIN EN 1999-1-4",
                    ClauseId::new("EN 1999-1-4", "§5", "5.4"),
                    SubjectRef::new(&sheet.id, format!("coldFormed[id={}].materialId", sheet.id), loc("Sheet", "Blech")),
                    loc("Sheeting material reference", "Blech-Materialverweis"),
                )
                .status(crate::document::CheckStatus::Fail)
                .explanation(loc("Missing material reference for cold-formed sheet.", "Materialverweis für kaltgeformtes Blech fehlt."))
                .annex(annex)
                .remedy(Remedy::one_of(
                    SubjectRef::new(&sheet.id, format!("coldFormed[id={}].materialId", sheet.id), loc("Sheet", "Blech")),
                    doc.materials.iter().map(|m| m.id.clone()).collect(),
                    loc("Point sheet.materialId at an existing material.", "sheet.materialId auf vorhandenes Material setzen."),
                ))
                .build(),
            );
        }
    }

    if doc.shells.is_empty() {
        report.push(
            CheckResult::assess(
                "en1999.1-5.empty",
                "DIN EN 1999-1-5",
                ClauseId::new("EN 1999-1-5", "§5", "5.3"),
                SubjectRef::whole(loc("Shells", "Schalen")),
                loc("Shell buckling checks", "Schalenbeulnachweise"),
            )
            .not_applicable(loc("No shells in the subject.", "Keine Schalen im Gegenstand."))
            .annex(annex)
            .build(),
        );
    }
    for shell in &doc.shells {
        if let Some(mat) = doc.materials.iter().find(|m| m.id == shell.material_id) {
            report.extend(check_shell(shell, mat, annex));
        } else {
            report.push(
                CheckResult::assess(
                    format!("en1999.1-5.ref.{}", shell.id),
                    "DIN EN 1999-1-5",
                    ClauseId::new("EN 1999-1-5", "§5", "5.3"),
                    SubjectRef::new(&shell.id, format!("shells[id={}].materialId", shell.id), loc("Shell", "Schale")),
                    loc("Shell material reference", "Schalen-Materialverweis"),
                )
                .status(crate::document::CheckStatus::Fail)
                .explanation(loc("Missing material reference for shell.", "Materialverweis für Schale fehlt."))
                .annex(annex)
                .remedy(Remedy::one_of(
                    SubjectRef::new(&shell.id, format!("shells[id={}].materialId", shell.id), loc("Shell", "Schale")),
                    doc.materials.iter().map(|m| m.id.clone()).collect(),
                    loc("Point shell.materialId at an existing material.", "shell.materialId auf vorhandenes Material setzen."),
                ))
                .build(),
            );
        }
    }

    report
}

