        1 => Ok(PngTransparency::Grayscale { gray: r.read_u16_le()? }),
        2 => {
            let rr = r.read_u16_le()?;
            let g = r.read_u16_le()?;
            let b = r.read_u16_le()?;
            Ok(PngTransparency::Rgb { r: rr, g, b })
