            semio_s_artifact_stdio_contract::editing::SnapshotEditingCommand::Native(Pdf14XEditorCommand::PageEdit { action, payload }) => {
                crate::editor::page::emit_page_edit(snapshot, action, payload)
            }
            _ => Err(Fault::from("stdio-pdf-native-edit-command-mismatch")),
        }
    },
}

