//#region 🔖️OpText
impl protocol::OpText for ShootingMutation {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        semio_framework_pack_json::from_json_str(line, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|e| store::__rt::field_error(format!("invalid shooting mutation line: {e}")))
    }
    fn print_op(&self) -> String {
        semio_framework_pack_json::to_json_string(self)
    }
}
