                    Some(existing) => existing.diff = absorb_blocks_diff(existing.diff.clone(), &m2.diff),
                    None => modified.push(MdListItemModified { index: *bi, diff: m2.diff.clone() }),
                }
            }
            Some(ItemOrigin::Added(k)) => {
