    let mut cases = vec![MdDiff::default(), MdDiff::between(&a, &b), MdDiff::between(&b, &a), MdDiff::between(&a, &empty), MdDiff::between(&empty, &a)];
    // 🍃 Manual case: `ThematicBreak` diff (never produced by `between`) + `Replace` at a nested
