    let node_diff = FlowNodeDiff { params: Some(params_diff), ..Default::default() };
    SemioFlowDiff { nodes: Some(FlowNodesDiff { modified: vec![NamedModified { key: id.to_string(), diff: node_diff }], ..Default::default() }), edges: None }
}
