/// ✏️ The editor's typed command channel — exactly the one edit `🪟️main`'s `editable_window_kind()`
/// action (`set-node`, contract §2.6) can trigger. `node_id` is the window's own `/`-joined
/// child-index path encoding.
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue)]
pub enum XmlAnyEditorCommand {
    SetNode {
        node_id: String,
        revision: String,
        value: String,
    },
    EditSnapshot {
        event: SnapshotEditEvent,
    },
    /// 🎬️ The navbar example picker's payload — see the `🧵️RetainedRoutes` region below.
    SetActiveExample {
        example_id: String,
    },
}

fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn hex_decode(text: &str) -> Result<Vec<u8>, String> {
    let bytes = text.as_bytes();
    if !bytes.len().is_multiple_of(2) {
        return Err("odd-length hex string".into());
    }
    fn nibble(byte: u8) -> Result<u8, String> {
        match byte {
            b'0'..=b'9' => Ok(byte - b'0'),
            b'a'..=b'f' => Ok(byte - b'a' + 10),
            b'A'..=b'F' => Ok(byte - b'A' + 10),
            _ => Err(format!("non-hex byte 0x{byte:02x}")),
        }
    }
    bytes.chunks_exact(2).map(|pair| Ok((nibble(pair[0])? << 4) | nibble(pair[1])?)).collect()
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn decode_node_id(node_id: &str) -> Result<Vec<usize>, String> {
    if node_id == main::XML_ROOT_NODE_ID {
        return Ok(Vec::new());
    }
    let separator = semio_framework_plugin::TREE_WINDOW_PATH_SEPARATOR;
    let mut segments = node_id.split(separator);
    if segments.next() != Some(main::XML_ROOT_NODE_ID) {
        return Err("xml editor command: node path must begin with exactly one root segment".into());
    }
    segments
        .map(|segment| {
            if segment.is_empty() || segment == main::XML_ROOT_NODE_ID {
                return Err(format!("non-canonical XML node segment {segment:?}"));
            }
            let index = segment.parse::<usize>().map_err(|error| error.to_string())?;
            if index.to_string() != segment {
                return Err(format!("non-canonical XML node index {segment:?}"));
            }
            Ok(index)
        })
        .collect()
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn resolve_node<'a>(root: &'a XmlNode, path: &[usize]) -> Option<&'a XmlNode> {
    let mut node = root;
    for &index in path {
        match node {
            XmlNode::Element { children, .. } => node = children.get(index)?,
            _ => return None,
        }
    }
    Some(node)
}

impl protocol::OpText for XmlAnyEditorCommand {
    fn print_op(&self) -> String {
        match self {
            XmlAnyEditorCommand::SetNode { node_id, revision, value } => {
                format!("set-node node-id={} revision={} value={}", hex_encode(node_id.as_bytes()), hex_encode(revision.as_bytes()), hex_encode(value.as_bytes()))
            }
            XmlAnyEditorCommand::EditSnapshot { event } => format!("snapshot-edit event={}", hex_encode(&<SnapshotEditEvent as protocol::OpBinary>::encode_op(event).expect("snapshot edit event encodes"))),
            XmlAnyEditorCommand::SetActiveExample { example_id } => format!("active-example id={}", hex_encode(example_id.as_bytes())),
        }
    }
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        if let Some(rest) = line.strip_prefix("active-example id=") {
            let example_id = String::from_utf8(hex_decode(rest).map_err(|error| semio_framework_diagnostic::TextError::new(format!("xml editor command: invalid example hex {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?)
                .map_err(|error| semio_framework_diagnostic::TextError::new(format!("xml editor command: invalid example utf8 {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
            return Ok(XmlAnyEditorCommand::SetActiveExample { example_id });
        }
        if let Some(rest) = line.strip_prefix("snapshot-edit event=") {
            let bytes = hex_decode(rest).map_err(|error| semio_framework_diagnostic::TextError::new(format!("xml editor command: invalid snapshot edit hex {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
            let event = <SnapshotEditEvent as protocol::OpBinary>::decode_op(&bytes).map_err(|error| semio_framework_diagnostic::TextError::new(format!("xml editor command: invalid snapshot edit {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
            return Ok(XmlAnyEditorCommand::EditSnapshot { event });
        }
        let rest = line.strip_prefix("set-node ").ok_or_else(|| semio_framework_diagnostic::TextError::new(format!("xml editor command: unknown line {line:?}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
        let mut node_id = None;
        let mut revision = None;
        let mut value = None;
        for token in rest.split(' ') {
            let (key, raw) = token.split_once('=').ok_or_else(|| semio_framework_diagnostic::TextError::new(format!("xml editor command: bad token {token:?}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
            let decoded = String::from_utf8(hex_decode(raw).map_err(|error| semio_framework_diagnostic::TextError::new(format!("xml editor command: invalid field hex {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?)
                .map_err(|error| semio_framework_diagnostic::TextError::new(format!("xml editor command: invalid field utf8 {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
            match key {
                "node-id" => node_id = Some(decoded),
                "revision" => revision = Some(decoded),
                "value" => value = Some(decoded),
                _ => {}
            }
        }
        let (node_id, revision, value) =
            node_id.zip(revision).zip(value).map(|((node_id, revision), value)| (node_id, revision, value)).ok_or_else(|| semio_framework_diagnostic::TextError::new("xml editor command: missing node-id/revision/value", semio_framework_diagnostic::TextSpan::at(1, 1)))?;
        Ok(XmlAnyEditorCommand::SetNode { node_id, revision, value })
    }
}

impl protocol::OpBinary for XmlAnyEditorCommand {
    /// 🎯️ The app-owned retained routes this command channel carries — the join key
    /// `AppActionRegistry::validate_tool_job_rows` demands an exact owner-local proof for. The `TreeWindowKit`
    /// mints `set-node`, but only this editor can reduce it into its own mutation, so it is an
    /// app-owned route exactly like the example switch.
    const TOOL_JOB_IDS: &'static [&'static str] = XML_ANY_COMMAND_TOOL_IDS;

    fn encode_op(&self) -> Result<Vec<u8>, protocol::ProtocolError> {
        Ok(<Self as protocol::OpText>::print_op(self).into_bytes())
    }
    fn decode_op(bytes: &[u8]) -> Result<Self, protocol::ProtocolError> {
        let line = String::from_utf8(bytes.to_vec()).map_err(|error| protocol::ProtocolError::Malformed { what: "xml editor command utf8", offset: 0, detail: error.to_string() })?;
        <Self as protocol::OpText>::parse_op(&line).map_err(|error| protocol::ProtocolError::Malformed { what: "xml editor command", offset: 0, detail: error.to_string() })
    }
}
