fn sqlite_snapshot_program_declared_json_preserves_full_unsigned64_transport(){
    let base=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../🏅️standards/🔖️1/🪆️subsets/✳️any");
